SELECT 'moj-all-verified-judgments-review-002-chunk-176' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b44c14fe-5947-5f4b-aab6-6a7058b856b5","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -مستثمر -استرداد ثمن أجره مدفوعة لتعرض العقار لإلزالة -مراعاة اختاف األجرة الختاف املوسم -تقدير األجرة عن طريق قسم اخلبراء -إلزام املدعى عليه بإعادة جزء من ثمن األجرة -صرف النظر عن غير ذلك من طلبات للمدعى.","document_number":"34231967","case_number":"33644605","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/5","year":"1434","subject":"عقد -إجارة -مستثمر -استرداد ثمن أجره مدفوعة لتعرض العقار لإلزالة -مراعاة اختاف األجرة الختاف املوسم -تقدير األجرة عن طريق قسم اخلبراء -إلزام املدعى عليه بإعادة جزء من ثمن األجرة -صرف النظر عن غير ذلك من طلبات للمدعى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/6/5 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34231967 :‬‬\n                   ‫َر ْق ُم الدعوى‪33644605 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34281939‬تاريخه‪1434/7/29 :‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬مســتثمر ‪ -‬اســترداد ثمــن أجــره مدفوعــة لتعــرض‬\n‫العقــار لإلزالــة ‪ -‬مراعــاة اختــاف األجــرة الختــاف املوســم ‪ -‬تقديــر‬\n‫األجــرة عــن طريــق قســم اخلبــراء ‪ -‬إلــزام املدعــى عليــه بإعــادة جــزء‬\n‫مــن ثمــن األجــرة ‪ -‬صــرف النظــر عــن غيــر ذلــك مــن طلبــات للمدعــى‪.‬‬\n\n\n\n\n‫قــال املوفــق يف املغنــي ‪ »:28/8‬فــإن كان أجــر املــدة متســاويا فعليــه بقــدر‬\n‫مــا مضــى إن كان قــد مضــى النصــف فعليــه نصف األجــر وإن كان قد‬\n‫مضــى الثلــث فعليــه الثلــث كمــا يقســم الثمــن علــى املبيــع املتســاوي‬\n‫وإن كان مختلفــا كــدار أجرهــا يف الشــتاء أكثــر مــن أجرهــا يف‬\n‫الصيــف وأرض أجرهــا يف الصيــف أكثــر مــن الشــتاء أو دار لهــا موســم‬\n‫كــدور مكــة رجــع تقوميــه إلــى أهــل اخلبــرة ويقســط األجــر املســمى‬\n‫علــى حســب قيمــة املنفعــة كقســمة الثمــن علــى األعيــان املختلفــة يف‬\n                      ‫البيــع»‪ ،‬وينظــر أيضــا شــرح منتهــى اإلرادات ‪.108/5‬‬\n\n\n\n\n                                                                                     ‫‪118‬‬\n\f      ‫ادعــى املدعــي بدعــوى ضــد املدعــى عليــه بأنــه اســتأجر منــه عقــار ًا‬\n      ‫عشــر ســنوات يدفــع الثمــن بدايــة كل عــام ويف العــام الثانــي وبعدمــا‬\n      ‫دفــع األجــرة أول العــام صــدر قــرار بإزالــة املبنــى خــال العــام الثانــي‬\n      ‫وقبــل موســم احلــج وألنــه ال يســتفاد مــن املبنــي حقيقــة إال يف موســم احلــج‬\n      ‫وألن ثمــن األجــرة كان مرتفعــا لطــول املــدة فقــد طلــب إعــادة مــا ســلمه‬\n      ‫مــن ثمــن أجــرة الســنة الثانيــة وإعــادة تقديــر أجــرة الســنة األولــى التــي‬\n      ‫اســتفاد فيهــا مــن العقــار قبــل إزالتــه ورد لــه الفــارق بينــه وبــن األجــرة‬\n      ‫املســلمة‪ ،‬أقــر املدعــى عليــه بالعقــد والثمــن والواصــل وتاريــخ اإلخــاء‬\n      ‫وألن االتفــاق علــى األجــرة كان ســنويا فقــد طلــب تســليمه بقيــة األجــرة‬\n      ‫املســتحقة للعــام الثانــي وصــرف النظــر عــن دعــوى املدعــي‪ ،‬جــرى بعــث‬\n      ‫املعاملــة لهيئــة النظــر لتقديــر أجــرة العقــار للمــدة من‪1433/1/1‬ه ـ حتــى‬\n      ‫‪1433/7/30‬ه ـ حســب األجــرة املدونــة يف العقــد مــع مالحظــة املواســم‬\n      ‫املعتبــرة وأثرهــا يف األجــرة فــوردت بتقديرهــا بأربعمئــة و عشــرين ألــف‬\n      ‫ريــال ‪ -‬لتصــادق الطرفــن علــى مقــدار املبلــغ املدفــوع مــن أجــرة عــام‬\n      ‫‪1433‬ه ـ وأنــه مليــون وســتمائة ألــف ريــال كمــا تصادقــا علــى أن املــدة‬\n      ‫التــي بقــي فيهــا املدعــي أصالــة يف العقــار وعلــى تاريــخ اإلخــاء وفصــل‬\n      ‫التيــار الكهربائــي وألن هيئــة النظــر قــدرت أجــرة هــذه املــدة بأربعمائــة‬\n      ‫وعشــرين ألــف ريــال وألن عقــد اإلجــارة عقــد الزم للطرفــن وألن أجــرة‬\n      ‫العقــار مبكــة تختلــف حســب املواســم فأجرتهــا يف احلــج ورمضــان‬\n      ‫تختلــف عــن باقــي الســنة لــذا فيرجــع تقديــر األجــرة ألهــل اخلبــرة‪ ،‬قــال‬\n      ‫املوفــق يف املغنــي ‪ »:28/8‬فــإن كان أجــر املــدة متســاويا فعليــه بقــدر مــا‬\n\n‫‪119‬‬\n\f‫مضــى إن كان قــد مضــى النصــف فعليــه نصــف األجــر وإن كان قــد‬\n‫مضــى الثلــث فعليــه الثلــث كمــا يقســم الثمــن علــى املبيــع املتســاوي وإن‬\n‫كان مختلفــا كــدار أجرهــا يف الشــتاء أكثــر مــن أجرهــا يف الصيــف‬\n‫وأرض أجرهــا يف الصيــف أكثــر مــن الشــتاء أو دار لهــا موســم كــدور‬\n‫مكــة رجــع تقوميــه إلــى أهــل اخلبــرة ويقســط األجــر املســمى علــى حســب‬\n‫قيمــة املنفعــة كقســمة الثمــن علــى األعيــان املختلفــة يف البيــع»‪ ،‬ينظــر‬\n‫أيضــا شــرح منتهــى اإلرادات ‪108/5‬وبعــد خصــم األجــرة التــي قدرتهــا‬\n‫هيئــة النظــر للمــدة التــي بقــي فيهــا املدعــي يف العقــار مــن املبلــغ الــذي‬\n‫دفعــه املدعــي مــن أجــرة عــام ‪1433‬ه ـ فقــد حكمــت احملكمــة علــى‬\n‫املدعــى عليــه أصالــة بــأن يدفــع للمدعــي مليــون ومائــة وثمانــن ألف ريال‬\n‫ورد دعــوى املدعــي بإعــادة تقديــر أجــرة عــام ‪1432‬هــ‪ ،‬بعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــي وكالــة القناعــة وقــرر املدعــى عليــه عــدم‬\n‫القناعــة فأفهــم بالتعليمــات‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪....................‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33644605‬وتاريــخ‬\n‫‪ 1433/11/09‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331978291‬وتاريــخ‬\n‫‪ 1433/11/09‬ه ـ يف يــوم الثالثــاء املوافــق‪ 1433/11/23‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪09 : 30‬وفيهــا حضــر ‪...........................‬بالســجل املدنــي‬\n‫رقم………………‪..‬بوكالتــه عــن …………………أصالــة عــن‬\n‫نفســه وبصفتــه مديــر وشــريك لشــركة ‪ .......‬احملــدودة بالوكالــة‬\n                                                                                       ‫‪120‬‬\n\f      ‫الصــادرة مــن كتابــة العــدل الثانية مبكــة املكرمة برقم ‪5106/4935‬‬\n      ‫يف ‪1433/2/3‬ه ـ والتــي تخولــه املدافعــة واملرافعــة وحضــور اجللســات‬\n      ‫واإلقــرار والصلــح ‪...‬الــخ وادعــى علــى احلاضــر معــه ‪ .......‬بالســجل املدنــي‬\n      ‫رقــم ‪ .......‬بوكالتــه عــن ‪ .......‬بالوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بغــرب مكــة برقــم ‪ 341732‬يف ‪1434/1/3‬ه ـ والتــي تخولــه‬\n      ‫إقامــة الدعــاوى واملرافعــة واملدافعــة والصلــح والتنــازل ‪..‬الــخ قائــا يف‬\n      ‫دعــواه عليــه لقــد اســتأجر موكلــي مــن املدعــى عليــه العمــارة الواقــع‬\n      ‫بحــي ‪ ...‬ملــدة عشــر ســنني بــدأ بتاريــخ ‪1432/01/01‬ه ـ وتنتهــي يف‬\n      ‫‪1441/12/30‬ه ـ بأجــرة ســنوية مليونــن ومائــة ألــف ريــال وقــد دفــع‬\n      ‫موكلــي أجــرة عــام ‪1432‬ه ـ كاملــة وانتفع بالعــن يف ذلك العام ثم دفع‬\n      ‫مــن أجــرة عــام ‪1433‬ه ـ مبلــغ وقــدره مليون وســتمائة وعشــرون ألف ريال‬\n      ‫فقــط ثــم دخــل العقــار يف مشــروع توســعة الســاحات الشــمالية وتقــررت‬\n      ‫إزالــة املبنــى وفصــل التيــار الكهربائــي عنــه يف ‪1433/8/1‬ه ـ ورفــع‬\n      ‫موكلــي يــده عــن املبنــى يف ذلــك التاريــخ وألن موكلــي لــم ينتفــع بالعــن‬\n      ‫يف ذلــك العــام ألن العقــار ال ينتفــع بــه إال يف موســم احلــج فقــط ويطلــب‬\n      ‫إلــزام املدعــى عليــه أصالــة بإعــادة مــا اســتلمه مــن أجــرة ذلــك العــام مبلــغ‬\n      ‫وقــدره مليــون وســتمائة وعشــرون ألــف ريالكمــا أن موكلــي إمنــا وافــق‬\n      ‫علــى أجــرة املبنــى املرتفعــة بســبب طــول املــدة وألن موكلــي لــم ينتفــع‬\n      ‫منــه إال لســنه واحــده فموكلــي يطلــب إعــادة تقديــر أجــرة الســنة التــي‬\n      ‫انتفــع بهــا وإلــزام املدعــى عليــه بدفــع الباقــي بعــد التقديــر هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليــه وكالــة عــن دعــوى املدعــي أجــاب قائــا صحيــح‬\n      ‫ان موكلــي اجــر العقــار علــى املدعــي أصالــة الواقــع بالتيســير ملــدة‬\n      ‫عشــر ســنني تبــدأ يف ‪1432/1/1‬ه ـ وتنتهــي يف‪1441/12/30‬ه ــبأجرة‬\n\n\n‫‪121‬‬\n\f‫ســنوية مليونــن ومائــة الــف ريــال وقــد اســتلم موكلــي أجــرة عام‪1432‬هـ‬\n‫كاملــة وأمــا أجــرة عام‪1433‬ه ـ فــا صحــة ملــا ذكــره املدعــي وكالــة‬\n‫فــإن موكلــه لــم يســلم ملوكلــي مليــون وســتمائة وعشــرين الــف‬\n‫ريــال وإمنــا ســلم ملوكلــي خمســمائة الــف ريــال فقــط وكان التســليم‬\n‫مبوجــب شــيك مســحوب علــى مصــرف ‪ ...‬يف شــهر جمــادى الثانيــة‬\n‫مــن عــام ‪1433‬ه ــوقد صــرف موكلــي هــذا الشــيك واســتلم املبلــغ ثــم‬\n‫دخــل املوقــع يف مشــروع توســعة الســاحات الشــمالية ومت فصــل التيــار‬\n‫الكهربائــي بتاريــخ ‪1433/8/1‬ه ــوألنأجرة كامــل العــام ‪1433‬ه ـ هــي‬\n‫مليونــان ومائــة ألــف ريــال ولــم يســتلم موكلــي مــن أجــرة ذلــك العــام‬\n‫إال خمســمائة ألــف ريــال وقــد انتفــع املدعــى عليــه بالعقــار ملــدة ســبعة‬\n‫أشــهر كاملــة مــن ‪1433/1/1‬ه ـ حتــى ‪1433/7/30‬ه ـ وألن أجــرة هــذه‬\n‫املــدة هــي مبلــغ وقــدره مليــون وأربعمائــة ألــف ريــال لــذا فــإن موكلــي‬\n‫يطلــب إلــزام املدعــى عليــه أصالــة بدفــع هــذا املبلــغ املتبقــى تســعمائة‬\n‫ألــف ريــال وأمــا ماذكــره املدعــي أصالــة مــن طلــب إعــادة تقديــر أجــرة‬\n‫العقــار الســنوية وعلــل ذلــك بأنــه وافــق عــن هــذه األجــرة بســببط وال ملــدة‬\n‫وانــه لــم ينتفــع مــن العقــار إال لعــام وســبعة أشــهر فــإن هــذا الطلــب غيــر‬\n‫صحيــح ألن بــن املدعــي أصالــة وموكلــي عقــد مذكــور فيــه أجــرة‬\n‫كل ســنة وأطلــب صــرف النظــر عــن هــذا الطلــب ألنــه غيــر صحيــح‬\n‫هــذه إجابــة موكلــي وبعــرض ذلــك علــى املدعــي وكالــة قــال الصحيــح‬\n‫مــا جــاء يف دعــوى موكلــي وموكلــي ســلم مليــون وســتمائة وعشــرين‬\n‫الــف ريــال مــن أجــرة عــام ‪1433‬ه ـ للمدعــى عليــه أصالــة حيــث ســلمه‬\n‫ثــاث شــيكات علــى مصــرف ‪ ...‬األول مببلــغ ســبعمائة وســبعني الــف‬\n‫ريــال والثانــي مبلــغ خمســمائة الــف ريــال والثالــث مببلــغ عشــرين الــف‬\n\n\n                                                                                        ‫‪122‬‬\n\f      ‫ريــال كمــا ان موكلــي اتفــق مــع املدعــى عليــه أصالة يف املادة السادســة‬\n      ‫مــن العقــد علــى إن يقــوم موكلــي بتأثيــث الفنــدق مببلــغ ثمامنائــة ألــف‬\n      ‫ريــال ويخصــم هــذا املبلــغ منأجــرة عام‪1432‬ه ـ و‪1433‬ه ـ علــى النحــو‬\n      ‫اآلتــي أوال ‪ /‬أربعمائــة وســبعني ألــف ريــال مــن أجــرة عام‪1432‬ه ــثانيا‪/‬‬\n      ‫ثالثمائــة وثالثــن ألــف ريــال مــن أجرةعام‪1433‬ه ــوبذا يتبــن لكــم أن‬\n      ‫موكلــي دفــع للمدعــى عليــه أصالــة مليــون وســتمائة وعشــرين ألــف‬\n      ‫ريــال وأمــا مــا ذكــره املدعــى عليــه مــن أجــرة الفترةمن‪1433/1/1‬ه ـ‬\n      ‫حتــى ‪1433/7/30‬ه ــهي مليــون وأربعمائــة ألــف ريــال فــا صحــة لــه الن‬\n      ‫هــذه الفتــرة ليــس لهــا أجــرة يف احلقيقــة الن العمــارة ال يســتفاد منهــا إال‬\n      ‫يف موســم احلــج فقــط وكامــا ألجــرة هــي ملوســم احلــج فقــط وأمــا باقــي‬\n      ‫العــام فليــس لــه أجــرة ‪ .‬هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫وكالــة قــال إننــي راجعــت موكلــي وتبــن أن مــا ذكــره املدعــي وكالــة‬\n      ‫بعضــه صحيــح وبعضــه غيــر صحيــح فالصحيــح منــه أن موكلــي اســتلم‬\n      ‫مــن املدعــي وكالــة مــن أجــرة عــام ‪1433‬ه ـ مبلــغ وقــدره مليون وســتمائة‬\n      ‫ألــف ريــال فقــط علــى النحــو اآلتــي ‪ -:‬اوال)‪ -:‬ســبعمائة وســبعون ألــف‬\n      ‫ريــال مبوجــب شــيك ‪ .‬ثانيــا)‪ -:‬خمســمائة ألــف ريــال مبوجــب شــيك‬\n      ‫أيضــا وهــو املبلــغ الــذي ذكرتــه يف اجللســة املاضيــة ‪ .‬ثالثــا)‪ -:‬ثالثمائــة‬\n      ‫وثالثــون ألــف ريــال وهــو اجلــزء الثانــي مــن ثمــن األثــاث الــذي اشــتراه‬\n      ‫املدعــي أصالــة بثمامنائــة ألــف ريــال واملنصــوص عليــه يف املــادة السادســة‬\n      ‫مــن العقــد وأمــا مــا ذكــر املدعــي مــن أن موكلــي اســتلم عشــرين ألــف‬\n      ‫ريــال فهــذا غيــر صحيــح ألن هــذا املبلــغ ليــس مــن األجــرة وإمنــا هــو داللــه‬\n      ‫دفعهــا املدعــي أصالــة ملوكلــي هكــذا قــرر وبعــرض ذلــك علــى املدعــى‬\n      ‫وكالــة قــال إن موكلــي يكتفــي بهــذا املبلــغ الــذي أقــر بــه املدعــى‬\n\n\n‫‪123‬‬\n\f‫عليــه وال يطالــب مببلــغ العشــرين ألــف ريــال الــذي أنكــره املدعــى عليــه‬\n‫وكالــه وبــذا يكــون أجمالــي مــا ســلمه موكلــي للمدعــى عليــه أصالــة‬\n‫مــن أجــرة عــام ‪1433‬ه ـ مبلــغ مليــون وســتمائة ألــف ريــال فقــط وموكلي‬\n‫يطلــب الــزام املدعــى عليــه أصالــة بدفعــة هكــذا قــرر ‪ ،‬فطلبــت مــن‬\n‫املدعــي وكالــة عقــد اإلجــارة فأبــرز عقــد ًا مــن مطبوعــات شــركة ‪...‬‬\n‫وهــذا نصــه ‪ -:‬احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‬\n‫وبعــد ففــي يــوم اخلميــس‪1432/5/17 :‬ه ـ املوافــق‪2010/4/21 :‬م بعــون‬\n                                         ‫اهلل وتوفيقــه مت االتفــاق بــن كل مــن ‪:‬‬\n‫‪-‬األستاذ ‪ ........................../‬سعودي بالسجل املدني رقم ‪.......................‬‬\n                        ‫وهــو (املؤجــر) ويشــار إليــه يف هذا العقد بالطرف األول‪.‬‬\n‫‪ --‬شــركة ‪ ..................‬وميثلهــا يف هــذا العقــد األســتاذ‪...................... /‬‬\n‫ســعودي بالســجل املدنــي رقــم ‪ ...........................‬بصفتــه مديــر ًا عام ـ ًا‬\n ‫للشــركة وهــو املســتأجر ويشــار إليــه يف هــذا العقــد بالطــرف الثانــي‪.‬‬\n                                                                                      ‫متهيد‪:‬‬\n‫ملــا كان الطــرف األول ميلــك منفعــة العقــار الواقــع يف ‪ ...‬أمــام احملكمــة‬\n‫القدميــة واململــوك لوقــف ‪ ....................‬مبوجــب الصــك الصــادر مــن‬\n‫محكمــة مكــه املكرمــه برقــم (‪)3/383‬وتاريــخ ‪ 1367/8/3‬ه ــو‬\n‫ذلــك بصفتــه مســتثمر ًا للوقــف مبوجــب صــك اإلذن باالســتثمار الصــادر‬\n‫مــن احملكمــه العامــه مبكــه املكرمــه برقــم ‪ 2/100/33‬بتاريــخ‬\n‫‪ 1430/1/21‬ه ـ واملكــون مــن دور أرضــي ‪ +‬بــدروم ‪ +‬دور ميزانــن‪+‬‬\n‫دور مطعــم‪ +‬دور خدمــات ‪ +‬تســعة ادوار متكــررة ‪ +‬دور أخيــر ورغــب‬\n‫يف تأجيــر املبنــى ملــدة طويلــة لــذا فقــد انعقــدت إرادة الطرفــن علــى‬\n                                                       ‫التأجيــر وفــق البنــود التاليــة ‪:‬‬\n\n\n                                                                                               ‫‪124‬‬\n\f                     ‫أوالً‪ :‬تعتبر املقدمة والتمهيد جزء ًا ال يتجزأ من هذا العقد‪.‬‬\n      ‫ثاني ـاً‪ :‬تكــون مــدة عقــد اإليجــار عشــر ســنوات اعتبــار مــن تاريــخ‬\n                                       ‫‪1432/1/1‬هــ‪ .‬وحتــى ‪1441/12/30‬هــ‪.‬‬\n      ‫ثالث ـاً‪ :‬تكــون القيمــة اإليجاريــة الســنوية للعقــار هــي (‪)2.100000‬‬\n      ‫تســتحق دفعــة واحــدة ويف حالــة تأخــر الطــرف الثانــي عــن دفــع اإليجــار‬\n      ‫املقــرر ملــدة شــهر عــن موعــد حلولــه فيعتبــر عقــد اإليجــار الغيــا ومــن‬\n      ‫حــق الطــرف األول اســتالم عمارتــه حــا ًال علم ـ ًا بــأن الشــيك الصــادر‬\n      ‫مــن الطــرف الثانــي هــو االســاس بالتاريــخ ويكــون الشــيك مصدق ـ ًا‬\n      ‫مــن البنــك ويكــون تاريخــه هــو املعتبــر أو بإيــداع حلســاب الطــرف األول‬\n                                           ‫مبوجــب احلســاب رقــم (‪ )........‬بنــك ‪......‬‬\n      ‫رابع ـاً‪ :‬قــرر الطــرف الثانــي اســتالمه للعقــار بحالــة جيــدة وكان‬\n      ‫االســتالم بتاريــخ ‪1431/11/20‬ه ـ كمــا قــرر الطــرف األول تنازلــه عــن‬\n      ‫القيمــة االيجاريــة للفتــرة مــا بــن اســتالم العقــار ونفــاذ العقــد ولــه حــق‬\n                                                                  ‫االنتفــاع يف هــذه املــده‪.‬‬\n      ‫خامسـاً‪ :‬قــرر الطــرف األول اســتالمه مــن الطــرف الثانــي كامــل ايجار‬\n      ‫الســنه األولــى التــي تبــدأ مــن ‪1432/1/1‬ه ـ حتــى ‪1432/12/30‬ه ـ‬\n      ‫وقــدره (مليونــن ومائــة ألــف ريــال فقــط) منهــا مادفــع شــيكات ومنهــا‬\n      ‫مــا دفــع نقــد ًا ومنهــا مــا خصــم مــن قيمــة التأثيث كما ذكر يف سادسـ ًا‬\n      ‫فقــرة (أ)‪ ،‬كمــا يقــرر الطــرف االول خلــو العقــار مــن أي التزامــات‬\n      ‫أخــرى أو حقــوق ألي أحــد أو مخالفــات بالبلديــه‪ ،‬ويف حالــة ظهــور أي‬\n      ‫مــن ذلــك فإنــه يجــب علــى الطــرف األول إزالتهــا دون أي تكلفــة ماديــة‬\n                                                                    ‫علــى الطــرف الثانــي‪.‬‬\n      ‫سادس ـاً‪ :‬أ‪ -‬علــى الطــرف األول تأثيــث الفنــدق مــن ســرر ومراتــب‬\n\n\n‫‪125‬‬\n\f‫ومكيفــات وتلفزيونــات وثالجــات وقــد فــوض الطــرف االول الطــرف‬\n‫الثانــي بالتأثيــث ويكــون مبلــغ التأثيــث هــو ‪( 800000‬ثمامنائــة ألــف‬\n‫ريــال فقــط) يخصــم مــن مبلــغ االيجــار للســنة األولــى التــي تبــدأ مــن‬\n‫‪1433/1/1‬ه ـ حتــى ‪1432/12/30‬ه ـ مبلــغ وقــدره ‪( 470000‬أربعمائــة‬\n‫وســبعون ألــف ريــال فقــط ) واملتبقــي وقــدره ‪( 330000‬ثالثمائــة وثالثون‬\n‫ألــف ريــال فقــط) يخصــم مــن ايجــار الســنه الثانــي هــو التــي تبــدأ مــن‬\n‫‪1433/1/1‬ه ـ حتــى ‪1433/12/30‬ه ـ ويكــون املتبقــي مــن ايجــار‬\n‫الســنه الثانيــه املذكــوره ‪ 1770000‬ريــال (مليــون وســبعمائة وســبعون‬\n‫ألــف ريــال فقــط ) بعــد أن مت إلغــاء احملضــر الســابق اخلــاص بالتأثيــث‬\n‫بعــد أن مت تخفيــض قيمــة التأثيــث مــن (مليــون وثالثمائــة وأحــد عشــر‬\n‫ألــف ريــال ) إلــى (ثمامنائــة ألــف ريــال فقــط ) ويكــون التأثيــث املطلــوب‬\n‫مــن الطــرف الثانــي كمــا هــو مذكــور يف بدايــة البنــد سادس ـ ًا وإذا‬\n‫رغــب الطــرف الثانــي إحضــار أثاثـ ُا إضافيـ ًا فــا مانــع علــى أن يحــق لــه‬\n‫ســحبه مــع نهايــة العقــد ويراعــي عنــد تســليم املبنــى مــدة اإلســتهالك‬\n          ‫للتأثيــث املذكــور ويكــون قبولــه للتأثيــث يف حالتــه الراهنــه‪.‬‬\n‫ب‪ -‬يتــم دفــع مبلــغ وقــدره ‪( 770000‬ســبعمائة وســبعون ألــف ريــال فقط)‬\n‫يف ‪ 1432/9/15‬ه ـ وهــي دفعــه مقدمــه مــن الســنه الثانيــه التــي تبــدأ يف‬\n‫‪1433/1/1‬ه ـ ويتبقــى مليــون ريــال تدفــع يف ‪1433/1/1‬ه ـ لهــذه الســنه‬\n                                                                           ‫فقط‪.‬‬\n‫ســابعاً‪ -:‬اتفــق الطرفــان علــى إن يكــون الدكاكــن االثنــن الصغيــره‬\n‫وغرفــة احلــارس الصغيــره التــي باجلهــة اجلنوبيــة ليســت يف اإليجــار‬\n‫وكذلــك البــدروم الــذي مدخلــه مــن اجلهــة الشــماليه مبدخــل خــاص ‪.‬‬\n‫ثامنـاً‪ :‬يجــوز للطــرف الثانــي تأجيــر العقــار محــل العقــد ملــن يشــاء مــدة‬\n\n\n                                                                                     ‫‪126‬‬\n\f                           ‫العقــد بــدون الرجــوع للطــرف األول أو أخــذ موافقتــه ‪.‬‬\n      ‫تاســع ًا ‪ :‬يســري هــذا العقــد علــى الطرفــن وورثتهمــا الشــرعيني طيلــة‬\n                      ‫مدتــه وال يســقط بوفــاة أحدهمــا بــل يكــون ملزمــا لهمــا‪.‬‬\n      ‫عاشــر ًا أقــر الطرفــان مبــا ورد بهــذا العقــد و إطالعهمــا علــى مــا جــاء‬\n      ‫فيــه إطالعــا ً نافيـ ًا للجهالــة والغــرر كمــا يلغــي هــذا العقــد كل ماســواه‬\n                                                                  ‫مــن العقــود الســابقه‪.‬‬\n      ‫احلــادي عشــر ‪ :‬يتكــون هــذا العقــد مــن مقدمــة ومتهيــد و أحــد عشــر‬\n      ‫بنــد مرتبطــات ببعضهــا وقــد حــرر هــذا العقــد مــن نســختني بيــد كل‬\n      ‫مــن الطرفــن نســخة منهــا‪ .‬ا‪.‬ه ـ ‪ ،‬وبعــرض هــذا العقــد علــى املدعــى‬\n      ‫عليــه وكالــة صــادق عليــه وقــال إن املــادة العاشــرة مــن العقــد تــدل علــى‬\n      ‫أن األجــرة املتفــق عليــه هــي برضــا الطرفــن وليــس فيهــا غــرر وال غــن‬\n      ‫وألن أجــرة املــدة مــن ‪1433/1/1‬ه ـ حتــى ‪1433/7/30‬ه ـ هــي مليــون‬\n      ‫وأربعمائــة ألــف ريــال وألن موكلــي اســتلم مــن املدعــي أصالــة مليــون‬\n      ‫وســتمائة ألــف ريــال لــذا فــإن املتبقــي للمدعــي أصالــة مائتــي ألــف ريــال‬\n      ‫وموكلــي مســتعد بدفــع هــذا املبلــغ للمدعــي أصالــة ألنــه حقــه هكــذا‬\n      ‫قــرر ‪،‬وعليــه فقــد جــرى بعــث املعاملــة لهيئــة النظــر لتقديــر أجــرة العقــار‬\n      ‫للمــدة مــن ‪1433/1/1‬ه ـ حتــى ‪1433/7/30‬ه ـ حســب األجــرة املدونــه‬\n      ‫يف العقــد مــع مالحظــة املواســم املعتبــرة وأثرهــا يف األجــرة وذلــك‬\n      ‫بخطابــي رقــم ‪ 331978291‬يف ‪1434/4/24‬ه ـ فــوردت اإلفــادة مــن‬\n      ‫هيئــة النظــر باخلطــاب رقــم ‪ 331978291‬يف ‪1434/05/08‬ه ـ وهــذا‬\n      ‫نــص احلاجــة منــه «تقــدر اجــرة العقــار للفتــرة مــن ‪1433/1/1‬ه ـ حتــى‬\n      ‫‪1433/07/30‬ه ـ مبلــغ وقــدره ( ‪ 420.000‬فقــط اربعمائــة و عشــرون‬\n      ‫الــف ريــال ال غيــر ) ا‪.‬ه ـ « ثــم قــرر الطرفــان أن بينهمــا محاولــة صلــح‬\n\n\n‫‪127‬‬\n\f‫وطلبــا امهالهمــا لذلــك ثــم يف جلســة أخــرى حضــر الطرفــان وكالــة‬\n‫وقــررا أنهمــا وموكليهمــا لــم يتوصــا إلــى صلــح وقــرر املدعــي وكالــة‬\n‫أن موكلــي يطالــب أيضــا إعــادة تقديــر أجــرة عــام ‪1432‬ه ـ وهــي الســنة‬\n‫التــي اســتفادتها بالكامــل ألن موكلــي إمنــا وافــق علــى األجــرة الســنوية‬\n‫املرتفعــة واملدونــة يف العقــد بســبب طــول املــدة ولكــن بعــد اإلزالــة فــان‬\n‫موكلــي يــرى أن هــذه األجــرة مرتفعــة وهــو يطلــب إعــادة تقديــر أجــرة‬\n‫تلــك الســنة هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال‬\n‫إن العقــد بــن الطرفــن ملــزم لهمــا واألجــرة منصــوص فيــه أنهــا ســنوية‬\n‫والعقــد برضــي الطرفــن هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وبعــد االطــاع علــى عقــد اإلجــارة بــن الطرفــن ومصادقتهمــا‬\n‫عليــه وألن الطرفــن تصادقــا علــى مقــدار املبلــغ املدفــوع مــن أجــرة عــام‬\n‫‪1433‬ه ـ وأنــه مليــون وســتمائة ألــف ريــال كمــا تصادقــا علــى أن املــدة‬\n‫التــي بقــي فيهــا املدعــي أصالــة يف العقــار وعلــى تاريــخ اإلخــاء وفصــل‬\n‫التيــار الكهربائــي وألن هيئــة النظــر قــدرت أجــرة هــذه املــدة بأربعمائــة‬\n‫وعشــرين ألــف ريــال وألن عقــد اإلجــارة عقــد الزم للطرفــن وألن أجــرة‬\n‫العقــار مبكــة تختلــف حســب املواســم فأجرتهــا يف احلــج ورمضــان‬\n‫تختلــف عــن باقــي الســنة ولــذا فيرجــع تقديــر األجــرة ألهــل اخلبــرة قــال‬\n‫املوفــق يف املغنــي ‪ ( 28/8‬فــإن كان أجــر املــدة متســاويا فعليــه بقــدر مــا‬\n‫مضــى إن كان قــد مضــى النصــف فعليــه نصــف األجــر وإن كان قــد‬\n‫مضــى الثلــث فعليــه الثلــث كمــا يقســم الثمــن علــى املبيــع املتســاوي وإن‬\n‫كان مختلفــا كــدار أجرهــا يف الشــتاء أكثــر مــن أجرهــا يف الصيــف‬\n‫وأرض أجرهــا يف الصيــف أكثــر مــن الشــتاء أو دار لهــا موســم كــدور‬\n‫مكــة رجــع تقوميــه إلــى أهــل اخلبــرة ويقســط األجــر املســمى علــى حســب‬\n\n\n                                                                                     ‫‪128‬‬\n\f      ‫قيمــة املنفعــة كقســمة الثمــن علــى األعيــان املختلفــة يف البيــع ) ينظــر‬\n      ‫أيضــا شــرح منتهــى اإلرادات البــن النجــار ‪108/5‬وبعــد خصــم األجــرة‬\n      ‫التــي قدرتهــا هيئــة النظــر للمــدة التــي بقــي فيهــا املدعــي يف العقــار مــن‬\n      ‫املبلــغ الــذي دفعــه املدعــي مــن أجــرة عــام ‪1433‬ه ـ فقــد حكمــت علــى‬\n      ‫املدعــى عليــه أصالــة بــأن يدفــع للمدعــي مليــون ومائــة وثمانــن ألف ريال‬\n      ‫ورددت دعــوى املدعــي بإعــادة تقديــر أجرة عام ‪1432‬هـ وبعرض احلكم‬\n      ‫علــى الطرفــن قــرر املدعــي وكالــة القناعــة وقــرر املدعــى عليــه عــدم‬\n      ‫القناعــة وطلــب رفعــه حملكمــة االســتئناف بعــد تقــدمي الئحــة اعتراضيــة‬\n      ‫عليــه فأفهمتــه مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم الصــك‬\n      ‫وتقــدمي الالئحــة االعتراضيــة خــال ثالثــن يومــا مــدة االعتــراض فــاذا‬\n      ‫تاخــر ســقط حقــه يف طلــب االســتئناف واكتســب احلكــم القطعيــة‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                               ‫حــرر يف ‪1434/6/5‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بشــرح فضيلــة الرئيــس برقــم ‪ 33/1978291‬يف ‪1434/8/9‬ه ـ علــى‬\n      ‫خطــاب رئيــس محكمــة االســتئناف مبنطقــة مكــة املكرمــة املكلــف‬\n      ‫برقــم ‪ 331978291‬يف ‪1434/8/6‬ه ـ برفقهــا قــرار التصديــق مبوجــب‬\n                    ‫القــرار رقــم ‪ 34281939‬يف ‪1434/7/29‬ه ـ وهــذا نصــه‪-:‬‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ -:‬فقــد‬\n      ‫جــرى منــا نحــن رئيــس وأعضــاء الدائــرة احلقوقيــة الثالثــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى هــذا الصــك الصادر‬\n      ‫مــن فضيلــة الشــيخ ‪ ....................‬القاضــي باحملكمــة العامــة مبكــة‬\n      ‫املكرمــة واملســجل بعــدد ‪34231967‬وتاريــخ ‪1434/6/5‬ه ـ املتضمــن‬\n\n\n‫‪129‬‬\n\f‫دعــوى شــركة ‪ ...........‬ضــد ‪ ...........‬يف مبلــغ مالــي احملكــوم فيــه مبــا‬\n‫دون باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــرر باألكثريــة املوافقــة علــى احلكــم ‪ .‬وبــاهلل تعالــى التوفيــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ ،‬قاضــي اســتئناف‬\n‫ختــم وتوقيــع ‪ ...........‬قاضــي اســتئناف ختــم وتوقيــع ‪ ...........‬لــي وجهــة‬\n‫نظــر ‪ ،‬رئيــس الدائــرة ختــم وتوقيــع ‪...........‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/15‬ه ـ‬\n‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n‫مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى ه ــذا الصــك الص ــادر مــن‬\n‫فضي ــلة الشي ــخ ‪ ...............‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n‫واملســجل بعــدد ‪ 34231967‬وتــاري ــخ ‪1434/6/5‬ه ـ املتضمــن دعــوى‬\n‫شــركة ‪...........‬ضــد ‪ ...........‬يف مبلــغ مالــي احملكــوم فيــه مبــا دون‬\n‫باطنه‪ .‬وبــدراس ــة احلك ــم وص ــورة ضبط ــه والئحته االعتراضية تقـ ـ ـ ــرر‬\n‫باألكثريــة املـ ــوافقـ ـ ـ ــة علــى احلكــم‪ .‬وبــاهلل تعالــى التوفيــق وصل ــى اهلل‬\n                                ‫عل ــى نبي ــنا محم ــد وعل ــى آلـه وصحب ــه وسـلم‪.‬‬\n\n\n\n\n                                                                                          ‫‪130‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":118,"source_page_end":130,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5c21fef458ded7fc51ff74c7d1defbdce8f0d677aa3bd7adddc623deb1b19bc1","normalized_text_hash":"6c344aac3bcbf7e51b499646de8e970df652346b164e3f0d476b8eef6f83320d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p118-34231967"},{"id":"97c14733-3eee-568c-a7d8-96c03de86879","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -طلب إخاء عقار -البينة على املدعى واليمن على من انكر -توجيه اليمن على املدعي -نكول املدعي عن اليمن - حكم بصرف النظر عن دعوى املدعي لنكوله عن اليمن.","document_number":"332031116","case_number":"33656979","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/24","year":"1434","subject":"عقد -إجارة -طلب إخاء عقار -البينة على املدعى واليمن على من انكر -توجيه اليمن على املدعي -نكول املدعي عن اليمن - حكم بصرف النظر عن دعوى املدعي لنكوله عن اليمن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/24 :‬هـ‬\n                       ‫ُ‬                  ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪332031116 :‬‬\n                           ‫َر ْق ُم الدعوى‪33656979 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪ 34376312‬تاريخه‪1434/12/2 :‬هـ‬\n\n\n        ‫عقــد ‪ -‬إجــارة ‪ -‬طلــب إخــاء عقــار ‪ -‬البينــة علــى املدعــى واليمــن علــى‬\n        ‫مــن انكــر‪ -‬توجيــه اليمــن علــى املدعــي ‪ -‬نكــول املدعــي عــن اليمــن ‪-‬‬\n                  ‫حكــم بصــرف النظــر عــن دعــوى املدعــي لنكولــه عــن اليمــن‪.‬‬\n\n\n\n\n        ‫قولــه صلــى اهلل عليــه وســلم (( البينــة علــى املدعــي واليمــن علــى مــن‬\n                                                                              ‫أنكــر ))‬\n\n\n\n\n        ‫ادعــى املدعــي بــأن املدعــى عليــه اســتأجر منه بوفيــه مت ذكر وصفها يف‬\n        ‫نــص القضيــة بأجــرة قدرهــا أربعــون ألــف ريــال ملــدة ثالث ســنوات بتاريخ‬\n        ‫‪1432/2/15‬ه ـ والدفــع مقدم ـ ًا كل ســتة أشــهر وانــه تأخــر يف ســداد‬\n        ‫األجــرة ولــم يلتــزم بهــا يف وقتهــا كمــا انــه اســتغل الرصيــف للتخزيــن‬\n        ‫وجلســة الزبائــن ممــا تعــرض معــه للمســائلة مــن جهــة البلديــة كمــا قــام‬\n        ‫بصبــغ الواجهــة ولــم يتقيــد مبــا جــاء يف عقــد اإليجــار وطلــب املدعــي‬\n        ‫فســخ عقــد اإليجــار وإلــزام املدعــى عليــه بإخــاء البوفيــه وتســليمها‬\n        ‫للمدعــي‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى عقــد اإليجــار واألجــرة‬\n        ‫وقــرر أن اجللســة علــى الرصيــف مت إزالتهــا ومت صبــغ الواجهــة الن احملــل‬\n        ‫ســابق ًا كان مغســلة وملــا مت فتــح البوفيــه مت صبــغ الواجهــة وتنظيفهــا‬\n‫‪131‬‬\n\f‫وأمــا األجــرة فقــرر انــه اتفــق مــع املدعــي علــى تقســيط املبلــغ عشــرة‬\n‫آالف ريــال كل ثالثــة أشــهر‪ ،‬أنكــر املدعــي دعــوى تقســيط األجــرة‬\n‫التــي دفــع بهــا املدعــى عليــه وكالــة وليســت لديــه بينــه وطلــب املدعــى‬\n‫عليــه ميــن املدعــي ونــكل عنهــا‪ ،‬قــرر ناظــر القضيــة ملــا ســبق صــرف‬\n‫النظــر عــن الدعــوى ‪ ،‬صــدر قــرار محكمــة االســتئناف باملصادقــة علــى‬\n                                                                      ‫احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة العامــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام املســاعد برقــم ‪ 33656979‬وتاريــخ ‪ 1433/11/16‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332031116‬وتاريــخ ‪ 1433/11/16‬ه ـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1434/01/10‬ه ـ حضــر ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم وادعــى علــى احلاضــر معــه ســعودي بالســجل‬\n‫رقــم الوكيــل الشــرعي عــن بالوكالــة الصــادرة مــن محكمــة ‪..........‬‬\n‫العامــة برقــم ‪..........‬وتاريــخ ‪1432/2/5‬ه ـ ولكــون املدعــى عليــه لــم‬\n‫يحضــر أصــل الوكالــة فقــد جــرى رفــع اجللســة وتأجلــت إلــى يــوم االثنــن‬\n‫‪1434/1/19‬ه ـ الســاعة العاشــرة وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/1/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/02/06‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر الطرفــان وقــال املدعــى عليــه وكالــة‪:‬‬\n‫إننــي لــم أســتطع إحضــار الوكالــة األصــل لــذا جــرى رفــع اجللســة‬\n‫إلحضارهــا وتأجلــت ليــوم االثنــن ‪1434/02/11‬ه ـ الســاعة العاشــرة‬\n                                                                                   ‫‪132‬‬\n\f      ‫والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/06‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق ‪1434/02/18‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي واملدعــى عليــه املذكــور هويتــه‬\n      ‫بعاليــه الوكيــل الشــرعي عــن بالوكالــة الصــادرة مــن كتابــة عــدل‬\n      ‫محافظــة أحــد رفيــدة برقــم ‪..........‬وتاريــخ ‪1434/2/12‬ه ـ وادعــى األول‬\n      ‫قائــا لقــد أجــرت مــوكل املدعــى عليــه البوفيــه الواقعــة بعمارتــي‬\n      ‫الواقعــة بحــي ‪..........‬علــى شــارع ‪..........‬بقيمــة قدرهــا أربعــون ألــف ريــال‬\n      ‫ملــدة ثــاث ســنوات ابتــداء بتاريــخ ‪1432/2/15‬ه ـ والدفــع مقدمــا كل‬\n      ‫ســتة أشــهر وهــو يتأخــر يف ســداد األجــرة وال يلتــزم بهــا يف وقتهــا كمــا‬\n      ‫أنــه اســتغل الرصيــف للتخزيــن وجلســة للزبائــن ممــا تعرضــت بســببه‬\n      ‫للمســاءلة مــن جهــة بلديــة ‪..........‬كمــا قــام بصبــغ الواجهــة ولــم يتقيــد‬\n      ‫مبــا جــاء يف عقــد اإليجــار وحيــث احلــال مــا ذكــر فإننــي أطلــب فســخ‬\n      ‫العقــد وإلزامــه بإخــاء البوفيــة وتســليمها لــي هــذه دعــواي ولكــون‬\n      ‫وكالــة املدعــى عليــه ناقصــة ال تتضمــن حــق املرافعــة ومــا يتبعهــا فقــد‬\n      ‫جــرى رفــع اجللســة وتاجلــت ليــوم األحــد املوافــق ‪1434/4/7‬ه ـ التاســعة‬\n      ‫والنصــف وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم حــرر يف ‪1434/02/18‬ه ـ‬\n      ‫ويف جلســة أخــرى حضــر الطرفــان وأحضــر املدعــى عليــه وكالــة مــن‬\n      ‫موكلــه صــادرة مــن كتابــة عــدل محافظــة أحــد رفيــدة برقــم ‪..........‬يف‬\n      ‫‪1434/5/29‬ه ـ تخولــه املرافعــة وكافــة إجــراءات التقاضــي وبعــرض‬\n      ‫الدعــوى عليــه قــال مــا ذكــره املدعــي يف دعــواه مــن اســتئجار موكلــي‬\n      ‫منــه البوفيــة التــي ذكــر بالقيمــة واملــدة التــي ذكــر وأن الدفــع مقــدم‬\n\n\n‫‪133‬‬\n\f‫كل ســتة أشــهر فهــذا صحيــح وأمــا مــا ذكــره مــن أن موكلــي ال يلتــزم‬\n‫بســداد األجــرة ولــم يلتــزم مبــا جــاء يف العقــد فغيــر صحيــح وأمــا مــا‬\n‫ذكــره مــن اســتغالل موكلــي للرصيــف فقد كان يوجد فيه كراســي‬\n‫ومت إزالتهــا وأمــا صبــغ الواجهــة فقــد كان احملــل مغســلة وملــا مت فتــح‬\n‫البوفيــه مت صبــغ الواجهــة وتنظيفهــا هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫املدعــي قــال الصحيــح مــا ذكرتــه ولــدي البينــة وأطلــب رفــع اجللســة‬\n‫إلحضارها ويف جلســة أخرى حضر الطرفان وبســؤال املدعي عن بينته‬\n‫علــى ماذكــر قــال إن اجللســة التــي وضعهــا علــى الرصيــف للزبائــن قــد‬\n‫أزالهــا ولــم يبــق إال خــزان املــاء وبســؤاله هــل مت مســاءلته مــن قبــل البلديــة‬\n‫بعدهــا قــال ال وقــدم بيانــا يبــن فيــه تاريــخ اســتحقاق االيجــار وتاريــخ‬\n‫ســداده وبعرضــه علــى املدعــى عليــه قــال مــا جــاء يف صحيــح والســبب يف‬\n‫تأخــري عــن ســداد االيجــار هــو أننــي اتفقــت معــه علــى ذلــك وطلبــت منــه‬\n‫أن يقســط علــي املبلــغ عشــرة آالف كل ثالثــة أشــهر وبعــرض ذلــك علــى‬\n‫املدعــي قــال ماذكــره املدعــى عليــه وكالــة غيــر صحيــح والصحيــح‬\n‫أننــي لــم اتفــق معــه علــى تقســيط املبلــغ إال مــرة واحــدة وبعــرض ذلــك‬\n‫علــى املدعــى عليــه قــال الصحيــح ماذكرتــه وبســؤاله هــل لديــه بينــة‬\n‫علــى ذلــك قــال ال وأطلــب ميينــه وبعــرض اليمــن علــى املدعــي قــال إننــي‬\n‫لــن أحلــف إال علــى أننــي قســطت عليــه املبلــغ إال مــرة واحــدة فجــرى‬\n‫إفهامــه بحلــف اليمــن علــى نفــي مــا ذكــره املدعــى عليــه كامــا فقــال‬\n‫لــن أحلــف علــى ذلــك فكررتــه عليــه ثالثــا فرفــض فبنــاء علــى ماتقــدم‬\n‫مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه وكالــة بصحــة مــا جــاء يف‬\n‫دعــوى املدعــي مــن اســتئجار موكلــه منه احملــل املذكــور بالقيمة واملدة‬\n‫التــي ذكــر وملــا قــرره املدعــي مؤخــرا مــن أنــه مت إزالــة مــا كان موجــودا‬\n\n\n                                                                                           ‫‪134‬‬\n\f      ‫علــى الرصيــف وألن املدعــى عليــه أقــر بأنــه تأخــر يف الســداد بنــاء علــى‬\n      ‫اتفــاق بــن املدعــي وبــن موكلــه ولــم يقــم بينــة علــى ذلــك وطلــب ميــن‬\n      ‫املدعــي وألن املدعــي نــكل عــن اليمــن ولقولــه صلــى اهلل عليــه وســلم‬\n      ‫(البينــة علــى املدعــي واليمــن علــى مــن أنكــر) فقــد صرفــت النظــر‬\n      ‫عــن دعــوى املدعــي وبعرضــه علــى املدعــي قــرر عــدم قناعتــه باحلكــم‬\n      ‫وطلــب رفــع املعاملــة حملكمــة االســتئناف فأفهمتــه أن عليــه التقــدم بعــد‬\n      ‫خمســة أيــام الســتالم نســخة مــن الصــك وتقــدمي الالئحــة االعتراضيــة‬\n      ‫خــال املــدة املقــررة نظامــا وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/30‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء ‪ 1434/12/25‬ه ـ افتتحــت‬\n      ‫اجللســة بنــاء علــى عــودة املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية برقــم ‪ 342093878‬يف ‪1434/12/17‬ه ـ وبرفقهــا قــرار‬\n      ‫أصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة األولــى رقــم ‪34376312‬‬\n      ‫يف ‪1434/12/2‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1434/12/25‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n      ‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف‬\n      ‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبدينــة بالدمــام برقــم ‪332031116‬‬\n      ‫وتاريــخ ‪1434/8/24‬ه ـ واملقيــدة لدينــا برقــم ‪ 342093878‬وتاريــخ‬\n      ‫‪1434/9/1‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ /‬املسـ ّـجل برقــم ‪ 34286020‬وتاريــخ ‪1434/8/2‬ه ـ‬\n\n\n‫‪135‬‬\n\f‫اخلــاص بدعــوى‪ ...........‬ضــد‪ ...........‬يف قضيــة حقوقيــة وقــد تضمــن‬\n‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة‬\n‫علــى احلكــم ‪ ،‬ولبيانــه حــرر يف ‪1434/12/2‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                              ‫‪136‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":131,"source_page_end":136,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"28bf1df4288ab440f01ac74722535fbf779020842fd20aff633c2712a73fca82","normalized_text_hash":"1e2b6c1c4662f1cd6b93ca58b6db795b999e4e274bb68e2d95a94975546a73bf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p131-332031116"},{"id":"8f73326c-3d65-57ff-ad5d-69b7e0caff9e","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة مع الوعد بالتملك -سيارة -حادث -بيع السيارة للغير من قبل املدعى عليه -احتساب أقساط السيارة بعد احلادث- سبب عدم السداد راجع للشركة املدعى عليها -طلب فسخ العقد ورفع االسم من القائمة السوداء -األجرة تستحق على املستاخر عند متكنه من االنتفاع -إثبات فسخ العقد واحلكم برفع اسم املدعى من القائمة السوداء.","document_number":"34240533","case_number":"33681073","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/13","year":"1434","subject":"عقد -إجارة مع الوعد بالتملك -سيارة -حادث -بيع السيارة للغير من قبل املدعى عليه -احتساب أقساط السيارة بعد احلادث- سبب عدم السداد راجع للشركة املدعى عليها -طلب فسخ العقد ورفع االسم من القائمة السوداء -األجرة تستحق على املستاخر عند متكنه من االنتفاع -إثبات فسخ العقد واحلكم برفع اسم املدعى من القائمة السوداء.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/6/13 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34240533 :‬‬\n                         ‫َر ْق ُم الدعوى‪33681073 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪/34377281‬ق‪/2‬أ تاريخه‪1434/12/3 :‬هـ‬\n\n\n\n      ‫عقــد ‪ -‬إجــارة مــع الوعــد بالتملــك ‪ -‬ســيارة ‪ -‬حــادث ‪ -‬بيــع الســيارة‬\n      ‫للغيــر مــن قبــل املدعــى عليــه ‪ -‬احتســاب أقســاط الســيارة بعــد احلادث‪-‬‬\n      ‫ســبب عــدم الســداد راجــع للشــركة املدعــى عليهــا ‪ -‬طلــب فســخ العقــد‬\n      ‫ورفــع االســم مــن القائمــة الســوداء ‪ -‬األجــرة تســتحق علــى املســتاخر‬\n      ‫عنــد متكنــه مــن االنتفــاع ‪ -‬إثبــات فســخ العقــد واحلكــم برفــع اســم‬\n                                                ‫املدعــى مــن القائمــة الســوداء‪.‬‬\n\n\n\n\n      ‫‪ .1‬قــول اخلرقــي رحمــه اهلل ‪»:‬فــإن جــاء أمــر غالــب يحجــز املســتأجر عــن‬\n          ‫منفعــة مــا وقــع عليــه العقــد لزمــه مــن األجــر مبقــدار مــدة انتفاعــه»‪.‬‬\n      ‫‪ .2‬قــول املوفــق رحمــه اهلل يف املغنــي أن العــن املســتأجرة «إذا غصبــت‬\n      ‫فللمســتأجر الفســخ ألن فيــه تأخيــر حقــه ‪ ،‬فــإن فســخ فاحلكــم فيــه‬\n      ‫كمــا لــو انفســخ العقــد بتلــف العني ســواء وإن لم يفســخ حتى انقضت‬\n      ‫مــدة اإلجــارة ‪ ،‬فلــه اخليــار بــن الفســخ والرجــوع باملســمى وبــن البقــاء‬\n                                    ‫علــى العقــد ومطالبــة الغاصــب بأجــر املثــل»‪.‬‬\n                                                                 ‫‪ .3‬ال ضرر وال ضرار‪.‬‬\n                                                   ‫‪ .4‬املادة (‪ )55‬من نظام املرافعات‪.‬‬\n\n\n\n\n‫‪137‬‬\n\f‫ادعــت املدعيــة بدعــوى ضــد الشــركة املدعــى عليهــا بأنهــا اســتأجرت‬\n‫منهــا ســيارة بنظــام التأجيــر املنتهــي بالتمليــك وقامــت بتســديد بعــض‬\n‫األجــرة ثــم حصــل حــادث مــروري أديــن فيــه الطــرف املقابــل بالنســبة‬\n‫الكاملــة ولــم يقبــل املــرور مراجعتهــا فســلمت األوراق للشــركة املدعــى‬\n‫عليهــا فتفاجــأت موكلتــه بــإدراج اســمها يف القائمــة الســوداء (‪)000‬‬\n‫وقيامهــا ببيــع الســيارة علــى الغيــر عليــه فقــد طلبــت املدعيــة إلــزام‬\n‫الشــركة املدعــى عليهــا برفــع اســمها مــن القائمــة وتســليمها ســيارة‬\n‫جديــدة عوض ـ ًا عــن الســيارة التالفــه‪ ،‬أجــاب وكيــل الشــركة بصحــة‬\n‫العقــد واألقســاط املســددة وحصــول احلــادث والتبليــغ بــه يف وقتــه ووضــع‬\n‫موكلتــه علــى القائمــة الســوداء وبيــع الشــركة للســيارة محــل الدعــوى‬\n‫وأنــه ملــا أبلــغ باحلــادث مــن قبــل مديــر الشــرطة ذهــب للمــرور فأكــدوا‬\n‫وجــود رقــم احلــادث ولكــن األوراق مفقــودة ووعــد بالبحــث عنهــا‬\n‫وراجعهــم عــدة مــرات ولكــن لــم يجــدوا أوراق احلــادث وألن األقســاط‬\n‫تســتمر علــى املدعيــة فقــد ترتــب يف ذمتهــا مبالــغ متأخــرة فجــرى بيــع‬\n‫الســيارة لعــدم مراجعتهــا للشــركة ومطالبتهــا بالســيارة يف املــدة‬\n‫احملددة من قبل الشــركة‪ ،‬جرى ســؤاله ملاذا مت بيع الســيارة مع كون‬\n‫العقــد الزال ســاري ًا وهــل مت إبــاغ املدعيــة بذلــك فقــال تركنــا الســيارة‬\n‫مــده معينــة فلمــا لــم تــأت املســتأجرة باملطالبــة بهــا مت بيعهــا‪ ،‬أنكــر‬\n‫وكيــل املدعيــة عــدم مراجعتــه للشــركة وقــرر بأنــه كان يراجعهــم‬\n‫باالســتمرار حتــى أخبــر بــأن الســيارة بيعــت وطلــب فســخ العقــد‪ ،‬قــرر‬\n‫وكيــل املدعــي بأنــه يطلــب البــت يف موضــوع رفــع اســم موكلتــه مــن‬\n\n                                                                                    ‫‪138‬‬\n\f      ‫القائمــة الســوداء وأنــه يرغــب فصــل الدعــوى مبطالبــة بســيارة جديــدة‬\n      ‫عــن هــذه الدعــوى‪ ،‬عليــه وألن املدعــي ادعــى بكــون الشــركة املدعــى‬\n      ‫عليهــا قــد وضعــت اســم موكلتــه يف القائمــة الســوداء نظــرا لتأخرهــا‬\n      ‫يف ســداد بعــض أقســاط الســيارة املســتأجرة منهــم بســبب مــن قبــل‬\n      ‫الشــركة لعــدم متابعتهــم موضــوع احلــادث يف املــرور وقــد أقــر املدعــى‬\n      ‫عليــه وكالــة بــأن التخلــف عــن األقســاط كان بعــد احلــادث ولــم يكــن‬\n      ‫مــن قبــل املدعيــة أصالــة وإمنــا كان التأخــر يف متابعــة أوراق احلــادث‬\n      ‫كان مــن املــرور إذ فقــدت أوراق احلــادث مــن قبلهــم ولــم يتمكــن مــن‬\n      ‫متابعــة أوراق احلــادث ونظــرا لكــون األجــرة تســتحق علــى املســتأجر‬\n      ‫عنــد متكنــه مــن االنتفــاع فــإن تعــذر انتفاعــه بهــا مــن قبــل املؤجــر أو‬\n      ‫مــن قبــل طــرف أجنبــي فــا يســتحق املؤجــر أجــرة املــدة التــي تعــذر فيهــا‬\n      ‫االنتفــاع وألن العــن املســتأجرة (إذا غصبــت فللمســتأجر الفســخ ألن‬\n      ‫فيــه تأخيــر حقــه‪ ،‬فــإن فســخ فاحلكــم فيــه كمــا لــو انفســخ العقــد‬\n      ‫بتلــف العــن ســواء وإن لــم يفســخ حتــى انقضــت مــدة اإلجــارة ‪ ،‬فلــه‬\n      ‫اخليــار بــن الفســخ والرجــوع باملســمى وبــن البقــاء علــى العقــد ومطالبــة‬\n      ‫الغاصــب بأجــر املثــل) وقــد طالــب املســتأجر بالفســخ ومبــا أن املدعــى‬\n      ‫عليهــا قــد تعســفت يف اســتعمال حقهــا يف وضــع املدعيــة علــى القائمــة‬\n      ‫الســوداء ولــم يحصــل منهــا خلــل يف ســداد األقســاط يف وقتهــا وقــد‬\n      ‫جــاءت الشــريعة برفــع الضــرر عــن املتضرريــن ومــن القواعــد الفقهيــة‬\n      ‫الكبــرى (ال ضــرر وال ضــرار) ولــكل مــا ســبق فقــد صــدر حكــم علــى‬\n      ‫املدعــى عليهــا برفــع اســم املدعيــة مــن القائمــة الســوداء لــدى شــركة‬\n      ‫(‪ )...........‬وثبــت لديهــا إرجــاء املدعــي وكالــة مطالبتــه بســيارة جديــدة‬\n      ‫بديلــة مــن الســيارة التــي باعتهــا الشــركة املدعــى عليهــا وإقــراره بطلــب‬\n\n\n‫‪139‬‬\n\f‫فصلهــا عــن هــذه الدعــوى‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة باخلبــر املســاعد برقــم ‪ 33681073‬وتاريــخ ‪1433/11/28‬ه‬\n‫املقيــدة باحملكمــة برقــم ‪ 332138646‬وتاريــخ ‪1433/11/28‬ه ففــي‬\n‫يــوم االثنــن املوافــق ‪1434/02/04‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n‫‪ 09‬وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ )........‬بصفتــه وكيــا عــن املدعيــة (‪ ).....‬ســعودية اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ ).....‬بالوكالــة رقــم (‪ ).....‬يف ‪1433/11/28‬ه ـ‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة باخلبــر واملخــول لــه فيهــا املرافعــة‬\n‫واملدافعــة وســماع الدعــوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح‬\n‫والتنــازل واإلبــراء وطلــب اليمــن ورده واالمتنــاع عنــه وإحضــار البينــات‬\n‫وقبــول احلكــم واالعتــراض عليــه واســتالم املبالــغ والصكــوك ولــم‬\n‫حتضــر املدعــى عليهــا شــركة (‪ ).....‬وال مــن ميثلهــا شــرعا ولــم تردنــا‬\n‫إفــادة بتبليغهــم مــن عدمــه فبنــاء علــى املــادة (‪ )55‬مــن نظــام املرافعــات‬\n‫الشــرعية فقــد قــررت رفــع اجللســة لتبليــغ املدعى عليها ويف جلســة أخرى‬\n‫حضــر املدعــي وكالــة (‪ ).....‬املثبتــة هويتــه ووكالتــه ســابق ًا ولــم حتضــر‬\n‫املدعــى عليهــا شــركة (‪ ).....‬وال مــن ميثلهــا شــرع ًا وقــد كتــب خطــاب‬\n‫لتبليغهــا برقــم ‪ 34318839‬يف ‪1434/2/9‬ه ـ وأفــاد محضــر اخلصــوم‬\n‫بأنــه مت تبليــغ املدعــى عليهــا بتوقيــع الوكيــل الشــرعي للشــركة (‪).....‬‬\n‫فبنــاء علــى املــادة (‪ )55‬مــن نظــام املرافعــات الشــرعية فقــد قــررت ســماع‬\n\n                                                                                     ‫‪140‬‬\n\f      ‫ا يف دعــواه إن موكلتــي‬    ‫الدعــوى غيابي ـ ًا فادعــى املدعــي وكالــة قائ ـ ً‬\n      ‫قــد اســتأجرت مــن الشــركة املدعــى عليهــا ســيارة (‪2008 ).....‬م رقــم‬\n      ‫اللوحــة (‪ ).....‬بنظــام اإليجــار املنتهــي بالتمليــك يف ‪1428/11/8‬ه ـ مببلــغ‬\n      ‫‪93960‬ريــال مقســطة علــى ‪ 60‬قســط ًا شــهري ًا قــدر القســط الواحــد‬\n      ‫‪1566‬ريــال اعتبــار ًا مــن ‪2008/1/1‬م علمـ ًا أن فيــه دفعــة مقدمــة قدرهــا‬\n      ‫(‪6500‬ريــال) وقــد مت تســديد املبلــغ املقــدم وبعــض األقســاط وبلــغ مقدار‬\n      ‫مــا ســدد ‪14000‬ريــال ثــم حصــل علــى الســيارة حــادث مــروري يف شــهر‬\n      ‫صفــر مــن عــام ‪1429‬ه ـ يف مدينــة اجلبيل الصناعية وكان يقود الســيارة‬\n      ‫(‪ ).....‬أخــو موكلتــي وقــد كانــت نســبة اإلدانــة يف احلــادث ‪ %100‬علــى‬\n      ‫الطــرف املقابــل وقــد باشــر مــرور اجلبيــل هــذا احلــادث وراجعتهــم عــدة‬\n      ‫مــرات فأفهمونــي بــأن الســيارة مســجلة باســم الشــركة وأنهــا هــي التــي‬\n      ‫تتابــع املوضــوع فتركــت املتابعــة وســلمتهم كامــل األوراق علمــا أنــه مت‬\n      ‫إبالغهــم باحلــادث مــن حــن حصولــه ثــم تفاجــأت موكلتــي بعــد ذلــك‬\n      ‫بكــون الســيارة قــد بيعــت علــى طــرف ثالــث بغيــر علمهــا كمــا تفاجأت‬\n      ‫بوضــع اســمها علــى القائمــة الســوداء وقــد راجعــت الشــركة فأفهمونــي‬\n      ‫بأننــي ال بــد أن أســدد كامــل قيمــة الســيارة وهــم قــد باعــوا الســيارة‬\n      ‫فأفهمتهــم بــأن الســيارة حصــل عليهــا حــادث وأن الشــركة باعتهــا بغيــر‬\n      ‫علــم موكلتــي فقالــوا ســدد النصــف إذن فرفضــت ذلــك وكل موظــف‬\n      ‫يتنصــل مــن املســؤولية فأطلــب إلزامهــم باآلتــي أوال رفــع اســم موكلتــي‬\n      ‫مــن القائمــة الســوداء ثاني ـ ًا إلزامهــم بإبــدال موكلتــي بســيارة جديــدة‬\n      ‫عوض ـ ًا عــن الســيارة التــي باعوهــا بغيــر علمهــا هكــذا ادعــى فطلبــت‬\n      ‫منــه البينــة علــى دعــواه فأبــرز العقــد الــذي بــن موكلتــه وبــن الشــركة‬\n      ‫املدعــى عليهــا وهــو مطابــق ملــا ذكــر بعاليــه كمــا جــرى ســؤاله هــل‬\n\n\n‫‪141‬‬\n\f‫لديــه مــا يثبــت وقــوع احلــادث ونســبة اإلدانــة فقــال ليــس لــدي شــيء‬\n‫مــن ذلــك وكامــل األوراق لــدى مــرور محافظــة اجلبيــل هكــذا أجــاب‬\n‫ونظــرا لضــرورة التثبــت مــن هــذا األمــر فقــد قــررت الكتابــة إلــى مــرور‬\n‫محافظــة اجلبيــل لطلــب اإلفــادة عــن احلــادث املذكــور ويف جلســة أخــرى‬\n‫حضــر املدعــي وكالــة املثبتــة هويتــه ووكالتــه مســبقا وحضــر معــه‬\n‫املدعــى عليــه (‪ ).....‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ ).....‬وكيــا‬\n‫عــن (‪ ).....‬بصفتــه شــريكا بشــركة (‪ ).....‬مبوجــب الســجل التجــاري‬\n‫رقــم (‪ ).....‬يف ‪1417/07/06‬ه مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل اخلبــر برقــم ‪ 37631‬يف ‪1432/11/20‬ه ـ واملخــول لــه فيهــا إقامــة‬\n‫الدعــوى واملرافعــة واملدافعــة وقبــول االحــكام واالعتــراض واالســتئناف‬\n‫واإلبــراء وكانــت اجللســة الســابقة قــد رفعــت ألجــل الكتابــة إلــى مــرور‬\n‫محافظــة اجلبيــل ألجــل االستفســار عــن احلــادث ولــم تتــم مخاطبتهــم‬\n‫لكــون املوظــف املختــص نســي ذلــك وقــد جــرى عــرض الدعــوى علــى‬\n‫املدعــى عليــه وكالــة فأجــاب قائــا ‪ :‬مــا ذكــره املدعــي وكالــة يف‬\n‫دعــواه مــن حصــول العقــد واألقســاط املســددة وحصــول احلــادث وتبليغنــا‬\n‫باحلــادث يف وقتــه ووضــع موكلتــه علــى القائمــة الســوداء وبيــع الشــركة‬\n‫للســيارة محــل الدعــوى فهــو صحيــح علمــا أننــي شــخصي ًا ملــا أبلغــت‬\n‫مــن قبــل مديــر الشــرطة باحلــادث ذهبــت إلــى مــرور محافظــة اجلبيــل‬\n‫فأكــد لــي وجــود رقــم احلــادث ولكــن األوراق مفقــودة ووعــد بالبحــث‬\n‫عنهــا وراجعتــه عــدة مــرات ولكــن لــم يجــدوا أوراق احلــادث ومبــا أن‬\n‫األقســاط تســتمر علــى املدعيــة فقــد ترتــب يف ذمتهــا مبالــغ متأخــرة ثــم‬\n‫مت بيــع الســيارة لعــدم مراجعتهــم للشــركة ومطالبتهــم بالســيارة يف‬\n‫املــدة احملــددة مــن قبــل الشــركة هكــذا أجــاب فجــرى ســؤاله ملــاذا‬\n\n\n                                                                                   ‫‪142‬‬\n\f      ‫مت وضــع اســم املدعيــة يف القائمــة الســوداء مــع علــم الشــركة بكــون‬\n      ‫الســبب يف التأخيــر يف ســداد األقســاط خارجــا عــن إرادتهــا فقــال لــو‬\n      ‫تركناهــا لتســبب لنــا باخلســارة هكــذا أجــاب فجــرى ســؤاله ملــاذا مت‬\n      ‫بيــع الســيارة مــع كــون العقــد الزال ســاري ًا وهــل مت إبــاغ املدعيــة بذلــك‬\n      ‫فقــال تركنــا الســيارة مــده معينــة فلمــا لــم تــأت املســتأجرة باملطالبــة‬\n      ‫بهــا مت بيعهــا هكــذا أجــاب وبعرضــه علــى املدعــي وكالــة أجــاب قائــا‬\n      ‫بــل كنــت أراجــع الشــركة بــن احلــن وآخــر للســؤال عــن احلــادث حتــى‬\n      ‫مت إبالغــي أخيــرا بأنــه مت بيــع الســيارة ثــم وضــع اســم موكلتــي يف‬\n      ‫القائمــة الســوداء وأطلــب فســخ العقــد بيننــا وإلغــاء وضــع اســم موكلتــي‬\n      ‫مــن القائمــة الســوداء هكــذا أجــاب وبعرضــه علــى املدعــى عليــه‬\n      ‫وكالــة أجــاب قائــا إن موكلتــي ترفــض ذلــك حتــى تســدد الباقــي مــن‬\n      ‫املديونيــة وقدرهــا خمســة وأربعــون ألــف ريــال تقريبــا فجــرى ســؤاله هــل‬\n      ‫كانــت املدعيــة ملتزمــة بســداد األقســاط قبــل حلــول احلــادث فقــال ال‬\n      ‫أعلــم وأحتــاج الرجــوع إلــى حســابات الشــركة هكــذا أجــاب ثــم قــرر‬\n      ‫املدعــي وكالــة قائــا أطلــب البــت يف موضــوع رفــع اســم موكلتــي مــن‬\n      ‫القائمــة الســوداء وأقــرر بأننــي أرغــب فصــل الدعــوى مبطالبــة بســيارة‬\n      ‫جديــدة عــن هــذه الدعــوى وســأقدم بهــا دعــوى مســتقلة بــإذن اهلل‬\n      ‫هكــذا أجــاب فبنــاء علــى مــا تقــدم وبعــد ســماع الدعــوى واإلجابــة ومبــا‬\n      ‫أن املدعــي ادعــى بكــون الشــركة املدعــى عليهــا قــد وضعــت اســم‬\n      ‫موكلتــه يف القائمــة الســوداء نظــرا لتأخرهــا يف ســداد بعــض أقســاط‬\n      ‫الســيارة املســتأجرة منهم واملذكورة بياناتها يف اجللســة املاضية وكان‬\n      ‫التخلــف بعــد حصــول احلــادث الــذي لــم تتمكــن موكلتــه مــن االســتفادة‬\n      ‫مــن الســيارة بســبب مــن قبــل الشــركة لعــدم متابعتهــم موضــوع احلــادث‬\n\n\n‫‪143‬‬\n\f‫يف املــرور وقــد أقــر املدعــى عليــه وكالــة بــأن التخلــف عــن األقســاط‬\n‫كان بعــد احلــادث ولــم يكــن مــن قبــل املدعيــة أصالة وإمنــا كان التأخر‬\n‫يف متابعــة أوراق احلــادث كان مــن املــرور إذ فقــدت أوراق احلــادث مــن‬\n‫قبلهــم وملتمكــن متابعــة أوراق احلــادث ونظــرا لكــون األجــرة تســتحق‬\n‫علــى املســتأجر عنــد متكنــه مــن االنتفــاع فــإن تعــذر انتفاعــه بهــا مــن‬\n‫قبــل املؤجــر أو مــن قبــل طــرف أجنبــي فــا يســتحق املؤجــر أجــرة املــدة‬\n‫التــي تعــذر فيهــا االنتفــاع قــال اخلرقــي رحمــه اهلل‪( :‬فــإن جــاء أمــر غالــب‬\n‫يحجــز املســتأجر عــن منفعــة مــا وقــع عليــه العقــد؟ لزمــه مــن األجــر‬\n‫مبقــدار مــدة انتفاعــه) وذكــر املوفــق رحمــه اهلل يف املغنــي تقســيمات‬\n‫لهــذه املســألة وينطبــق علــى هــذه القضيــة مــا إذا حصــل التعــذر بســبب‬\n‫غصــب العــن املؤجــرة حيــث إن فقــدان أوراق احلــادث وعــدم التمكــن‬\n‫مــن االنتفــاع بهــا إال بهــذه األوراق يعتبــر يف حكــم غصــب األجنبــي لهــذه‬\n‫العــن وقــد ذكــر املوفــق رحمــه اهلل يف املغنــي أن العــن املســتأجرة (إذا‬\n‫غصبــت فللمســتأجر الفســخ ألن فيــه تأخيــر حقــه؟ فــإن فســخ فاحلكــم‬\n‫فيــه كمــا لــو انفســخ العقــد بتلــف العــن ســواء وإن لــم يفســخ حتــى‬\n‫انقضــت مــدة اإلجــارة؟ فلــه اخليــار بــن الفســخ والرجــوع باملســمى وبــن‬\n‫البقــاء علــى العقــد ومطالبــة الغاصــب بأجــر املثــل) وقــد طالــب املســتأجر‬\n‫بالفســخ وحيــث لــم يدفــع أجــرة للمــدة التــي تعــذر فيهــا االنتفــاع ومبــا أن‬\n‫املدعــى عليهــا قــد تعســفت يف اســتعمال حقهــا يف وضــع املدعيــة علــى‬\n‫القائمــة الســوداء ولــم يحصــل منهــا خلــل يف ســداد األقســاط يف وقتهــا‬\n‫وقــد جــاءت الشــريعة بجلــب املصالــح وتكميلهــا ودفــع املفاســد وتقليلهــا‬\n‫وجــاءت برفــع الضــرر عــن املتضرريــن ومــن القواعــد الفقهيــة الكبــرى‬\n‫(ال ضرر وال ضرار) ولكل ما ســبق فقد ألزمت املدعى عليها شــركة‬\n\n\n                                                                                        ‫‪144‬‬\n\f      ‫(‪ ).....‬برفــع اســم املدعيــة (‪ ).....‬مــن القائمــة الســوداء لــدى شــركة (‪).....‬‬\n      ‫وثبــت لــدي إرجــاء املدعــي وكالــة ملطالبتــه بســيارة جديــدة بديلــة مــن‬\n      ‫الســيارة التــي باعتهــا الشــركة املدعــى عليهــا وإقــراره بطلــب فصلهــا‬\n      ‫عــن هــذه الدعــوى وبــه حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي‬\n      ‫وكالــة قناعتــه باحلكــم وقــرر املدعــى عليــه عــدم قناعتــه باحلكــم‬\n      ‫وطلــب رفــع املعاملــة حملكمــة االســتئناف بالئحــة اعتراضيــة وأفهــم‬\n      ‫مبقتضــى تعليمــات االســتئناف وبــاهلل التوفيــق حــرر يف ‪1434/6/13‬ه‬\n                                               ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده أمــا بعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بخطــاب رئيســها رقــم ‪ 342186558‬يف ‪1434/12/16‬ه ـ وقــد ظهــر‬\n      ‫علــى الصــك مــن قبــل الدائــرة احلقوقيــة الثانيــة يف محكمــة االســتئناف‬\n      ‫مبــا نصــه‪( :‬احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم‬\n      ‫‪ 34240533‬وتاريخ ‪1434/6/13‬هـ الصادر من فضيلة القاضي الشيخ‬\n      ‫(‪ ).....‬وأصدرنــا القــرار رقــم ‪/34377281‬ق‪/2‬أ وتاريــخ ‪1434/12/3‬ه ـ‬\n      ‫املتضمــن املصادقــة علــى احلكــم قاضــي اســتئناف (‪ ).....‬قاضــي‬\n      ‫اســتئناف (‪ ).....‬رئيــس الدائــرة (‪ ).....‬أختامهــم وتوقيعاتهــم) انتهــى نصــه‬\n      ‫وبــاهلل التوفيــق حــرر يف ‪1434/12/25‬ه ـ وصلــى اهلل وســلم علــى نبينــا‬\n                                                                                    ‫محمــد‪.‬‬\n      ‫احلمــد هلل وحــده أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقية‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪ 342186558‬وتاريــخ ‪1434/9/15‬ه ـ الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة اخلبــر املســاعد برقــم‬\n      ‫‪ 332138646‬وتاريــخ ‪1434/9/7‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n\n\n‫‪145‬‬\n\f‫فضيلــة القاضــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم ‪34240533‬‬\n‫وتاريــخ ‪1434/6/13‬ه ـ اخلــاص بدعــوى (‪ ).....‬ضــد (‪ ).....‬يف قضيــة‬\n‫حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/12/3‬ه ـ ‪.‬‬\n\n\n\n\n                                                                               ‫‪146‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":137,"source_page_end":146,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1832740e295ef7842a7b9eb9341b2944f221b8eb9100375770350b096ff16d39","normalized_text_hash":"8515d5ddc29301a7d600879f9905ede5f3ad6ccb514892b4c7067bb09be725b8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p137-34240533"},{"id":"e0249bdc-3819-507e-ac81-37d528ed992b","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة املؤجر بإصاح التلفيات ودفع األجرة -دفع املدعى عليه بأن التلفيات استهالكية ليست بتفريط وأنه أخلى العن- تقرير هيئة النظر -قرار أهل اخلبرة بأن التلفيات بتفريط وجود أعمال أحدثها عليه إزالتها -تضمن املدعي عليه التلفيات وإزالة ما أحدثه وإخاء العن قبل نهاية العام ودفع أجرته .","document_number":"34302116","case_number":"33683430","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/22","year":"1434","subject":"إجارة -مطالبة املؤجر بإصاح التلفيات ودفع األجرة -دفع املدعى عليه بأن التلفيات استهالكية ليست بتفريط وأنه أخلى العن- تقرير هيئة النظر -قرار أهل اخلبرة بأن التلفيات بتفريط وجود أعمال أحدثها عليه إزالتها -تضمن املدعي عليه التلفيات وإزالة ما أحدثه وإخاء العن قبل نهاية العام ودفع أجرته .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/22 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34302116 :‬‬\n                         ‫َر ْق ُم الدعوى‪33683430 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34349104‬تاريخه‪1434/11/4 :‬هـ‬\n\n\n      ‫إجــارة‪ -‬مطالبــة املؤجــر بإصــاح التلفيــات ودفــع األجــرة‪ -‬دفــع املدعــى‬\n      ‫عليــه بــأن التلفيــات اســتهالكية ليســت بتفريــط وأنــه أخلــى العــن‪-‬‬\n      ‫تقريــر هيئــة النظــر‪ -‬قــرار أهــل اخلبــرة بــأن التلفيــات بتفريــط وجــود‬\n      ‫أعمــال أحدثهــا عليــه إزالتهــا‪ -‬تضمــن املدعــي عليــه التلفيــات وإزالــة‬\n                     ‫مــا أحدثــه وإخــاء العــن قبــل نهايــة العــام ودفــع أجرتــه ‪.‬‬\n\n\n\n\n      ‫‪ .1‬املســتأجر إذا فــرط أو تعــدى يف العــن املســتأجرة ضمــن‪ .‬ينظــر‬\n                                                     ‫كشــاف القنــاع ‪.139/9‬‬\n      ‫‪ .2‬مــا كان مــن عمــارة العــن املؤجــرة ليــس الزمــا للمســتأجر‪ .‬ينظــر‬\n                                                      ‫كشــاف القنــاع ‪.109/9‬‬\n\n\n\n\n      ‫تقــدم املدعــي بدعــوى ضــد الشــركة املدعــى عليهــا بأنــه أجرهــا عقــارا‬\n      ‫ملــدة خمــس ســنوات تبــدأ يف ‪1430/9/1‬ه ـ وتنتهــي يف ‪1435/8/30‬ه ـ‬\n      ‫بثمانــن ألــف ريــال للســنة األولــى وثمانيــة وثمانــن ألــف ريــال للســنة‬\n      ‫الثانيــة وســتة تســعني ألفــا وثمامنائــة ريــال للســنة الثالثــة ومائــة وســتة‬\n      ‫آالف وأربعمائــة وثمانــن ريــاال للســنة الرابعــة ومائــة وســبعة عشــر ألفــا‬\n      ‫ومائــة وأربعــة وســتني ريــاال للســنة اخلامســة علــى أن تســلم األجــرة يف‬\n\n‫‪147‬‬\n\f‫بدايــة شــهر رمضــان مــن كل ســنة إيجاريــه وأنــه اســتلم أجــرة الســنني‬\n‫الثــاث األول ثــم بتاريــخ ‪1433/7/28‬ه ـ وردت رســالة مــن املدعــى عليها‬\n‫ترغــب فيهــا بفســخ العقــد وأنهــا ستســلم العقــار لــه يف ‪1433/9/1‬ه ـ‬\n‫وقــد رد عليهــم بأنــه إذا ســلمت الشــركة العقــار ســليما نظيفــا كمــا مت‬\n‫تســليمه لهــا بــدون تلفيــات وال تعديــات فإنــه موافــق علــى ذلــك فطلبــت‬\n‫الشــركة منــه احلضــور لالطــاع علــى البيــت وبيــان مــا فيــه مــن تلفيــات‬\n‫فشــاهد تلفيــات كبيــرة يف العقــار تســببت فيهــا الشــركة وأبلغهــا انــه‬\n‫لــن يســتلم العقــار وال يوافــق علــى فســخ العقــد وأنــه يطالــب الشــركة‬\n‫بأجــرة هــذا العــام وإصــاح تلفيــات العقــار قبــل اســتالمه فطلبــت‬\n‫الشــركة منــه بيــان تكلفــة إصــاح العقــار فأحضــر املختصــن وتبــن‬\n‫أن اإلصــاح يكلــف خمســة وســتني ألــف ريــال وطلــب منهــم موكلــي‬\n‫دفــع هــذا املبلــغ فرفضــت الشــركة لــذا فيطلــب إلــزام املدعــى عليــه‬\n‫بدفــع أجــرة الســنة اجلاريــة التــي بــدأت يف ‪1433/9/1‬ه ـ مئــة وســتة آالف‬\n‫وأربعمئــة وثمانــن ريــال وتكلفــة إصــاح العقــار للتلفيــات التــي تســببت‬\n‫فيهــا الشــركة خمســة وســتني ألــف ريــال‪ ،‬أقــر وكيــل املدعــى عليهــا‬\n‫بالعقــد والثمــن إال أنــه دفــع بــأن العقــد تضمــن بــأن ملوكلتــه فســخ العقد‬\n‫متــى شــاءت علــى أن تدفــع أجــرة الســنة التــي جــرى فســخ العقــد خاللهــا‬\n‫كاملــة وأن موكلتــه لــم تتــرك تلفيــات وإن مــا يطالــب بــه مجــرد أعيــان‬\n‫اســتهالكية جــرت العــادة تلفهــا مبضــي املــدة وأعمــال جبــس وفواصــل‬\n‫عملــت برضــاه وطوعــه واختيــاره وأنهــا ســلمت العقــار لــه لــذا فتطلــب‬\n‫رد دعــواه‪ ،‬جــرى الكتابــة لهيئــة النظــر فعــادت اإلفــادة بأنهــا تــرى مــا‬\n‫يلــي‪ :‬أوال‪ /‬إزالــة الفواصــل الصناعيــة لعــدم توافقهــا ألصــول الصنعــة‬\n‫مــن جهــة عــدم مالئمتهــا ملــا هــي فيــه‪ .‬ثانيــا‪ :‬إزالــة البــاب املوضــوع بالــدور‬\n\n\n                                                                                            ‫‪148‬‬\n\f      ‫العلــوي وبنــاء اجلــدار املهــدوم بالــدور األول وإعــادة تأهيلــه حســب أصــول‬\n      ‫الصنعــة وتقديــر ذلــك ألفــان وثالثمئــة ريال ‪ .‬ثالثــا‪ /‬تركيب درفة املنيوم‬\n      ‫ويقــدر ذلــك بخمســمائة ريــال‪ .‬رابعــا‪ /‬تركيــب األدوات التالفــة وتقديــر‬\n      ‫ذلــك ثالثــة آالف وأربعمائــة ريــال‪ .‬خامســا‪ /‬تســليم مفاتيــح األبــواب‬\n      ‫أو تغيــر القلــوب وتقديــر ذلــك مائتــان وخمســن ريــال‪ .‬سادســا‪/‬عمل‬\n      ‫نظافــة للموقــع مــع ترويــب مواضــع التنديــة يف دورات امليــاه ويقــدر ذلــك‬\n      ‫بخمســمائة ريــال‪ .‬ســابعا ‪ /‬تعــذر اختبــار عمــل املكيفــات ومضخــات‬\n      ‫امليــاه لعــدم وجــود كهربــاء باملوقــع هــذا مــا جــرى تقديــره ‪.‬إ‪.‬ه ـ ثــم جــرى‬\n      ‫إعــادة املعاملــة لهيئــة النظــر لإلفــادة عــن التلفيــات املوجــودة يف العقــار‬\n      ‫وهــل هــي طبيعيــة أم نتيجــة تعــد أو تفريــط مــن املســتأجر وحصرهــا‬\n      ‫مفصــا وكذلــك حصــر أدوات احلمــام املفقــودة مفصــا وتقديرهــا‪،‬‬\n      ‫عــادت اإلفــادة باإلشــارة للتلفيــات وبعــض القطــع املنزوعــة واإلشــارة‬\n      ‫لســعرها التالفــة وأنهــا نتيجــة اإلهمــال‪ ،‬عليــه وبعــد االطــاع علــى العقــد‬\n      ‫بــن الطرفــن والن الفقــرة الثالثــة مــن العقــد نصــت علــى أنــه ال يحــق‬\n      ‫للطــرف الثانــي إضافــة أو تغييــر معالــم العــن املؤجــرة مــن دهانــات أو‬\n      ‫أعمــال ديكــور إال بعــد موافقــة الطــرف األول ‪ ،‬كمــا يتحمــل الطــرف‬\n      ‫الثانــي جميــع أعمــال الصيانــة مــع مراعــاة احتســاب اإلســتهالك‬\n      ‫الطبيعــي للمبنــى و محتوياتــه عنــد نهايــة العقــد ‪ ،‬وقــد وافــق الطــرف‬\n      ‫األول علــى الســماح للطــرف الثانــي بعمــل فواصــل جيبســون بــورد أو‬\n      ‫خشــبية لتقســيم املســاحات الكبيــرة بالبيــت حتــى ميكــن اســتخدامها‬\n      ‫وعلــى حســاب الطــرف الثانــي ‪ ،‬كمــا أن الفقــرة اخلامســة مــن العقــد‬\n      ‫نصــت علــى أنــه يف حالــة رغبــة الطــرف الثانــي بإخــاء املــكان املؤجــر‬\n      ‫عليــه إبــاغ الطــرف األول قبــل انتهــاء مــدة العقــد بشــهر علــى األقــل ‪،‬‬\n\n\n‫‪149‬‬\n\f‫ويف حــال رغــب يف إخــاء العقــار قبــل نهايــة املــدة يلتــزم الطــرف الثانــي‬\n‫بســداد كامــل اإليجــار للســنة اإليجاريــة التــي يرغــب اإلخــاء خاللهــا‪،‬‬\n‫وألن املدعــى عليــه قــام بأعمــال يف العــن املســتأجرة بــدون إذن املدعــي‬\n‫أصالــة كمــا أن األعمــال التــي اســتأذن فيهــا لــم يقــم بعملهــا وفــق أصــول‬\n‫الصنعــة كمــا أنــه حينمــا رغــب إنهــاء العقــد لــم يقــم بإصــاح مــا أتلفــه‬\n‫أو قــام بتغييــره أو مــا فقــد منــه قبــل الوقــت احملــدد وهــو ‪1433/9/1‬ه ـ‬\n‫وألن املدعــي أصالــة حينمــا امتنــع مــن اســتالم العــن حتــى يتــم اصالحهــا‬\n‫ودفــع تكلفــة اإلصــاح فــإن تصرفــه صحيحــا ألن ذلــك يحتــاج إلــى وقت‬\n‫وثمــن وهــو نتيجــة تعــدي أو تفريــط مــن املســتأجر واملســتأجر إذا فــرط‬\n‫أو تعــدى يف العــن املســتأجرة ضمــن ينظــر كشــاف القنــاع ‪،139/9‬‬\n‫وألن ممــا قررتــه هيئــة النظــر هــو عمــل نظافــة للموقــع وترويــب مواضــع‬\n‫التنديــة يف دورات امليــاه مببلــغ خمســمائة ريــال وألن هــذا مــن عمــارة‬\n‫العــن املؤجــرة وليــس الزمــا للمســتأجر ينظــر كشــاف القنــاع ‪،109/9‬‬\n‫لذلــك كلــه فقــد حكمــت الدائــرة علــى املدعــى عليــه أصالــة بــأن يدفع‬\n‫للمدعــي مــا يلــي‪ :‬أوال ‪ /‬تكلفــة اإلصالحــات واملفقــودات يف املبنــى التي‬\n‫قدرتهــا هيئــة النظــر فيمــا عــدا تنظيــف املوقــع وترويــب مواقــع التنديــة‬\n‫يف دورات امليــاه‪ .‬ثانيــا ‪ /‬أجــرة املــدة التــي بــدأت يف ‪1433/9/1‬هــ‪ .‬ثالثا‪/‬‬\n‫دفــع اســتهالك املــاء والكهربــاء حتــى ‪1434/8/30‬ه ـ رابعــا ‪ /‬إلــزام‬\n‫املدعــى عليــه أصالــة بإخــاء املبنــى يف مــدة أقصاهــا ‪1434/9/1‬ه ـ‬\n‫وتســليمه للمدعــي أصالــة خاليــا مــن الشــواغل ‪-‬بعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــي وكالــة القناعــة وقــرر املدعــى عليــه وكالــة عــدم‬\n‫القناعــة وطلــب رفعــه حملكمــة االســتئناف فأفهــم بالتعليمــات‪ -‬صــدق‬\n                                             ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n                                                                                     ‫‪150‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪... .................‬القاضــي يف احملكمــة‬\n      ‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33683430‬وتاريــخ‬\n      ‫‪1433/11/30‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332150769‬وتاريــخ‬\n      ‫‪1433/11/30‬هـ حضر ‪.................‬بالســجل املدني رقم ‪1001974151‬‬\n      ‫بوكالتــه عــن أبيــه ‪.................................‬بالوكالــة الصــادرة مــن‬\n      ‫كتابــة العــدل الثانيــة مبكــة برقــم ‪ 35244/5049‬يف ‪1432/12/23‬هـ‬\n      ‫والتــي تخولــه إقامــة وســماع الدعــاوى واملرافعــة واملدافعــة واإلقــرار‬\n      ‫والصلــح والتنــازل والتأجيــر واســتالم األجــرة ‪..‬الــخ وادعــى علــى‬\n      ‫احلاضــر معــه ‪ .........................‬بالســجل املدنــي رقــم ‪1008486803‬‬\n      ‫بوكالتــه عــن ‪ ...........................‬بصفتــه رئيــس مجلــس املديريــن‬\n      ‫لشــركة ‪ ..........................‬بالســجل التجــاري رقــم ‪ ........................‬يف‬\n      ‫‪1411/8/9‬ه ـ وذلــك بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫مبكــة برقــم ‪ 20724/4566‬يف ‪1431/6/25‬ه ـ والتــي تخولــه إقامــة‬\n      ‫وســماع عمــوم الدعــاوى واملرافعــة واملدافعــة ‪..‬الــخ قائــا يف دعــواه‬\n      ‫عليــه لقــد أجــر موكلــي والــدي علــى شــركة ‪ ...........................‬العقــار‬\n      ‫الواقــع مبكــة حــي الهجــرة ملــدة خمــس ســنني بــدأت يف ‪1430/9/1‬ه ـ‬\n      ‫وتنتهــي يف ‪1435/8/30‬ه ـ بأجــرة ســنوية ثمانــن ألــف ريــال للســنة‬\n      ‫األولــى وثمانيــة وثمانــن ألــف ريــال للســنة الثانيــة وســتة تســعني ألفــا‬\n      ‫وثمامنائــة ريــال للســنة الثالثــة ومائــة وســتة آالف وأربعمائــة وثمانــن‬\n      ‫ريــاال للســنة الرابعــة ومائــة وســبعة عشــر ألفــا ومائــة وأربعــة وســتني‬\n\n‫‪151‬‬\n\f‫ريــاال للســنة اخلامســة علــى أن تســلم األجــرة يف بدايــة شــهر رمضــان مــن‬\n‫كل ســنة إيجاريــه وقــد اســتلم موكلــي أجــرة الســنني الثــاث األولــى‬\n‫ثــم بتاريــخ ‪1433/7/28‬ه ـ وردتنــا رســالة مــن املدعــى عليــه يذكــر‬\n‫أن الشــركة ترغــب يف فســخ العقــد وال ترغــب االســتمرار فيــه وأنهــا‬\n‫ستســلم العقــار ملوكلــي يف ‪1433/9/1‬ه ـ وقــد رد موكلــي عليهــم‬\n‫بأنــه إذا ســلمت الشــركة العقــار ســليما نظيفــا كمــا مت تســليمه لهــا‬\n‫بــدون تلفيــات وال تعديــات فــإن موكلــي موافــق علــى ذلــك فطلبــت‬\n‫الشــركة مــن موكلــي احلضــور لالطــاع علــى البيــت وبيــان مــا فيــه‬\n‫مــن تلفيــات فحضــر موكلــي إلــى العقــار وشــاهد تلفيــات كبيــرة يف‬\n‫العقــار تســببت فيهــا الشــركة وأبلــغ الشــركة انــه لــن يســتلم العقــار‬\n‫وال يوافــق علــى فســخ العقــد وأنــه يطالــب الشــركة بأجــرة هــذا العــام‬\n‫وإصــاح تلفيــات العقــار قبــل اســتالمه فطلبــت الشــركة مــن موكلــي‬\n‫بيــان تكلفــة إصــاح العقــار فأحضــر موكلــي املختصــن وتبــن أن‬\n‫اإلصــاح يكلــف خمســة وســتني ألــف ريــال وطلــب منهــم موكلــي دفــع‬\n‫هــذا املبلــغ فرفضــت الشــركة ذلــك فأطلــب إلــزام املدعــى عليــه بدفــع‬\n‫أجــرة هــذا الســنة التــي بــدأت يف ‪1433/9/1‬ه ـ مبلــغ وقــدره مائــة وســتة‬\n‫آالف وأربعمائــة وثمانــون ريــاال وتكلفــة إصــاح العقــار للتلفيــات التــي‬\n‫تســببت فيهــا الشــركة مبلــغ وقــدره خمســة وســتون ألــف ريــال هــذه‬\n‫دعــواي وبســؤال املدعــي وكالــة عــن دعــوى املدعــي أبــرز إجابتــه بورقــة‬\n‫هــذا نصهــا نوجــز ردنــا علــى الئحــة الدعــوى املقدمــة مــن املدعــي ونقســم‬\n‫ردنــا علــى شــقني األول مــا يتعلــق بحــق املدعــى عليــه بفســخ العقــد قبــل‬\n‫انتهــاء أجلــه ومدتــه العقــد شــريعة املتعاقديــن واملســلمون علــى شــروطهم‬\n‫فعقــد اإليجــار أعطــي للمدعــى عليهــا موكلتــي حــق فســخ العقــد قبــل‬\n\n\n                                                                                    ‫‪152‬‬\n\f      ‫انتهــاء مدتــه شــريطة أن يتــم ســداد اإليجــار للســنة اإليجاريــة التــي‬\n      ‫ينفســخ فيهــا العقــد وذلــك بالبنــد سادســا مــن العقــد صفحــة رقــم (‬\n      ‫‪ )2‬والتــي تنــص علــى ( يف حالــة رغبــة الطــرف الثانيــة بإخــاء املــكان‬\n      ‫املؤجــر عليــه إبــاغ الطــرف األول قبــل انتهــاء مــدة العقــد بشــهر علــى‬\n      ‫األقــل ويف حــال رغــب يف إخــاء العقــار قبــل نهايــة املــدة يلتــزم الطــرف‬\n      ‫الثانــي بســداد كامــل اإليجــار للســنة اإليجاريــة التــي يرغــب اإلخــاء‬\n      ‫خاللهــا ) وبالفعــل فقــد ســددت املدعــى عليهــا األجــرة كاملــة للســنة‬\n      ‫التــي مت الفســخ خاللهــا وهــو مــا أقــر بــه املدعــي يف الئحــة دعــواه حيــث‬\n      ‫اقــر بســدادنا األجــرة لــه واســتالمه إياهــا وكذلــك اقــر بإخطــار املدعــى‬\n      ‫عليهــا لــه بفســخ العقــد حيــث أن العقــد بالبنــد اخلامــس أعطــي للمدعــى‬\n      ‫عليهــا حــق الفســخ شــريطة اإلخطــار املســبق قبــل نهايــة الســنة االيجاريــة‬\n      ‫مبــدة شــهر وهــو مــا اقــر بــه املدعــي يف الئحــة دعــواه يف أنــه تســلم‬\n      ‫اإلخطــار يف ‪1433/7/28‬ه ــومن هنــا يتضــح أن املدعــى عليهــا مــن حقها‬\n      ‫فســخ العقــد وإنهــاؤه قبــل حلــول اجــل العقــد ويتضــح أيضــا أن املدعــى‬\n      ‫عليهــا قــد أوفــت بكامــل التزامهــا مــع املدعــي وبالتالــي فليــس للمدعــي‬\n      ‫وجــه حــق فيمــا يطالــب بــه مــن ســداد أجــرة عــن ســنة إيجاريــة جديــدة‬\n      ‫أو ســداد األجــرة لســنوات العقــد املتبقيــة ألن العقــد شــريعة املتعاقديــن‬\n      ‫واملســلمون علــى شــروطهم ‪ .‬ثانيــا فيمــا يتعلــق بطلــب املدعــي إصــاح‬\n      ‫العــن املؤجــرة بــادي ذي بــدء أشــير إلــى أن العقــار موضــوع الدعــوى وهــو‬\n      ‫مــا اســماه املدعــي فيــا هــو يف احلقيقــة منزل مكون مــن طابقني وغرف‬\n      ‫ملحقــة للحــارس وتاريــخ بنــاؤه يعــود إلــى أكثــر مــن خمــس وعشــرون‬\n      ‫ســنة ومــا يتحــدث عنــه املدعــي ويطالــب بــه هــو إعــادة طــاء اجلــدران‬\n      ‫وتغييــر ليــات الشــطافات والقاعــدة البالســتيكية لكراســي احلمامــات‬\n\n\n‫‪153‬‬\n\f‫وتغييــر الكوالــن واألقفــال وهــي طلبــات يف احلقيقــة جــرى العــرف علــى‬\n‫انهــا تقــادم طبيعــي ألي مــكان مؤجــر ومــن الطبيعــي أنــه عنــد انتهــاء‬\n‫العقــد يقــوم املالــك بعمــل الصيانــة للعقــار إلعــادة تأجيــره ومــا يطالــب بــه‬\n‫املدعــي هــو أمــر غيــر مألــوف ولــم يجــري عليــه العــرف فالبنــاء كمــا هــو‬\n‫ولــم نقــوم بهــدم املــكان أو إزالــة أعمــدة أو االنتقــاص مــن املبنــى شــيء‬\n‫اللهــم إن اســتخدامنا للمــكان يأتــي يف طــور االســتخدام الطبيعــي‬\n‫ألي مــكان مؤجــر عــودا علــى بــدء فإننــا نشــير أخيــر العقــد اإليجــار‬\n‫يف أننــا أوضحنــا بالبنــد الثالــث مــن عقــد اإليجــار عبــارة ( مــع مراعــاة‬\n‫اإلهــاك الطبيعــي للعقــار ) أخيــرا فإننــا نتقــدم لفضيلتكــم بردنــا حــول‬\n‫مــا أثــاره املدعــي يف دعــواه ونطلــب رد الدعــوى لعــدم قيامهــا علــى ســند‬\n‫مــن الشــرع أو النظــام أو العــرف أو الواقــع فهــي ال تعــدو كونهــا محاولــة‬\n‫للتربــح واإلثــراء بــا ســبب علــى حســاب املدعــى عليهــا فالعقــار حتــت‬\n‫يــده ولــه أن يتصــرف فيــه كيفمــا يشــاء ووقتمــا يشــاء واهلل ولــي التوفيــق‬\n‫أه ـ وبعــرض ذلــك علــى املدعــي وكالــة وأبــرز رده بورقــة هــذا نصهــا‬\n‫أفيــد فضيلتكــم بالتالــي ‪ -1‬املــادة الثالثــة مــن عقــد االيجــار املبــرم مــع‬\n‫الســادة مجموعــة ‪ ...........‬نصــت علــى ( ال يحــق للطــرف الثانــي إضافــة أو‬\n‫تغييــر يف معالــم العــن املؤجــرة مــن دهانــات أو أعمــال ديكــور أو‪..‬الــخ)‬\n‫إال بعــد الرجــوع وموافقــة الطــرف األول وحيــث أنــه قــام بهــدم جــدار‬\n‫وعمــل بــاب دون الرجــوع إلينــا ‪ -2‬املوافقــة املبدئيــة علــى عمــل جبــس‬\n‫بــورد فواصــل بــن الغــرف ولكــن عملــت بطريقــة عشــوائية وليســت‬\n‫حضاريــة ‪ -3‬أرفــق لفضيلتكــم بعــض الصــور اخلاصــة باملبنــى املتهالــك‬\n‫والــذي ميثــل ‪ %10‬مــن الدمــار املوجــود األمــر الــذي دفعنــي بعــدم اســتالم‬\n‫املبنــى ‪ -4‬شــرط مــن شــروط مكاتــب العقــار املوضوعة مــن قبل اجلهات‬\n\n\n                                                                                         ‫‪154‬‬\n\f      ‫املختصــة بــأن علــى املســتأجر إعــام املؤجــر خطيــا إذا رغــب يف جتديــد‬\n      ‫العقــار قبــل حلــول مــدة انتهــاء االيجــار املنصــوص عليــه يف هــذا العقــد‬\n      ‫بأســبوعني علــى األقــل وإذا لــم يقــم بتنفيــذ هــذا الشــرط يعتبر املســتأجر‬\n      ‫مســتاجرا نفــس العقــار لســنة أخــرى ومطالــب بدفــع االيجــار كامــا‬\n      ‫كمــا أن زيــادة جــزء مــن الســنة يعتبــر إيجــار عــام كامــل بــدون مناقشــة‬\n      ‫ألي ســبب كان وحيــث أن القضيــة املاثلــة امــام فضيلتكــم واضحــة‬\n      ‫وموثقــة بأدلــة مصــورة وال تخفــى علــى املدعــى عليــه فإننــي أطلــب مــا‬\n      ‫يلــي ‪ -1‬عــدم املماطلــة وعمــل جميــع االصالحــات وتســليمنا العــن كمــا‬\n      ‫اســتلمها وبإشــراف مهنــدس مــن قبلنــا مرفــق صــورة مــن االســتالم‬\n      ‫‪-2‬دفــع إيجــار الســنة ‪1434-1433‬ه ـ كامــا وعمــل االصالحــات‬\n      ‫خــال ‪ 8‬أشــهر ‪ -3‬تســليمنا جميــع مفاتيــح األبــواب الداخليــة واخلارجيــة‬\n      ‫عنــد انتهــاء فتــرة االيجــار وهــو نهايــة شــهر شــعبان ‪1434/8/30‬ه ـ‬\n      ‫‪-4‬عمــل محضــر اســتالم وتســليم بــن الطرفــن أه ـ وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه وكالــة أبــرز رده بورقــة هــذا نصهــا املوضــوع ‪ :‬الــرد علــى‬\n      ‫خطــاب املدعــي‪ ...........‬املقــدم بجلســة يــوم الثالثــاء ‪ 1434-1-6‬ه ـ‬\n      ‫بالقضيــة رقــم ( ‪ . ) 332150769‬ربط ـ ًا بالــرد الــذي تقدمنــا بــه بجلســة‬\n      ‫يف‪1433/12/29‬ه ـ ‪ -‬والتــي يحــاول فيهــا املدعــي قلــب احلقائــق الثابتــة‬\n      ‫واملعضــدة بإثباتــات كتابيــة ومــا يحــاول إثارتــه بدفــوع واهيــة مــا انــزل‬\n      ‫اهلل بهــا مــن ســلطان للســعي نحــو حتقيــق مكاســب واالثــراء بــا ســبب‬\n      ‫علــي حســاب املدعــي عليهــا و اســمحوا لــي فضيلتكــم بالــرد ونوجــزه يف‬\n      ‫التالــي‪ :‬االول ‪ :‬مــا يتعلــق بدفــع األجــرة واســتالم الفيــا ‪ :‬ال نعلــم مــن أيــن‬\n      ‫أتــي املدعــي مبــا وصفــه مخالفتنــا (( شــرط مــن شــروط مكاتــب العقــار‬\n      ‫املوضوعــة مــن قبــل اجلهــات املختصــة )) فمــا هــي مكاتــب العقــار؟؟ ومــا‬\n\n\n‫‪155‬‬\n\f‫هــي شــروطها ؟؟ ومــا هــي اجلهــات املختصــة ؟؟ ومــا هــي عالقــة مكاتــب‬\n‫العقــار بالعالقــة التعاقديــة وبالدعــوي احلاليــة ‪،‬فاملدعــي يحــاول إغفــال‬\n‫العقــد ويخالــف القواعــد الشــرعية املتأصلــة وهــي أن املســلمون علــى‬\n‫شــروطهم وأن العقــد شــريعة املتعاقديــن ‪ .‬فالثابــت مــن خــال خطــاب‬\n‫االشــعار باإلخــاء املوجــه مــن املدعــي عليــه إلــى املدعــي والــذي قــام‬\n‫باســتالمه املدعــي بتاريــخ ‪ 1433-7-28‬ه ـ ‪ ،‬وفيــه نشــعره برغبتنــا‬\n‫يف إنهــاء العقــد بإنتهــاء الســنة االيجاريــة املدفوعــة لــه والتــي تنتهــي يف‬\n‫‪1433/9/1‬ه ـ وذلــك بحســب البنــد خامســا مــن العقــد ونصــه (( يف حال‬\n‫رغبــة الطــرف الثانــي بإخــاء املــكان املؤجــر عليــه ابــاغ الطــرف االول‬\n‫قبــل انتهــاء مــدة العقــد بشــهر علــي االقــل ويف حــال رغــب يف اخــاء‬\n‫العقــار قبــل نهايــة املــدة يلتــزم بســداد كامــل االيجــار للســنة التــي يرغــب‬\n‫االخــاء خاللهــا )) ‪ .‬وهومــا اقــر بــه املدعــي يف الئحــة دعــواه يف انه تســلم‬\n‫االخطــار ولكــن أغفــل ذكــر التاريــخ اخلــاص باســتالم اخلطــاب اال انــه‬\n‫أقــر يف الئحــة دعــواه بإســتالمه االجــرة حتــي نهايــة الســنة االيجاريــة‬\n                                               ‫التــي انتهــت يف ‪1433/9/1‬هــ‪.‬‬\n‫ومــن هنــا يتضــح عــدم أحقيــة املدعــي فيمــا يطالــب بــه مــن ســداد أجــرة‬\n‫جديــدة ألن العقــار أصبــح يف ملكــه وحتــت تصرفــه ‪ .‬ثاني ـاً‪ :‬يف الــرد‬\n‫علــي طلــب تســليم العقــار يف ‪1433/8/30‬ه ــواستالم املفاتيــح‪ :‬احلقيقــة‬\n‫اننــا نســتغرب مــن هــذا الطلــب وكيــف نســلمه العقــار وندفــع أجرتــه‬\n‫والعقــار حتــت يديــه وتصرفــه وإال كيــف صــور املــكان و مــن أيــن أتــي‬\n‫بالصــور التــي ســاقها وقدمهــا ومــن أيــن قــام بعمــل حصــر كمــا يدعــي‬\n‫بآثــار الدمــار وكأن قنبلــة ســقطت علــى العقــار كمــا جــاء بوصفــه‬\n‫مــن تهويــل وخيــال يف الوصــف‪ .‬فالعقــار حتــت يــد املدعــي وحتــت‬\n\n\n                                                                                        ‫‪156‬‬\n\f      ‫تصرفــه ولديــه مفاتيحــه ويحــاول تأجيــره علــي الغيــر ومعــروض لــدي‬\n      ‫اكثــر مــن مكتــب عقــاري منــذ فتــرة وحتــي تاريخــه لــم يقــوم بتأجيــره‬\n      ‫حيــث ان املــكان هــو يف االصــل وكمــا ذكرنــا ســكن عمــال وليــس‬\n      ‫مقســما كشــقق ســكنية ‪ .‬ثالثــا‪ :‬فيمــا يتعلــق بطلــب املدعــي اصــاح‬\n      ‫العــن املؤجــرة‪ :‬اســمحوا لنــا فضيلتكــم أن نكــرر بعــض مــا ذكرنــاه‬\n      ‫مبذكرتنــا الســابقة يف أن العقــار موضــوع الدعــوى وهــو مــا اســماه‬\n      ‫املدعــي فيــا هــو يف احلقيقــة منــزل مكــون مــن طابقــن وغــرف ملحقــة‬\n      ‫للحــارس وتاريــخ بنــاؤه يعــود الــي أكثــر مــن خمــس وعشــرون ســنة وقــد‬\n      ‫كان مجهــزا مــن قبــل كســكن للعمــال مــن خــال التجهيــزات التــي‬\n                                   ‫كانــت بــه وهــو مــا دعانــا يف احلقيقــة لتأجيــره‪.‬‬\n      ‫ومــا يتحــدث عنــه املدعــي مــن عمــل فواصــل وقواطــع جبــس فقــد كانــت‬\n      ‫بعلمــه وموافقتــه الصريحــة وباتفاق مكتوب بالعقــد بالبند ثالثا ((وافق‬\n      ‫الطــرف األول علــي الســماح للطــرف الثانــي بعمــل فواصــل جبســون بــورد‬\n      ‫أو خشــبية لتقســيم املســاحات الكبيرة ليتم اســتخدامها وعلي حســاب‬\n      ‫الطــرف الثانــي )) أمــا مــا يتحــدث عنــه مــن أن منظرهــا غيــر حضــاري‬\n      ‫وعشــوائية فهــذا شــأنه والعقــار بحوزتــه إن شــاء ابقاهــا وإن شــاء نزعهــا‬\n      ‫فهــي جتهيــزات وافــق عليهــا مســبقا وعلــي علــم بهــا وليــس علــي املدعــي‬\n      ‫عليهــا ادنــي التــزام أو اتفــاق بالعقــد علــي نزعهــا عــن إخــاء العقــار ‪.‬‬\n      ‫ومــا يتحــدث عنــه املدعــي ويطالــب بــه هــو إعــادة طــاء اجلــدران وتغييــر‬\n      ‫ليــات الشــطافات والقاعــدة البالســتيكية لكراســي احلمامــات وتغييــر‬\n      ‫الكوالــن واألقفــال وهــي طلبــات يف احلقيقــة جــرى العــرف علــي أنهــا‬\n      ‫تقــادم طبيعــي ألي مــكان مؤجــر ومــن الطبيعــي انــه عنــد انتهــاء العقــد‬\n      ‫يقــوم املالــك بعمــل الصيانــة للعقــار إلعــادة تأجيــره ‪ ،‬ومــا يطالــب بــه‬\n\n\n‫‪157‬‬\n\f‫املدعــي هــو أمــر غيــر مألــوف ولــم يجــري عليــه العــرف ‪ .‬فالبنــاء كمــا‬\n‫هــو ولــم نقــوم بهــدم املــكان أو إزالــة أعمــدة أو االنتقــاص مــن املبنــى‬\n‫شــيء اللهــم إن اســتخدامنا للمــكان يأتــي يف طــور االســتخدام الطبيعي‬\n‫ألي مــكان مؤجــر‪ .‬عــودا علــي بــدء فإننــا نشــير أخيــرا لعقــد اإليجــار‬\n‫يف أننــا أوضحنــا بالبنــد الثالــث عبــارة (مــع مراعــاة اإلهــاك الطبيعــي‬\n‫للعقــار) ‪ .‬أخيــرا فإننــا نتقــدم لفضيلتكــم بردنــا حــول مــا أثــاره املدعــي‬\n‫يف دعــواه ونطلــب ‪ :‬رد الدعــوي لعــدم قيامهــا علــي ســند مــن الشــرع‬\n‫او النظــام او العــرف أو الواقــع فهــي ال تعــدو كونهــا محاولــة للتربــح‬\n‫واإلثــراء بــا ســبب علــي حســاب املدعــي عليهــا فالعقــار حتــت يــده‬\n‫وبحوزتــه ولــه ان يتصــرف فيــه كيفمــا يشــاء ‪ .‬أه ـ فطلبــت مــن الطرفــن‬\n‫العقــد فأبــرز املدعــي وكالــة عقــدا وهــذا نصــه عقــد إيجــار بحمــد اهلل‬\n‫ال‬\n‫وتوفيقــه مت يف يــوم الســبت بتاريــخ ‪ 1430-9-1‬ه ـ اإلتفــاق بــن ك ً‬\n‫مــن ‪ :‬الســيد ‪ ........... :‬ســعودي اجلنســية هويــه رقــم (‪ )...........‬تاريــخ ‪-24‬‬\n‫‪1386-3‬ه ـ صــادره مــن مكــة املكرمــة وهــو املؤجــر ويشــار إليــه فيمــا‬\n‫بعــد بالطــرف األول ‪.‬الســادة ‪ :‬شــركة ‪ ......................‬و ميثلهــم يف هــذا‬\n‫العقــد الوكيــل الشــرعي مبوجــب صــك وكالــه رقــم ( ‪ ) 47013‬وتاريــخ‬\n‫‪1429-9-6‬ه ـ الصــادرة مــن كتابــة عــدل الثانيــة مبكــة املكرمــة‬\n‫الســيد‪ .......................‬ســعودي اجلنســية رقــم الهويــة (‪) .........................‬‬\n‫تاريــخ ‪ 1410-1-22‬ه ـ صــادره مــن مكــة املكرمــة وهــو املســتأجر و‬\n‫يشــار إليــه فيمــا بعــد بالطــرف الثانــي ‪ .‬علــى اآلتــي‪ :‬أو ًال ‪ :‬اطلــع الطــرف‬\n‫الثانــي علــى العــن املؤجــرة والكائنــة بحــي الهجــرة الطريــق الدائــري‬\n‫الثالــث فيــا دوريــن باملكيفــات و عددهــا (‪ )24‬مكيــف و بحالــه جيــده‬\n‫جــد ًا خلــف متوينــات ‪ ......‬الســتغالله كســن ملوظفــن شــركة ‪. ...........‬‬\n\n\n                                                                                               ‫‪158‬‬\n\f      ‫ثاني ـ ًا ‪ :‬حتمــل الطــرف الثانــي املســؤولية القانونيــة عــن اســتعمال العــن‬\n                          ‫املؤجــرة مبجــرد اســتالمه للعــن و بدايــة عقــد اإليجــار‪.‬‬\n      ‫ثالث ـ ًا ‪ :‬ال يحــق للطــرف الثانــي إضافــة أو تغييــر معالــم العــن املؤجــرة‬\n      ‫مــن دهانــات أو أعمــال ديكــور إال بعــد موافقــة الطــرف األول ‪ ،‬كمــا‬\n      ‫يتحمــل الطــرف الثانــي جميــع أعمــال الصيانــة مــع مراعــاة احتســاب‬\n      ‫اإلهــاك الطبيعــي للمبنــى و محتوياتــه عنــد نهايــة العقــد ‪،‬وقــد وافــق‬\n      ‫الطــرف األول علــى الســماح للطــرف الثانــي بعمــل فواصــل جيبســن بــورد‬\n      ‫أو خشــبيه لتقســيم املســاحات الكبيرة بالفيال حتى ميكن استخدامها‬\n      ‫و علــى حســاب الطــرف الثانــي‪ .‬رابع ـ ًا ‪ :‬يلتــزم الطــرف الثانــي بتســديد‬\n      ‫فاتــورة الكهربــاء وامليــاه و الصــرف الصحــي اخلاصــة بالعــن املؤجــرة‬\n      ‫ـداء مــن تاريــخ االســتالم ‪ .‬خامس ـ ًا ‪ :‬يف حالــة رغبــة الطــرف الثانــي‬ ‫ابتـ ً‬\n      ‫بإخــاء املــكان املؤجــر عليــه إبــاغ الطــرف األول قبــل انتهــاء مــدة‬\n      ‫العقــد بشــهر علــى األقــل ‪ ،‬و يف حــال رغــب يف إخــاء العقــار قبــل نهايــة‬\n      ‫املــدة يلتــزم الطــرف الثانــي بســداد كامــل اإليجــار للســنه اإليجاريــة‬\n      ‫التــي يرغــب اإلخــاء خاللهــا ‪ .‬سادس ـ ًا ‪ :‬مــدة العقــد املبــرم (‪ )5‬خمــس‬\n      ‫ـداء مــن تاريــخ ‪1430-9-1‬ه ـ وحتــى ‪1435-8-30‬ه ـ قابلــه‬          ‫ســنوات ابتـ ً‬\n      ‫للتجديــد ملــده مماثلــه ‪ ،‬و يف حــال رغبــة الطــرف األول بعــدم جتديــد‬\n      ‫مــدة العقــد فــإن عليــه إبــاغ الطــرف الثانــي قبــل انتهــاء مــدة العقــد‬\n      ‫بشــهر علــى األقــل ‪ .‬ســابع ًا ‪ :‬يلتــزم الطــرف الثانــي بدفــع قيمــة اإليجــار‬\n      ‫كدفعــه واحــده كاملــه أول كل عــام مــن تاريــخ العقــد ‪.‬ثامنـ ًا ‪ :‬يدفــع‬\n      ‫الطــرف الثانــي للطــرف األول مبلــغ و قــدره (‪ ) 80.000‬ثمانــون ألــف‬\n      ‫ريــال ال غيــر للســنه األولــى مــن العقــد مــع زيــادة ســنوية بنســبة (‪)% 10‬‬\n      ‫مــن قيمــة اإليجــار املذكــور أعــاه اعتبــار ًا مــن الســنه الثانيــة ويعتبــر‬\n\n\n‫‪159‬‬\n\f‫قيمــة إيجــار ملــدة ســنه كاملــه تبــد ًا يف تاريــخ ‪1430/9/1‬ه ـ وتنتهــي‬\n‫يف تاريــخ ‪ 1431-8-30‬ه ـ حســب التوضيــح التالــي ‪ :‬م تاريــخ اســتحقاق‬\n                           ‫اإليجــار مبلــغ اإليجــار املســتحق بالريــال ســعودي‬\n                                                 ‫‪ 1431-9-1 1‬هـ ‪ 88.000‬ريال‬\n                                                 ‫‪ 1432-9-1 2‬هـ ‪ 96.800‬ريال‬\n                                               ‫‪ 1433-9-1 3‬هـ ‪ 106.480‬ريال‬\n                                               ‫‪ 1434-9-1 4‬هـ ‪ 117.164‬ريال‬\n‫و إلحقــاق حــق كل طــرف أبــرم هــذا العقــد بنســختني أصليتــن بثمانيــة‬\n‫بنــود ملزمــة قانون ـ ًا و شــرع ًا للعمــل بــه لــكل مــن الطرفــن و اهلل ولــي‬\n‫التوفيــق و خيــر الشــاهدين أه ــو بعرضــه علــى املدعــي وكالــة صــادق‬\n‫عليــه وبســؤال املدعــي وكالــة هــل وافــق موكلــه علــى مــا قام بــه املدعى‬\n‫عليــه مــن تعديــات وإضافــات للمبنــى فقــال إن املدعــى عليــه عمــل‬\n‫أعمــال كثيــرة يف املبنــى وموكلــي لــم يوافــق إال علــى أعمــال اجلبســون‬\n‫بــورد ( فواصــل بــن الغــرف ) وأمــا مــا عــدا ذلــك فلــم يوافــق عليــه ولــم‬\n‫يبلغــه بــه املدعــى عليــه ومــن هــذه األعمــال التــي قــام بهــا املدعــى عليــه‬\n‫ولــم يبلــغ بهــا موكلــي وضــع بــاب خشــب بطريقــة عشــوائية بالــدور‬\n‫العلــوي وهــدم جــدار بالصالــون األرضــي كمــا أن اجلبســون بــورد الــذي‬\n‫وضعــوه كان بطريقــة ســيئة عشــوائية كمــا أن هنــاك اتالفــات‬\n‫باحلمامــات واملكيفــات كمــا أن أحــد األبــواب احلديــد يف امللحــق‬\n‫اخلارجــي غيــر موجــود وكذلــك اتالفــات يف الكهربــاء والبويــة‬\n‫واملكيفــات ونقــص يف محتويــات احلمامــات فبعضهــا غيــر موجــود أو‬\n‫مكســور وكل ذلــك يــدل علــى أنــه ليــس إهــاك طبيعــي وإمنــا عمــل‬\n‫مقصــود هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال أمــا‬\n\n\n                                                                                        ‫‪160‬‬\n\f      ‫اجلبســون بــورد فقــد مت تركيبــه عــادي يف حــدود الطبيعــي وموافــق‬\n      ‫للمواصفــات وأمــا مــا فقــد ومالــم يفقــد فــا نعلــم عنــه شــيئا ألننــا ســلمنا‬\n      ‫العقــار للمدعــي أصالــة مــن تاريــخ ‪1433/9/1‬ه ـ وأمــا وضــع البــاب يف‬\n      ‫الــدور العلــوي وهــدم جــدار يف الصالــون األرضــي فهــذا نحــن ملزمــون‬\n      ‫بإصالحــه وأمــا الهــاك يف البويــة والكهربــاء فهــو إهــاك عــادي وليس‬\n      ‫فيــه تخريــب مقصــود هكــذا قــرر فســألت املدعــي وكالــة هــل اســتلم‬\n      ‫موكلــك العقــار يف ‪1433/9/1‬ه ـ فقــال ان موكلــي لــم يســتلم العقــار‬\n      ‫بتاريــخ ‪1433/9/1‬ه ـ ورفضنــا اســتالم العقــار لوجــود تلفيــات فيــه علمــا‬\n      ‫بأنــه لــم يبلغنــا برغبتــه يف اإلخــاء وفســخ العقد إال قبــل رمضان بحوالي‬\n      ‫عشــرين يومــا أو خمســة عشــر يومــا وملــا رفضنــا االســتالم بقــي العقــار‬\n      ‫يف حوزتهــم ثــم إنهــم بتاريــخ ‪1433/12/6‬ه ـ أرســلوا لنــا رســالة بواســطة‬\n      ‫شــركة ‪ .....‬مرفقــا بهــا مفاتيــح وتبــن أن هــذه املفاتيــح هــي ليســت‬\n      ‫لألبــواب اخلارجيــة وإمنــا ألبــواب داخليــة هكــذا قــرر وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه وكالــة فقــال إن موكلــي أبلــغ املدعــي أصالــة بتاريــخ‬\n      ‫‪1433/7/28‬ه ـ بخطــاب ســلم لــه شــخصيا ورفــض اســتالم العقــار طيلــة‬\n      ‫هــذه املــدة حتــى أواخــر شــعبان حضــر املدعــي وكالــة ودخــل البيــت‬\n      ‫وطلبنــا منــه اســتالم املفاتيــح فرفــض بســبب وجــود مالحظــات لديــه‬\n      ‫علــى العقــار ثــم أرســل لنــا فاكــس يرفــض فســخ العقــد وأن العقــار ال‬\n      ‫زال بيــد موكلــي فحاولنــا الوصــول إلــى حــل ودي مــع املدعــي أصالــة‬\n      ‫فذكــر أن ســبب رفضــه الســتالم البيــت فقــال إنــه يوجــد بالعقــار‬\n      ‫تخريــب واتالفــات وأن علينــا إصالحــه فقــال لــه إننــا مســؤولني عــن أي‬\n      ‫تخريــب وإتــاف وأمــا اإلهــاك الطبيعــي فهــذا ال نتحملــه فرفــض‬\n      ‫وطلــب منــا إصــاح العقــار بخمســة وســتني ألــف ريــال فرفضنــا ذلــك‬\n\n\n‫‪161‬‬\n\f‫وتقــدم بهــذه الدعــوى ثــم أرســلنا لــه مفاتيــح العقــار برســالة عبــر شــركة‬\n‫فيدكــس وهــي النســخة الوحيــدة التــي توجــد لدينــا وال أعلــم هــل مفتــاح‬\n‫خارجــي أم داخلــي علمــا بأننــا اســتلمنا نســخة واحــدة مــن جميــع األبــواب‬\n‫الداخليــة واخلارجيــة وليــس لدينــا ســوى هــذا املفتــاح الــذي بعثنــاه‬\n‫للمدعــي أصالــة وال نعلــم هــل هــو للبــاب اخلارجــي أم لألبــواب الداخليــة‬\n‫هكــذا قــرر وحيــث األمــر مــا ذكــر فقــد جــرى بعــث املعاملــة إلــى هيئــة‬\n‫النظــر باخلطــاب رقــم ‪ 332150769‬يف ‪1434/1/10‬ه ـ للوقــوف علــى‬\n‫العقــار ومعاينتــه واإلفــادة عــن التلفيــات املوجــودة فيــه هــل هــي طبيعيــة‬\n‫أم ســبب تفريــط وتعــدي مــن املســتأجر واإلفــادة عــن أدوات احلمــام‬\n‫املفقــودة وتقديرهــا وكذلــك تقديــر إصــاح اإلعمــال التــي قــام املدعــى‬\n‫عليــه ولــم يســتأذن املدعــي أصالــة مــن وضــع بــاب يف الــدور العلــوي وهدم‬\n‫جــدار يف الــدور األرضــي وكذلــك اإلفــادة عــن الفواصــل الصناعيــة‬\n‫املوجــودة يف الــدور األرضــي هــل وضعــت حســب أصــول الصنعــة أم ال‬\n‫إ‪.‬ه ـ فــوردت اإلجابــة مــن هيئــة النظــر باخلطــاب رقــم ‪332150769‬‬\n‫يف‪1434/5/12‬ه ـ وهــذا نصــه احلمــد هلل والصــاة والســام علــى نبينــا‬\n‫محمــد والــه وصحبــه بنــاء علــى املعاملــة الــواردة لنــا مــن فضيلــة الشــيخ‬\n‫‪ .........‬رقــم ‪ 332150769‬يف ‪1434/1/10‬ه ـ بشــأن دعــوى ‪ ...........‬ضــد‬\n‫‪ ...........‬بوكالتــه عــن ‪ ...........‬فطلــب فضيلتــه الوقــوف واإلفــادة ‪...‬الــخ‬\n‫عليــه فقــد جــرى الوقــوف وتبــن أن العقــار محــل الدعــوى كان محــل‬\n‫اهتمــام مالكــه والعنايــة بــه والــذي يــراه حيــال مــا طلــب فضيلتــه اآلتــي‪:‬‬\n‫أوال‪ /‬إزالــة الفواصــل الصناعيــة لعــدم توافقهــا ألصــول الصنعــة مــن‬\n‫جهــة عــدم مالئمتهــا ملــا هــي فيــه ‪ .‬ثانيــا‪ :‬إزالــة البــاب املوضــوع بالــدور‬\n‫العلــوي وبنــاء اجلــدار املهــدوم بالــدور األول وإعــادة تأهيلــه حســب أصــول‬\n\n\n                                                                                        ‫‪162‬‬\n\f      ‫الصنعــة وتقديــر ذلــك ألفــان وثالثمائــة ريــال ‪ .‬ثالثــا‪ /‬تركيــب درفــة‬\n      ‫أملنيــوم ويقــدر ذلــك بخمســمائة ريــال رابعــا‪ /‬تركيــب األدوات التالفــة‬\n      ‫وتقديــر ذلــك ثالثــة آالف وأربعمائــة ريــال خامســا‪ /‬تســليم مفاتيــح‬\n      ‫األبــواب أو تغيــر القلــوب وتقديــر ذلــك مائتــان وخمســن ريــال سادســا‪/‬‬\n      ‫عمــل نظافــة للموقــع مــع تــروي مبواضــع التنديــة يف دورات امليــاه ويقــدر‬\n      ‫ذلــك بخمســمائة ريــال ســابعا ‪ /‬تعــذر اختبار عمــل املكيفات ومضخات‬\n      ‫امليــاه لعــدم وجــود كهربــاء باملوقــع هــذا مــا جــرى تقديــره ‪.‬إ‪.‬ه ـ ثــم جــرى‬\n      ‫إعادة املعاملة لهيئة النظر بشرحي رقم ‪ 332150769‬يف‪1434/5/25‬هـ‬\n      ‫لإلفــادة عــن التلفيــات املوجــودة يف العقــار وهــل هــي طبيعيــة ام نتيجــة‬\n      ‫تعــدي او تفريــط مــن املســتأجر وحصرهــا مفصــا وكذلــك حصــر‬\n      ‫أدوات احلمــام املفقــودة مفصــا وتقديرهــا إ‪.‬ه ـ فعــادت املعاملــة مــن هيئــة‬\n      ‫النظــر باخلطــاب رقــم ‪ 332150769‬يف‪1434/6/21‬ه ـ وهــذا نصــه‬\n      ‫احلمــد هلل والصــاة والســام علــى نبينــا محمــد والــه وصحبــه بنــاء علــى‬\n      ‫املعاملــة الــواردة لنــا مــن فضيلــة الشــيخ ‪ ...................‬رقــم ‪332150769‬‬\n      ‫يف ‪1434/1/10‬ه ـ بشــأن دعــوى ‪ ....................‬ضــد ‪ ............‬وكالــة‬\n      ‫فطلــب فضيلتــه اإلفــادة عــن التلفيــات هــل هــي طبيعيــة ام نتيجــة تعــدي‬\n      ‫او تفريــط مــن املســتأجر وكذلــك حصــر أدوات احلمــام املفقــودة‬\n      ‫وتقديرهــا عليــه نفيــد بــأن التلفيــات تتمثــل يف ‪ /1‬تركيــب بــاب بالــدور‬\n      ‫العلــوي ‪ /2‬فتــح جــدار بالــدور األرضــي وتركيــب بــاب مكانــه ‪ /3‬عــدم‬\n      ‫وجــود درفــة بــاب املنيــوم ‪ /4‬عــدم وجــود مفاتيــح األبــواب ‪ /5‬تنديــة يف‬\n      ‫دورات امليــاه فــاألول والثانــي نتيجــة احلاجــة إليــه مــن قبــل املســتأجر‬\n      ‫والثالــث والرابــع تعــدي وتفريــط واخلامــس نتيجــة إهمــال الصيانــة‬\n      ‫والتقديــر كمــا جــاء بقرارنــا الســابق أمــا أدوات احلمام املفقــودة والتالفة‬\n\n\n‫‪163‬‬\n\f‫فهــي ‪ /1‬مغاســل عــدد ثالثــة ‪ /2‬خــاط مغســلة عــدد ثالثــة ‪ /3‬شــفاط‬\n‫ولــي عــدد ثالثــة ‪ /4‬كرســي عــدد اثنــان ‪ /5‬بانيــو مــع خــاط عــدد‬\n‫واحــد فــاألول عــدد (‪ )2‬تالــف وواحــد مفقــودة والثانــي والثالــث والرابــع‬\n‫تالــف واخلامــس مفقــود فــاألدوات التالفــة نتيجــة التفريــط واملفقــودات‬\n‫ســببها ظاهــر وتقديرهــا مفصــا ‪ /1‬ســعر الوحــدة ‪350‬ريــال ‪ /2‬ســعر‬\n‫الوحــدة ‪ 90‬ريــال ‪ /3‬ســعر الوحــدة ‪25‬ريــال ‪ /4‬ســعر الوحــدة ‪ 600‬ريــال‬\n‫‪ /5‬ســعر الوحــدة ‪ 800‬ريــال هــذا مــا جــرى تقديــره إ‪.‬ه ـ بعــرض قــراري‬\n‫هيئــة النظــر علــى الطرفــن قــاال نطلــب إمهالنــا ملراجعــة موكلينــا ‪ .‬ويف‬\n‫جلســة أخــرى حضــر الطرفــان وكالــة وقــرر املدعــى عليــه وكالــة قائــا‬\n‫ان لــدى موكلــي رد علــى مــا جــاء يف قــرار هيئــة النظــر وأبــرز ورقــة هــذا‬\n‫نصهــا (نتقــدم بالــرد علــي طلبــات املدعــي وكذلــك التعقيــب علــي‬\n‫التقريــر الــوارد مــن هيئــة النظــر ونلخــص الــرد فيمــا يلــي ‪:‬أوال ‪ :‬الــرد‬\n‫علــي ادعــاءات املدعــي للمطالبــة بأجــرة عــن الفتــرة املتبقيــة بعقــد‬\n‫االيجــار‪ :‬العقــد شــريعة املتعاقديــن واملســلمون علــى شــروطهم فعقــد‬\n‫االيجــار اعطــى للمدعــي عليهــا موكلتــي حــق فســخ العقــد قبــل انتهــاء‬\n‫مدتــه شــريطة ان يتــم ســداد االيجــار للســنة االيجاريــة التــي ينفســخ فيهــا‬\n‫ا راجــع العقــد مســتند رقــم ‪ ) 1‬بحســب البنــد خامســا مــن‬        ‫العقــد (فضـ ً‬\n‫العقــد ونصــه ‪ ((:‬يف حــال رغبــة الطــرف الثانــي بإخــاء املــكان املؤجــر‬\n‫عليــه ابــاغ الطــرف االول قبــل انتهــاء مــدة العقــد بشــهر علــى االقــل ويف‬\n‫حــال رغــب يف اخــاء العقــار قبــل نهايــة املــدة يلتــزم بســداد كامــل‬\n‫االيجــار للســنة التــي يرغــب االخــاء خاللهــا)) ‪ .‬وبالفعــل فقــد ســددت‬\n‫املدعــي عليهــا االجــرة كاملــة للســنة التــي مت الفســخ خاللهــا وهــو مــا‬\n‫أقــر بــه املدعــي يف الئحــة دعــواه (فضــا راجــع الئحــة الدعــوي ‪ -‬مســتند‬\n\n\n                                                                                       ‫‪164‬‬\n\f      ‫رقــم (‪ ))2‬حيــث اقــر بســدادنا االجــرة لــه واســتالمه اياهــا ‪ ،‬وكذلــك‬\n      ‫هنــاك اقــرار صريــح مــن املدعــي بأنــه تلقــي إخطــار مــن املدعــي عليهــا‬\n      ‫لــه بفســخ العقــد حيــث ان العقــد بالبنــد اخلامــس اعطــي للمدعــي عليهــا‬\n      ‫حــق الفســخ شــريطة االخطــار املســبق قبــل نهايــة الســنة االيجاريــة مبــدة‬\n      ‫شــهر وهــو مــا أقــر بــه املدعــي يف الئحــة دعــواه يف انــه تســلم االخطــار يف‬\n      ‫تاريــخ ‪ 1433-7-28‬هــ‪ .‬مــن هنــا يتضحــان املدعــي عليهــا مــن حقهــا‬\n      ‫فســخ العقــد وانهــاؤه قبــل حلــول أجــل العقــد ويتضــح ايض ـ ًا أن املدعــي‬\n      ‫عليهــا قــد أوفــت بكامــل التزامهــا مــع املدعــي وســددت لــه كامــل‬\n      ‫الســنة التعاقديــة وبالتالــي فليــس للمدعــي وجــه حــق فيمــا يطالــب بــه مــن‬\n      ‫ســداد اجــرة عــن ســنة ايجاريــة جديــدة أو ســداد االجــرة لســنوات العقــد‬\n      ‫املتبقيــة الن العقــد شــريعة املتعاقديــن واملســلمون علــى شــروطهم ‪ .‬فيمــا‬\n      ‫يتعلــق بطلــب املدعــي اصــاح العــن املؤجــرة ‪ :‬العقــار موضــوع الدعــوي‬\n      ‫هــو يف احلقيقــة منــزل مكــون مــن طابقــن وغــرف ملحقــة للحــارس‬\n      ‫وتاريــخ بنــاؤه يعــود الــي أكثــر مــن خمــس وعشــرون ســنة ومــا يتحــدث‬\n      ‫عنــه املدعــي ويطالــب بــه هــو اعــادة طــاء اجلــدران وتغييــر ليــات‬\n      ‫الشــطافات والقاعــدة البالســتيكية لكراســي احلمامــات وتغييــر‬\n      ‫الكوالــن واألقفــال أو ترويــب أرضيــة احلمامــات باإلســمنت األبيــض‬\n      ‫هيفــي احلقيقــة طلبــات جــري العــرف علــي انهــا اســتهالك وأمــور تقــادم‬\n      ‫طبيعــة ألي مــكان مؤجــر ومــن الطبيعــي أنــه عنــد انتهــاء العقــد يقــوم‬\n      ‫املالــك بعمــل الصيانــة للعقــار إلعــادة تأجيــره ومــا يطالــب بــه املدعــي هــو‬\n      ‫أمــر غيــر مألــوف ولــم يجــري عليــه العــرف ‪.‬فالبنــاء كمــا هــو ولــم نقــوم‬\n      ‫بتغييــر معالــم العقــار أو هــدم املــكان أو إزالــة اعمــدة او االنتقــاص مــن‬\n      ‫املبنــى شــيء اللهــم ان اســتخدامنا للمــكان يأتــي يف طــور االســتخدام‬\n\n\n‫‪165‬‬\n\f‫الطبيعــي ألي مــكان مؤجــر عــود ًا علــي بــدء فإننــا نشــير اخيــر ًا لعقــد‬\n‫االيجــار يف أننــا أوضحنــا بالبنــد الثالــث عبــارة (مــع مراعــاة االهــاك‬\n‫الطبيعــي للـ ــعقار) ‪ .‬ثانيــا ‪ :‬التعقيــب علــى تقريــر هيئــة النظــر ‪ :‬جــاء‬\n‫تقريــر هيئــة النظــر مجحفــا بحــق املدعــي عليهــا فاملبنــى جتــاوز عمــره‬\n‫‪ 30‬أو‪ 40‬ســنة وكانــت املدعــى عليهــا تســدد أجــرة ‪ 100000‬ريــال ثــم‬\n‫تقــرر الهيئــة حتميلنــا‪ 6950‬ريــال قيمــة صيانــة هــو امــر ًا نــراه مجحف ـ ًا‬\n‫رغــم ضآلــة املبلــغ ونخــص اعتراضنــا عليمــا ورد بالتقريــر يف النقــاط‬\n                                                                          ‫التالية‪:‬‬\n‫‪ .1‬عــدم وجــود ‪ 2‬كرســي حمــام وقيمتــه ‪600‬ريــال ‪ :‬يف احلقيقــة لــم‬\n‫تكــن تلــك الكراســي موجــودة مــن االســاس عنــد اســتالم الفيــا فمــا‬\n‫تتحــدث عنــه هيئــة النظــر هــي كرســي احلمــام الشــطاف وهــو مــا يطلــق‬\n‫عليــه (بيديــه) وهــو غيــر موجــود مبكانــه مــن االصــل ورمبــا نزعــه‬\n‫مــن مكانــه املســتأجر الســابق أو مالــك العقــار املدعــي كــون هــذا‬\n‫الكرســي غيــر مســتخدم وليــس لــه اســتخدام خاصــة عندنــا كشــعوب‬\n‫عربيــة واحلقيقــة ان الــزام املدعــي عليهــا بقيمتــه هــو نــوع مــن االجحــاف‪.‬‬\n‫‪ .2‬الــزام الهيئــة للمدعــي عليهــا بتركيــب ‪ 3‬ليــات شــطاف وقيمتهــا‪90‬‬\n‫ريــال ‪ :‬فهــو أمــر خــارج عــن العــرف والعــادة حيــث ان تلــك االدوات‬\n‫مســتهلكة بطبيعتهــا مــع االســتخدام وجــرى العــرف علــي تغييرهــا مــن‬\n‫آن آلخــر خاصــة ان اللــي مــن البالســتيك ومســألة اســتخدامه مــع مــرور‬\n                                     ‫الزمــان تــؤدي لتهالكــه هــو امــر طبيعــي‪.‬‬\n‫‪ .3‬مــا يتعلــق باملغاســل وعددهــا ‪ 3‬وعــدد ‪ 3‬خالطــات وقيمتهــا ‪1320‬‬\n‫ريــال ‪ :‬فنوضــح أن أماكــن تلــك املغاســل موجــودة ولكنهــا لــم تكــن‬\n‫مركبــة عــن االســتالم كــون اماكــن تواجدهــا بالصالــة أمــام املطبــخ‬\n\n\n                                                                                     ‫‪166‬‬\n\f      ‫وقــت كان املالــك (املدعــي) يؤجــر العقــار إلســكان احلجــاج ونوضــح‬\n      ‫أن املغاســل اخلالطــات لــم تكــن موجــودة مــن االســاس فكيــف لنــا ان‬\n      ‫نتحمــل قيمــة غيــر موجــود ‪ -1‬مــا يتعلــق بتنديــة احلمــام وترويــب ارضيــة‬\n      ‫احلمــام الصغيــر باجلبــس االبيــض وعمــل نظافــة للموقــع والــذي قدرتــه‬\n      ‫الهيئــة بــ‪ ...........‬ريــال ‪:‬هــو يف احلقيقــة أمــر خــارج العــرف فترويب البالط‬\n      ‫للحمامــات امــرا ال دخــل للمســتأجر فيــه أو بخــروج االســمنت األبيــض‬\n      ‫مــن مكانــه بالبــاط موضــوع حتميــل هيئــة النظــر املســؤولية للمدعــي‬\n      ‫عليهــا بقيمــة اصالحــات ال تتجــاوز ‪ 3400‬ريــال ‪ :‬هــو أمــر فيــه اجحــاف‬\n      ‫للمدعــي عليهــا كــون تلــك األدوات لــم تكــن موجــودة يف األســاس أو‬\n      ‫خلروجهــا عــن العــرف واملألــوف فضــا عــن ذلــك فــإن هيئــة النظــر لــم‬\n      ‫تقــم باإلشــارة الــى تاريــخ البنــاء او عمــر املبنــي والــذي جتــاوز‪ 30‬الــي ‪40‬‬\n      ‫ســنة منــذ تاريــخ بنــاؤه أخيــر ًا فإننــا نتقــدم لفضيلتكــم بردنــا حــول مــا‬\n      ‫أثــاره املدعــي يف دعــواه ونعقــب علــي تقريــر هيئــة النظــر ونطلــب ‪/1 :‬‬\n      ‫رد الدعــوي لعــدم قيامهــا علــي ســند مــن الشــرع أو النظــام او العــرف أو‬\n      ‫الواقــع فهــي ال تعــد وكونهــا محاولــة للتربــح واالثــراء بــا ســبب علــى‬\n      ‫حســاب املدعــي عليهــا فالعقــار حتــت يــده وبحوزتــه ولــه ان يتصــرف فيــه‬\n      ‫كيفمــا يشــاء شــركة محــات عبدالصمــد القرشــي عنهــا وكالــة‬\n      ‫محمــد ابراهيــم شــاولي) إ‪.‬ه وبعــرض ذلــك علــى املدعــى وكالــة قــال إن‬\n      ‫موكلــي يطالــب مبــا قدرتــه هيئــة النظــر علمــا بــأن هيئــة النظــر قــدرت‬\n      ‫أن التالــف هــو ســبب تفريــط املدعــى عليــه ولــذا فيلزمــه دفــع مــا قدرتــه‬\n      ‫هيئــة النظــر كمــا أن موكلــي يطالبــه بإلــزام املدعــى عليــه بدفــع‬\n      ‫االجــرة التــي بــدأت يف ‪1433/9/1‬ه ـ وســداد فواتيــر الكهربــاء واملــاء‬\n      ‫حتــى نهايــة هــذا الشــهر هكــذا قــرر ‪ ،‬فجــرى ســؤال املدعــى عليــه‬\n\n\n‫‪167‬‬\n\f‫وكالــة هــل اســتأذن موكلــه فيعمــل التعديــات فيمــا عــدا الفواصــل‬\n‫فقــال إن موكلــي لــم يســتأذن فيمــا عمــل يف العقــار ماعــدا الفواصــل‬\n‫وبعــرض ذلــك علــى املدعــي وكالــة قــال صحيــح انــه لــم يســتأذن إال يف‬\n‫عمــل الفواصــل ومــع ذلــك فإنــه لــم يعملهــا وفــق أصــول الصنعــة هكــذا‬\n‫قــرر فبنــاء علــى مــا تقــدم مــن املدعــى واإلجابــة وبعــد االطــاع علــى‬\n‫العقــد بــن الطرفــن والن الفقــرة الثالثــة مــن العقــد نصــت علــى ال يحــق‬\n‫للطــرف الثانــي إضافــة أو تغييــر معالــم العــن املؤجــرة مــن دهانــات أو‬\n‫أعمــال ديكــور إال بعــد موافقــة الطــرف األول ‪ ،‬كمــا يتحمــل الطــرف‬\n‫الثانــي جميــع أعمــال الصيانــة مــع مراعــاة احتســاب اإلهــاك الطبيعــي‬\n‫للمبنــى و محتوياتــه عنــد نهايــة العقــد ‪ ،‬وقــد وافــق الطــرف األول علــى‬\n‫الســماح للطرف الثاني بعمل فواصل جيبســون بورد أو خشــبيه لتقســيم‬\n‫املســاحات الكبيــرة بالفــا حتــى ميكــن اســتخدامها و علــى حســاب‬\n‫الطــرف الثانــي ‪ .‬كمــا أن الفقــرة اخلامســة مــن العقــد نصــت علــى يف‬\n‫حالــة رغبــة الطــرف الثانــي بإخــاء املــكان املؤجــر عليــه إبــاغ الطــرف‬\n‫األول قبــل انتهــاء مــدة العقــد بشــهر علــى األقــل ‪ ،‬و يف حــال رغــب يف‬\n‫إخــاء العقــار قبــل نهايــة املــدة يلتــزم الطــرف الثانــي بســداد كامــل‬\n‫اإليجــار للســنه اإليجاريــة التــي يرغــب اإلخــاء خاللهــا ‪ .‬وألن املدعــى‬\n‫عليــه قــام بأعمــال يف العــن املســتأجرة بــدون إذن املدعــي أصالــة كمــا‬\n‫أن األعمــال التــي اســتأذن فيهــا لــم يقــم بعملهــا وفــق أصــول الصنعــة‬\n‫كمــا أنــه حينمــا رغــب إنهــاء العقــد لــم يقــم بإصــاح مــا تلفــه او قــام‬\n‫بتغيــره او مــا فقــد منــه قبــل الوقــت احملــدد وهــو ‪1433/9/1‬ه ـ وألن‬\n‫املدعــي أصالــة حينمــا امتنــع مــن اســتالم العــن حتــى يتــم اصالحــه أو‬\n‫دفــع تكلفــة اإلصــاح فــإن تصرفــه صحيحــا ألن ذلــك يحتــاج الــى وقــت‬\n\n\n                                                                                    ‫‪168‬‬\n\f      ‫وثمــن وهــو نتيجــة تعــدي او تفريــط مــن املســتأجر واملســتأجر اذا فــرط‬\n      ‫أو تعــدى يف العــن املســتأجرة ضمــن ينظــر كشــاف القنــاع ‪139/9‬‬\n      ‫وألن ممــا قررتــه هيئــة النظــر هــو عمــل نظافــة للموقــع وترويــب مواضــع‬\n      ‫التنديــة يف دورات امليــاه مببلــغ خمســمائة ريــال وألن هــذا مــن عمــارة‬\n      ‫العــن املؤجــرة وليــس الزمــا للمســتأجر ينظــر كشــاف القنــاع ‪. 109/9‬‬\n      ‫لذلــك كلــه فقــد حكمــت علــى املدعــى عليــه أصالــة بأن يدفــع للمدعي‬\n      ‫أوال‪ /‬تكلفــة اإلصالحــات و املفقــودات يف املبنــى التــي قدرتهــا هيئــة‬\n      ‫النظــر فيمــا عــدا تنظيــف املوقــع وترويــب مواقــع التنديــة يف دورات امليــاه‬\n      ‫مبلــغ وقــدره ســتة آالف وأربعمائــة وخمســة وأربعــون ريــال ‪ .‬ثانيــا ‪ /‬أجــرة‬\n      ‫املــدة التــي بــدأت يف ‪1433/9/1‬ه ـ مبلــغ وقــدره مائــة وســتة آالف ريــال‬\n      ‫وأربعمائــة وثمانــن ريــاال ‪ .‬ثالثــا ‪ /‬دفــع اســتهالك املــاء والكهربــاء حتــى‬\n      ‫‪1434/8/30‬ه ـ وأن علــى املدعــى عليــه أصالــة اخــاء املبنــى يف مــدة‬\n      ‫اقصاهــا ‪1434/9/1‬ه ـ وتســليمه للمدعــي أصالــة خاليــا مــن الشــواغل‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــي وكالــة القناعــة وقــرر‬\n      ‫املدعــى عليــه وكالــة عــدم القناعــة وطلــب رفعــه حملكمــة االســتئناف‬\n      ‫بعــد تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه مبراجعــة احملكمــة خــال‬\n      ‫عشــرة أيــام الســتالم صــورة الصــك وتقــدمي الالئحــة االعتراضيــة‬\n      ‫خــال ثالثــن يومــا مــدة االعتــراض فــإذا تأخــر ســقط حقــه يف طلــب‬\n      ‫االســتئناف واكتســب احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد مت عــادت املعاملــة من محكمة االســتئناف بشــرح‬\n      ‫فضيلــة الرئيــس برقــم ‪ 33/2150769‬يف ‪1434/11/18‬ه ـ علــى خطاب‬\n      ‫فضيلــة رئيــس محكمــة االســتئناف مبنطقــة مكــة املكرمــة املكلــف‬\n\n\n‫‪169‬‬\n\f‫برقــم ‪ 3321450769‬يف ‪1434/11/11‬ه ـ برفقهــا قــرار التصديــق‬\n‫مبوجــب القــرار رقــم ‪34349104‬يف ‪1434/11/4‬ه ـ وهــذا نصــه ‪-:‬‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ‪ ...........‬القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل‬\n‫بعــدد ‪ 34302116‬وتاريــخ ‪1434/8/22‬ه ـ املتضمــن دعــوى ‪...........‬‬\n‫ضــد شــركة‪ ...........‬واحملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكم ‪ .‬وصلى اهلل على نبينا محمد وعلى آله وصحبه وســلم‪ ،‬قاضي‬\n‫اســتئناف‪ ...........‬ختــم وتوقيــع قاضــي اســتئناف‪ ...........‬ختــم وتوقيــع‪،‬‬\n‫قاضــي اســتئناف‪ ...........‬ختــم وتوقيع‪،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/20‬ه ـ‬\n‫احلمــد هلل‪،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ‪ ...........‬القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل‬\n‫بعدد ‪ 34302116‬وتاريخ ‪1434/8/22‬ه ـ املتضمن دعوى ‪.....................‬‬\n‫ضــد شــركة ‪ .....................‬واحملكــوم فيــه مبــا دون باطنــه وبدراســة‬\n‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقة‬\n‫علــى احلكــم‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪170‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":147,"source_page_end":170,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2cade3311345afea8a0392708678903d5d5b1a1a1bcfa0a05df31037f4833d41","normalized_text_hash":"f5f5209bae2ab1ba19a20327002d840f91ff726b5bf1c5fa5345587ce518a06e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p147-34302116"},{"id":"7c239a48-5704-56cf-bfa4-f4be4409fbef","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -طلب إخاء عقار وقف -إجارة وقف مدة طويلة - ضرر متيقن الوقوع على عقار الوقف -إجازة فسخ ناظر الوقف لعقد األجرة -حكم بإخاء عقار.","document_number":"3435968","case_number":"33689238","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/22","year":"1434","subject":"عقد -إجارة -طلب إخاء عقار وقف -إجارة وقف مدة طويلة - ضرر متيقن الوقوع على عقار الوقف -إجازة فسخ ناظر الوقف لعقد األجرة -حكم بإخاء عقار.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/22 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3435968 :‬‬\n                         ‫َر ْق ُم الدعوى‪33689238 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34176955‬تاريخه‪1434/4/2 :‬هـ‬\n\n\n      ‫عقــد ‪ -‬إجــارة ‪ -‬طلــب إخــاء عقــار وقــف ‪ -‬إجــارة وقــف مــدة طويلــة ‪-‬‬\n      ‫ضــرر متيقــن الوقــوع علــى عقــار الوقــف ‪ -‬إجــازة فســخ ناظــر الوقــف‬\n                                          ‫لعقــد األجــرة ‪ -‬حكــم بإخــاء عقــار‪.‬‬\n\n\n\n\n                   ‫‪ .1‬قوله صلى اهلل عليه وسلم (( املسلمون على شروطهم ))‬\n                                             ‫‪ .2‬الضرر مرفوع يف الشريعة‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ناظــر وقــف ضــد املدعــى عليــه ومضمــون الدعــوى أن‬\n      ‫والــد املدعــي كان ناظــر وقفــه وقــد أجــره علــى املدعــى عليــه مــدة‬\n      ‫ثالثــن ســنة مــن ‪1422/1/1‬ه ـ بأجــرة ســنوية قدرهــا ألفــان وســتمائة‬\n      ‫ريــال وقــد ســلم املدعــى عليــه أجــرة الســنة األولــى والثانيــة وانقطــع عــن‬\n      ‫تســليم األجــرة لباقــي الســنوات وقــد تــويف والــده وان املدعــي هــو الناظــر‬\n      ‫وقــرر املدعــي أن العقــد املبــرم بــن والــده واملدعــى عليــه ينــص علــى أن‬\n      ‫العقــد ينفســخ عنــد عــدم ســداد األجــرة وطلــب املدعــي إلــزام املدعــى‬\n      ‫عليــه بإخــاء العقــار‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى‬\n      ‫ا ســوى تخلفــه عــن ســداد أجــرة الســنة الثالثــة فقــد ذكــر‬ ‫جملــة وتفصيـ ً‬\n      ‫انــه ســدد أجــرة الســنة الثالثــة ثــم تخلــف عــن الســداد الن والــد املدعــي‬\n\n‫‪171‬‬\n\f‫قــد تــويف وبســبب انشــغال ورثتــه وقــرر انــه غيــر مســتعد بإخــاء العقــار‬\n‫وانــه مســتعد بدفــع أجــرة الســنوات املاضيــة والقادمــة كمــا قــرر انــه‬\n‫تخلــف عــن ســداد األجــرة منــذ عــام ‪1427‬ه ـ وان املدعــي احلاضــر طالبــه‬\n‫يف عــام ‪1430‬ه ـ باألجــرة وانــه لــم يســتطع الســداد لظــروف مــرت بــه‪،‬‬\n‫عــرض ناظــر القضيــة الصلــح بــن الطرفــن وقــد تعــذر ذلــك‪ ،‬مت اطــاع‬\n‫ناظــر القضيــة علــى صــك امللكيــة وعقــد اإلجــارة‪ ،‬قــرر املدعــي نظــارة‬\n‫أن املدعــى عليــه تأخــر يف دفــع اإليجــار وانــه فســخ العقــد‪ ،‬قــرر ناظــر‬\n‫ـاء علــى مــا ســبق وملصادقــة املدعــى عليــه علــى تأخــره‬ ‫القضيــة انــه بنـ ً‬\n‫عــن دفــع األجــرة بســبب ظروفــه ولكــون املــدة ليســت بالقصيــرة فهــي‬\n‫تقــارب ســبع ســنوات ولكــون شــرط فســخ العقــد عنــد منــع األجــرة‬\n‫ثابــت بإقــرار املدعــى عليــه والن املســلمني علــى شــروطهم والضــرر‬\n‫مرفــوع يف الشــريعة وبقــاء املدعــى عليــه يف العقــار دون دفــع األجــرة‬\n‫ضــرر متيقــن الوقــوع علــى عقــار الوقــف لذلــك كلــه فقــد أجــاز ناظــر‬\n‫القضيــة فســخ املدعــي لعقــد األجــرة وإلــزام املدعــى عليــه بإخــاء العقــار‬\n‫محــل الدعــوى‪ ،‬صــدر قــرار محكمــة االســتئناف بالقصيــم باملوافقــة‬\n                                                                   ‫علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 33689238‬وتاريــخ ‪ 1433/12/19‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332182629‬وتاريــخ ‪ 1433/12/19‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/01/10‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 30‬‬\n\n                                                                                     ‫‪172‬‬\n\f      ‫وفيهــا حضــر ‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫بصفتــه ناظــر ًا علــى وقــف والــده ‪........‬مبوجــب الصــك الصــادر مــن‬\n      ‫هــذه احملكمــة برقــم ‪ 4/59‬يف ‪1428/5/27‬ه ـ وادعــى علــى احلاضــر‬\n      ‫معه‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬قائــا يف‬\n      ‫دعــواه عليــه إن والــدي ‪........‬كان قــد أوقــف األرض الواقعــة يف حــي‬\n      ‫‪ ........‬اململوكــة لــه مبوجــب الصــك الصــادر مــن محكمــة عنيــزة برقــم‬\n      ‫‪ 1/102‬وتاريــخ ‪1489/4/1‬ه ـ علــى أن تكــون النظــارة لــه مدة حياته ثم‬\n      ‫الصالــح مــن ذريتــه مــن بعــده وقــد أقمــت ناظــر ًا عليــه بعــد وفاتــه وذلــك‬\n      ‫مبوجــب صــك النظــارة الصــادرة مــن محكمــة عنيــزة برقــم ‪ 4/59‬يف‬\n      ‫‪1428/5/27‬ه ـ وقــد أجــر والــدي األرض حــال حياتــه للمدعــى عليــه‬\n      ‫ملــدة ثالثــن ســنة تبــدأ مــن تاريــخ ‪1422/1/1‬ه ـ بأجــرة ســنوية قدرهــا‬\n      ‫ألفــان وســتمائة ريــال دفــع املدعــى عليــه أجــرة الســنة األولــى والثانيــة‬\n      ‫ولــم يدفــع أجــرة الســنوات التاليــة وقــد نــص العقــد املبــرم بينهمــا علــى‬\n      ‫أن العقــد ينفســخ عنــد عــدم ســداد األجــرة أطلــب إلزامــه بإخــاء العقــار‬\n      ‫هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجاب قائــا ما ذكره‬\n      ‫املدعــي يف دعــواه مــن أننــي اســتأجرت مــن والــده العقــار املذكــور‬\n      ‫باملبلــغ واملــدة املذكــورة فصحيــح وأمــا قولــه إننــي لــم أدفــع ســوى أجــرة‬\n      ‫الســنة األولــى والثانيــة فغيــر صحيــح فقــد التزمــت بســداد األجــرة‬\n      ‫ثــاث ســنوات بعــد الســنتني األولــى والثانيــة ولــم أدفــع باقــي الســنوات‬\n      ‫لوفــاة والــد املدعــي والنشــغال ورثتــه وأمــا طلبــه إخــاء العقــار فأنــا‬\n      ‫غيــر مســتعد لذلــك ومســتعد بدفــع أجــرة الســنوات املاضيــة وااللتــزام‬\n      ‫بدفــع الســنوات القادمــة يف وقتهــا هكــذا أجــاب وبطلــب عقــد اإليجــار‬\n      ‫مــن املدعــي قــدم صــورة ورقــة هــذا نصهــا بســم اهلل الرحمــن الرحيــم‬\n\n\n‫‪173‬‬\n\f‫واحلمــد هلل وحــده حضــر عنــدي ‪........‬حامــل حفيظــة رقــم ‪........681‬‬\n‫مصــدر عنيــزة وتاريــخ ‪1385/5/23‬ه ـ وحضــر معــه ‪........‬حامــل حفيظــة‬\n‫رقــم ‪........‬مصــدر عنيــزة وتاريــخ ‪1396/11/10‬ه ـ وبعــد حضورهمــا‬\n‫أجــر ‪........‬بيتــه الواقــع ب‪ ........‬والــذي يحمــل صــك مــن احملكمــة‬\n‫برقــم ‪ 102‬وتاريــخ ‪1389/4/1‬ه ـ وذلــك علــى ‪........‬الســنة مببلــغ ألفــن‬\n‫وســتمائة ريــال ســعودي وملــدة ثالثــن ســنة ابتــداء مــن محــرم ‪1422‬ه ـ‬\n‫وقــد دفــع املســتأجر للمؤجــر حــق ســنتان مقــدم ويدفــع كل ســنة مقــدم‬\n‫مــن تاريخــه واالجــارة املذكــورة الصبــرة قادمــة بالبيــت ومــا يوضــع عليه‬\n‫مــن تعميــر ومنعهــا فســخ لهــا واشــترط ‪........‬أال يبيــع رغبــة اال مبوافقتــه‬\n‫هكــذا مت بينهمــا شــهد بذلــك ‪........‬حامــل حفيظــة رقــم ‪........‬مصــدر‬\n‫عنيــزة وتاريــخ ‪1402/2/9‬ه ـ وشــهد بــه كاتبــه ‪1424/1/23........‬ه ـ‬\n‫بصمــة املؤجــر ‪........‬بصمــه املســتأجر توقيعــه شــاهد وكاتــب ‪........‬‬\n‫توقيعــه وختمــه شــاهد توقيعــه انتهــى ويف جلســة أخــرى حضــر املدعــي‬\n‫الناظــر واملدعــى عليــه وقــد جــرى عــرض صــورة العقــد علــى املدعــى‬\n‫عليــه فقــال إن هــذا هــو العقــد الــذي تعاقــدت مبوجبــه مــع املوقــف والــد‬\n‫املدعــي وهــي صــورة طبــق األصــل هكــذا قــرر املدعى عليــه وقد اطلعت‬\n‫علــى صــك ملكيــة العقــار محــل الدعــوى فوجــدت أنــه صــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 1/102‬يف ‪1389/4/1‬ه ـ وهــذا هــو صحــة تاريخــه وقد‬\n‫حــرر التهميــش عليــه بالوقفيــة يف تاريــخ ‪1427/8/25‬ه ـ كمــا اطلعــت‬\n‫علــى صــك النظــارة فوجدتــه كمــا ذكــر املدعــي‪ ،‬وقــد ســألت املدعــى‬\n‫عليــه عــن الســنوات التــي تأخــر فيهــا عــن دفــع األجــرة فقــال كان‬\n‫والــد املدعــي مريضــا عــام ‪1427‬ه ـ ثــم تــويف يف عــام ‪1428‬ه ـ ولــم أســلم‬\n‫أجــرة العقــار منــذ كان مريضــا حتــى اآلن وقــد حضــر إلــي املدعــي‬\n\n\n                                                                                      ‫‪174‬‬\n\f      ‫عــام ‪1430‬ه ـ وطلــب منــي األجــرة وقــد كنــت أمــر بظــروف صعبــة ولــم‬\n      ‫أســتطع دفــع األجــرة لــه ولــم أدفــع شــيئا مــن األجــرة منــذ مــرض والــد‬\n      ‫املدعــي حتــى اآلن هكــذا قــرر املدعــى عليــه وقــد جــرت محاولــة الصلــح‬\n      ‫بــن الطرفــن فقــرر املدعــي بقولــه إن املدعــى عليــه تأخــر كثيــرا يف‬\n      ‫دفــع األجــرة وقــد فســخت العقــد وأطلــب إلــزام املدعــى عليــه بإخــاء‬\n      ‫العقــار هكــذا قــرر املدعــي فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n      ‫املتضمنــة طلبــه إخــاء املدعــى عليــه مــن العقــار الــذي اســتأجره مــن‬\n      ‫والــده والــذي أوقفــه والــده وأن ســبب الفســخ هــو تأخــر املدعــى عليــه عــن‬\n      ‫دفــع األجــرة وملصادقــة املدعــى عليــه علــى عقــد اإلجــارة والــذي ورد فيــه‬\n      ‫أن منــع األجــرة فســخ لهــا وملصادقــة املدعــى عليــه علــى تأخــره عــن دفــع‬\n      ‫األجــرة بســبب ظروفــه ولكــون املــدة التــي تأخــر فيهــا املدعــى عليــه عــن‬\n      ‫دفــع األجــرة ليســت بالقصيــرة فهــي تقــارب ســبع ســنوات حســب إقــرار‬\n      ‫املدعــى عليــه وقــد حصــل االمتنــاع عــن دفــع األجــرة بعــد مطالبــة املدعــي‬\n      ‫عــام ‪1430‬ه ـ بإقــرار املدعــى عليــه ولكــون شــرط فســخ العقــد عنــد‬\n      ‫منــع األجــرة ثابــت بإقــرار املدعــى عليــه وألن املســلمني علــى شــروطهم‬\n      ‫وألن الضــرر مرفــوع يف الشــريعة وبقــاء املدعــى عليــه يف العقــار دون‬\n      ‫دفــع األجــرة ضــرر متيقــن الوقــوع علــى عقــار الوقــف وملــا تقــدم كلــه‬\n      ‫فقــد أجــزت فســخ املدعــي لعقــد األجــرة املذكــور مــع املدعــى عليــه‬\n      ‫وألزمــت املدعــى عليــه بإخــاء العقــار محــل الدعــوى وبذلــك حكمــت‬\n      ‫وبعــرض احلكــم علــى الطرفــن قنــع املدعــي وقــرر املدعــى عليــه عــدم‬\n      ‫القناعــة وطلــب االســتئناف بالئحــة اعتراضيــة فجــرى تســليمه صــورة‬\n      ‫مــن الصــك هــذا اليــوم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا مــن‬\n      ‫تاريــخ اليــوم فــإن لــم يقــدم الالئحــة خاللهــا ســقط حقــه يف االســتئناف‬\n\n\n‫‪175‬‬\n\f‫واكتســب احلكــم القطعيــة وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                          ‫آلــه وصحبــه أجمعــن ‪ .‬حــرر يف ‪1434/2/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 33689238‬وتاريــخ ‪ 1433/12/19‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332182629‬وتاريــخ ‪ 1433/12/19‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/04/20‬ه ـ افتتحــت اجللســة وقــد عــادت إلينــا‬\n‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪34176955‬‬\n‫يف ‪1434/4/2‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة «وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة قررنــا التصديــق علــى احلكــم» وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                 ‫حــرر يف ‪ 1434/04/20‬ه ـ‬\n‫احلمــدهلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n‫الثانيــة مبحكمــة االســتئناف مبنطقــة القصيــم علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة عنيــزة برقــم‬\n‫(‪ )332182629‬وتاريــخ ‪1434/3/22‬هــ؛ اخلاصــة بدعــوى ‪........‬ضــد‬\n‫‪........‬؛ بشــأن املطالبــة بخــاء عقــار؛ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪........‬؛ املســجل برقــم (‪)3435968‬‬\n‫وتاريــخ ‪1434/2/12‬هــ؛ املتضمــن أن فضيلتــه أجــاز فســخ املدعــي لعقــد‬\n‫األجــرة املذكــور مــع املدعــى عليــه وألــزم املدعــى عليــه بإخــاء العقــار‬\n‫محــل الدعــوى وبذلــك حكــم؛ كمــا هــو مــدون ومفصــل فيــه وبدراســة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة؛ قررنــا التصديــق علــى احلكــم؛‬\n‫واهلل املوفــق؛ وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n                                                                                   ‫‪176‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":171,"source_page_end":176,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"94ef3cb5d4b1a6b094b91c400cb728dc3d3cb96e717e165951f4a6c8fc39e380","normalized_text_hash":"c43bf379d64354ecb1d715814656a7d1d18a30c66b5757aef7dea4d15261f6d6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p171-3435968"},{"id":"6f8991ff-6ee9-5a1b-8469-de30978f5549","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -إخاء عقار -إثبات اإلخطار باإلخاء عن طريق البريد املمتاز -العادة محكمة -الدليل إذا تطرق إليه االحتمال بطل به االستدالل -حكم بإخاء عقار.","document_number":"344846","case_number":"33700939","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالباحة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/26","year":"1434","subject":"عقد -إجارة -إخاء عقار -إثبات اإلخطار باإلخاء عن طريق البريد املمتاز -العادة محكمة -الدليل إذا تطرق إليه االحتمال بطل به االستدالل -حكم بإخاء عقار.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/2/26 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪344846 :‬‬\n                         ‫َر ْق ُم الدعوى‪33700939 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34217825‬تاريخه‪1434/5/20 :‬هـ‬\n\n\n      ‫عقــد ‪ -‬إجــارة ‪ -‬إخــاء عقــار ‪ -‬إثبــات اإلخطــار باإلخــاء عــن طريــق‬\n      ‫البريــد املمتــاز ‪ -‬العــادة محكمــة ‪ -‬الدليــل إذا تطــرق إليــه االحتمــال‬\n                                  ‫بطــل بــه االســتدالل ‪ -‬حكــم بإخــاء عقــار‪.‬‬\n\n\n\n\n                                       ‫‪ .1‬القاعدة الفقهية ( العادة محكمة )‬\n      ‫‪ .2‬القاعــدة الفقهيــة (الدليــل إذا تطــرق إليــه االحتمــال بطــل بــه‬\n                                                                 ‫اال ســتدالل)‬\n\n\n\n\n      ‫ا عبــارة عــن فتحتــن يف‬   ‫ادعــى املدعــي ضــد املدعــى عليــه انــه أجــره محـ ً‬\n      ‫عقــاره املوصــوف بالدعــوى ملــدة ســنة مــن تاريــخ ‪1425/7/17‬ه ـ مببلــغ‬\n      ‫ثمانيــة آالف ســنوي ًا ويتجــدد العقــد تلقائيـ ًا مــا لــم يخطــر احــد الطرفــن‬\n      ‫اآلخــر برغبتــه يف عــدم التجديــد قبــل نهايــة الســنة بخمســة عشــر يومـ ًا‬\n      ‫مبوجــب عقــد اإليجــار املرفــق صورتــه باملعاملــة وقــرر املدعــي انــه ابلــغ‬\n      ‫املدعــى عليــه باإلخــاء قبــل نهايــة العقــد بخمســة عشــر يومـ ًا عــن طريــق‬\n      ‫إرســال رســالة بالبريــد املمتــاز إال أن املدعــى عليــه لــم يقــم باإلخــاء‬\n      ‫وطلــب املدعــي إلــزام املدعــى عليــه بإخــاء العقــار‪ ،‬أجــاب املدعــى عليــه‬\n      ‫ا وصــادق علــى اســتالمه للبريــد‬    ‫باملصادقــة علــى الدعــوى جملــة وتفصيـ ً‬\n\n‫‪177‬‬\n\f‫املمتــاز وقــرر أن اإلرســالية تتضمــن زيــادة اإليجــار أو اإلخــاء وقــرر‬\n‫رفضــه للزيــادة كمــا قــرر انــه ســلم البــن املدعــي أجــرة الســتة أشــهر مــن‬\n‫الســنة اجلديــدة‪ ،‬حضــر ابــن املدعــي وأنكــر اســتالمه لألجــرة للســتة‬\n‫أشــهر اجلديــدة وقــرر أن هــذا املبلــغ هــو أجــرة حالــة للســنة املنتهيــة‬\n‫بتاريــخ ‪1433/7/13‬ه ـ بدليــل تســليمه لهــذا املبلــغ يف ‪1433/1/11‬هــ‪،‬‬\n‫ـاء علــى إقــرار املدعــى عليــه باســتالمه إلخطــار‬‫قــرر ناظــر القضيــة انــه بنـ ً‬\n‫طلــب اإلخــاء ومــا قدمــه املدعــى عليــه بشــأن تســليمه اإليجــار عــام‬\n‫‪1433‬ه ـ وانــه يعــد ذلــك جتديــد ًا للعقد محتمل أن يكون للســتة األشــهر‬\n‫األولــى لعــام ‪1433‬ه ـ كمــا أجــاب بــه ابــن املدعــي ويؤيــد ذلــك أن عــادة‬\n‫النــاس ومــا تعارفــوا عليــه بتســليم األجــرة بدايــة كل ســتة أشــهر وليــس‬\n‫مــن عادتهــم تســليم األجــرة للســنة املقبلــة قبــل ابتدائهــا والعــادة محكمة‬\n‫وإذا تطــرق االحتمــال بطــل االســتدالل كمــا أن اإلقــرار غيــر موقــع مــن‬\n‫املدعــي إمنــا مــن ابنــه ولذلــك فقــد صــدر احلكــم علــى املدعــى عليــه‬\n‫بإخــاء العقــار حــاال وافهــم املدعــي بــان لــه مطالبــة املدعــى عليــه فيمــا‬\n‫يخــص أجــرة الفتــرة مــن تاريــخ انتهــاء العقــد وحتــى تاريــخ اإلخــاء‪ ،‬مت‬\n ‫تصديــق احلكــم مــن محكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــد وبعــد فلــدي أنــا‬\n‫القاضــي يف احملكمــة العامــة بالباحــة وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بالباحــة برقــم ‪ 33700939‬وتاريــخ‬\n‫‪1433/12/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332228478‬وتاريــخ‬\n‫‪1433/12/25‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪ 1434/01/06‬ه ـ افتتحت‬\n\n                                                                                         ‫‪178‬‬\n\f      ‫اجللســة الســاعة التاســعة والنصــف وفيهــا حضــر ‪ ...........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...........‬وادعــى علــى احلاضــر‬\n      ‫معــه ‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪...........‬‬\n      ‫قائــا يف دعــواه عليــه أن مــن اجلــاري يف ملكــي وحتــت تصــريف األرض‬\n      ‫الواقعــة يف ‪........‬بالباحــة والواقعــة علــى شــارع ‪ ...‬والبالــغ قــدر مســاحتها‬\n      ‫اإلجماليــة أربعمائــة وثالثــون متــرا وخمســة وخمســون ســنتيمترا مربعــا‬\n      ‫واململوكــة لــي بالصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 286‬وتاريــخ‬\n      ‫‪1393/5/5‬ه ـ واملرفــق صورتــه باملعاملــة‪ ،‬وقــد أقمــت علــى األرض‬\n      ‫محــات جتاريــة دور واحــد وقــد قمــت بتأجيــر املدعــى عليــه احلاضــر‬\n      ‫محــل فتحتــن ملــدة ســنة اعتبــارا مــن بتاريــخ ‪1425/7/13‬ه ـ ومببلــغ‬\n      ‫ثمانيــة آالف ريــال لــكل ســنة‪ ،‬ويتجــدد العقــد تلقائيـ ًا مــا لــم يخطــر أي‬\n      ‫مــن الطرفــن اآلخــر برغبتــه يف عــدم جتديــده قبــل نهايــة الســنة بخمســة‬\n      ‫عشــر يومــا وذلــك مبوجــب عقــد اإليجــار املرفــق صورتــه باملعاملــة‪ ،‬وقــد‬\n      ‫اســتمر املســتأجر احلاضــر حتــى نهايــة العــام املنصــرم املنتهــي بتاريــخ‬\n      ‫‪1433/7/13‬ه ـ وقــد أخطرتــه برغبتــي بعــدم جتديــد العقــد للســنة التــي‬\n      ‫تبــدأ مــن تاريــخ ‪1433/7/13‬ه ـ وذلــك بإرســال رســالة إليــه بالبريــد‬\n      ‫املمتــاز يف شــهر ربيــع األول لعــام ‪1433‬ه ـ وطلبــت منــه إخــاء العقــار‬\n      ‫فــور انتهــاء الســنة املاضيــة إال أنــه لــم يخــل احملــل وال يــزال حتــى اآلن‬\n      ‫فيــه لــذا أطلــب احلكــم بإلــزام املدعــى عليــه بإخــاء احملــل حــاال هــذه‬\n      ‫دعــواي وبعــرض مــا جــاء يف دعــوى املدعــي علــى املدعــى عليــه أجــاب‬\n      ‫قائــا مــا ذكــره املدعــي مــن أننــي اســتأجرت احملــل املذكــور منــه ملــدة‬\n      ‫ســنة اعتبــارا مــن تاريــخ ‪1425/7/13‬ه ـ باملبلــغ املذكــور وأن العقــد‬\n      ‫يتجــدد تلقائيــا وأننــي مكثــت فيــه حتــى اآلن صحيــح ‪ ،‬ومــا ذكــره مــن‬\n\n\n‫‪179‬‬\n\f‫أنــه أخطرنــي بعــدم رغبتــه يف جتديــد العقــد لهــذه الســنة التــي تبــدأ مــن‬\n‫تاريــخ ‪1433/7/13‬ه ـ فغيــر صحيــح فلــم يصلنــي شــيء ‪ ،‬ولقــد ســلمت‬\n‫مبلــغ الســتة األشــهر األولــى لهــذه الســنة البنــه ‪ ...‬ومعــي إيصــال منــه‬\n‫بذلــك ولــذا فلســت مســتعدا بإخــاء العقــار قبــل انتهــاء العقــد بتاريــخ‬\n‫‪1434/7/13‬ه ـ هــذه إجابتــي وبســؤال املدعــي هــل لديــه بينــة علــى‬\n‫إخطــاره للمدعــى عليــه بعــدم رغبتــه يف جتديــد العقــد لهــذه الســنة أبــرز‬\n‫لنــا فاتــورة إرســال رســالة بالبريــد املمتــاز وباالطــاع عليهــا وجدتهــا‬\n‫تضمنــت اســم املرســل واســم املرســل إليــه ‪ ،‬ولــم يوضــح تاريــخ إرســالها‬\n‫وال صورة من األوراق املرســلة ‪ ،‬وبســؤال املدعي عنها أجاب بقوله إنني‬\n‫كبيــر يف الســن وال أعــرف القــراءة وقــد أمــرت ابنــي بإبــاغ املســتأجر‬\n‫بعــدم رغبتــي يف التجديــد فأخبرنــي أنــه بلغــه وأعطانــي هــذه الفاتــورة ‪،‬‬\n‫ومرفــق لكــم باملعاملــة صــورة مــن اإلخطــار هكــذا أجــاب وبالرجــوع‬\n‫إلــى أوراق املعاملــة وجــدت صــورة خلطــاب موقــع مــن موجــه مــؤرخ يف‬\n‫‪1433/3/29‬ه ـ متضمنــا إنــذاره باإلخــاء فــور انتهــاء مــدة العقــد‬\n‫املوافــق لتاريــخ ‪1433/7/1‬ه ـ انتهــى مضمونــه وبعرضــه علــى املدعــى‬\n‫عليــه أجــاب قائــا هــذه الورقــة املشــار إليهــا لــم أطلــع عليهــا إال اآلن ولــم‬\n‫يردنــي أي شــيء عــن طريــق البريــد هكــذا أجــاب فســألت املدعــي هــل‬\n‫لديــك مزيــد مــن البينــة فأجــاب قائــا أطلــب إمهالــي للجلســة القادمــة‬\n‫فأجيــب لطلبــه ورفعــت اجللســة إلــى يــوم الثالثــاء املوافــق ‪1434/1/27‬ه ـ‬\n‫الســاعة التاســعة والنصــف ويف املوعــد احملــدد افتتحــت اجللســة ‪ ،‬ويف‬\n‫هــذه اجللســة حضــر املدعــي واملدعــى عليــه وحضــر مــع املدعــي ابنــه‬\n‫حامــل الســجل املدنــي رقــم ‪ ،‬وبســؤال املدعــي ألديــك مزيــد بينــة أجــاب‬\n‫ا لــدي صــورة مــن إيصــال االســتالم للبريــد املمتــاز املرســل مــن قبلــي‬  ‫قائـ ً‬\n\n\n                                                                                          ‫‪180‬‬\n\f      ‫للمدعــى عليــه وموقــع علــى االســتالم مــن قبــل املدعــى عليــه بتاريــخ‬\n      ‫‪30‬ربيــع األول‪1433‬ه ـ ومبــن فيــه رقــم اإلرســالية املســتلمة واملطابقــة‬\n      ‫للرقــم املــدون يف الفاتــورة التــي قدمتهــا اجللســة الســابقة هكــذا قــرر‬\n      ‫وبالطــاع عليهــا وجدتهــا كمــا ذكــر وبعرضهــا علــى املدعــى عليــه‬\n      ‫صــادق علــى صحــة توقيعــه وأنــه اســتلم البريــد املرســل مــن املدعــي‬\n      ‫ا أن هــذا االخطــار الــذي اســتلمته كان مذكــور ًا فيــه‬              ‫وأضــاف قائ ـ ً‬\n      ‫طلــب زيــادة اإليجــار للســنة اجلديــدة التــي تبــدأ بتاريــخ ‪1433/7/13‬ه ـ‬\n      ‫وقــد اســتلمت هــذه اإلخطــار يف شــهر ربيــع الثانــي لعــام ‪1433‬ه ـ هكــذا‬\n      ‫ا اإلخطــار طلــب منــك زيــادة اإليجــار أو اإلخــاء عنــد‬        ‫قــرر فســألته قائـ ً‬\n      ‫ا نعــم ولكــن ملــاذا أزيــده ‪ ،‬علمــا بأنــه قــد‬‫انتهــاء مــدة العقــد أجــاب قائـ ً‬\n      ‫اســتلم املدعــي منــي إيجــار كامــل ســنة ‪1433‬ه ـ ولــدي إقــرار موقــع مــن‬\n          ‫إبــن املدعــي بذلــك هكــذا أجــاب ثــم أبــرز لنــا ورقــة مــن مطبوعــات‬\n      ‫مؤسســة ‪........‬للمقــاوالت العامــة وتضمنــت مــا نصــه « أقــر أنــا أننــي‬\n      ‫اســتلمت مبلــغ وقــدره ثمانيــة آالف ريــال مــن وهــو إيجــار البوفيــة الواقعــة‬\n      ‫يف ‪........‬ســنة ‪1433‬ه ـ واهلل ولــي التوفيــق «انتهــى نصهــا وبعرضهــا علــى‬\n      ‫ا هــذا املبلــغ إيجار الســنة املنتهيــة بتاريخ‬ ‫احلاضــر وســؤاله عنهــا قــرر قائـ ً‬\n      ‫‪1433/7/13‬هـ بدليل تاريخ تسليمه لهذا املبلغ يف ‪1433/1/11‬هـ وهو‬\n      ‫بدايــة الســتة األشــهر األخيــرة للســنة املنتهيــة يف ‪1433/7/13‬ه ـ وأمــا‬\n      ‫الســنة احلالية فلم نســتلم منه شــيء حتى اآلن ‪ ،‬وكيف أســتلم منه مبلغ‬\n      ‫الســتة األشــهر للســنة اجلديــدة دون زيــادة مــع إخبارنــا لــه ســابق ًا باإلخــاء‬\n      ‫هكــذا أجــاب وبعــرض جوابــه علــى املدعــي صــادق علــى صحتــه ‪ ،‬ثــم‬\n      ‫رفعــت اجللســة النتهــاء وقتهــا ودخــول وقــت اجللســة التــي تليهــا إلــى يــوم‬\n      ‫الثالثــاء املوافــق ‪1434/2/26‬ه ـ الســاعة التاســعة والنصــف ويف املوعــد‬\n\n\n‫‪181‬‬\n\f‫احملــدد افتتحــت اجللســة وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه‬\n‫مــع تبلغــه مبوعــد هــذه اجللســة يف ضبــط اجللســة الســابقة‪ ،‬وبعــد التأمــل‬\n‫يف مــا ســبق ضبطــه وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا‬\n‫قدمــه الطرفــان مــن أوراق ومبــا أن املدعــى عليــه أقــر باجللســة الثانيــة‬\n‫باســتالمه لإلخطــار املرســل مــن قبــل املدعــي املتضمــن عــدم رغبتــه يف‬\n‫جتديــد اإليجــار لســنة أخــرى بعــد إنــكاره الســتالمه يف اجللســة األولى‪،‬‬\n‫ومبــا أن العقــد نــص فيــه علــى أنــه يتجــدد مــا لــم يخطــر أي مــن الطرفــن‬\n‫اآلخــر بشــأن عــدم رغبتــه يف التجديــد‪ ،‬وقــد قــدم املدعــي ذلــك اإلخطار‬\n‫وأقــر املدعــى عليــه باســتالمه‪ ،‬ونظــرا إلــى أن مــا قدمــه املدعــى عليــه‬\n‫بشــأن تســليمه إليجــار احملــل لعــام ‪1433‬ه ـ كامــا املــدون نصهــا أعــاه‬\n‫وأنــه يعــد جتديــدا للعقــد محتمــل أن يكــون للســتة األشــهر األولــى لعــام‬\n‫‪1433‬ه ـ كمــا أجــاب بــه ابــن املدعــي احلاضــر باجللســة الســابقة ‪ ،‬ويؤيــد‬\n‫ذلــك االحتمــال أن عــادة النــاس ومــا تعارفــوا عليــه تســليم األجــرة بدايــة‬\n‫كل ســتة أشــهر‪ ،‬وليــس مــن عادتهــم تســليم األجــرة للســنة املقبلــة قبــل‬\n‫ابتدائهــا‪ ،‬والعــادة محكمــة‪ ،‬وإذا تطــرق االحتمــال بطــل االســتدالل‬\n‫كمــا قــرر ذلــك أهــل العلــم‪ ،‬إضافــة علــى أنهــا غيــر موقعــة مــن املدعــي‬\n‫وإمنــا مــن ابنــه‪ ،‬ولــكل مــا تقــدم فقــد حكمــت بإلــزام املدعــى عليــه‬\n‫بإخــاء عقــار املدعــي حــاال ويعتبــر هــذا احلكــم يف حقــه حضوريــا‪،‬‬\n‫وأفهمــت املدعــي بــأن لــه مطالبــة املدعــى عليــه فيمــا يخــص أجــرة‬\n‫الفتــرة مــن تاريــخ انتهــاء العقــد وحتــى تاريــخ اإلخــاء‪ ،‬وبعــرض احلكــم‬\n‫علــى املدعــي قــرر قناعتــه بــه وأمــرت ببعــث نســخة مــن صــك احلكــم‬\n‫للمدعــى عليــه لتمكينــه مــن االعتــراض عليــه خــال ثالثــن يومــا مــن‬\n‫اســتالمه لنســخة احلكــم وإذا لــم يتقــدم باعتراضــه خاللهــا ســقط حقــه‬\n\n\n                                                                                     ‫‪182‬‬\n\f      ‫يف االعتــراض واكتســب احلكــم القطعيــة‪ ،‬وختمــت اجللســة الســاعة‬\n      ‫العاشــرة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/26‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف يــوم‬\n      ‫األحــد املوافــق ‪1434/06/04‬ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــرة‬\n      ‫إال ربــع وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫برقــم ‪ 332228478‬يف ‪1434/05/28‬ه ـ وبرفقهــا قــرار التصديــق‬\n      ‫الصــادر مــن الدائــرة احلقوقيــة السادســة مبحكمــة االســتئناف برقــم‬\n      ‫‪ 34217825‬يف ‪1434/05/20‬ه ـ واملتضمــن بعــد املقدمــة مــا نصــه «‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر املوافقــة‬\n      ‫علــى احلكــم‪ ،‬وبــاهلل التوفيــق وصلى اهلل على نبينا محمد وآله وصحبه‬\n      ‫وســلم‪ ،‬قاضــي اســتئناف‪ ...........‬ختــم وتوقيــع‪ ،‬قاضــي اســتئناف‪...........‬‬\n      ‫ختــم وتوقيــع‪ ،‬رئيــس الدائــرة‪ ...........‬ختــم وتوقيــع انتهــى نصــه ‪ ،‬وللعلــم‬\n      ‫جــرى حتريــره‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                           ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/06/04‬ه ـ‬\n      ‫احلمــد هلل‪ ،‬والصــاة والســام علــى رســول اهلل‪ ،‬وبعــد ‪ :‬فق ــد ج ــرى م ّنــا‬\n      ‫نحـن رئيس وأعضاء الدائـرة احلقوقيـة السادسة يف محكمة االستئناف‬\n      ‫مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هذا احلكم الصادر من فضيلة‬\n      ‫الشــيخ‪ ...........‬القاضــي باحملكمــة العامــة بالباحة‪،‬واملســجل بع ــدد‬\n      ‫‪ 3448464‬وتاريــخ ‪1434/2/26‬هـ‪،‬املتضمــن دعــوى ضــد‪ ،‬احملكــوم‬\n      ‫في ــه مبــا دون باطــن الصك‪،‬وبدراس ــة احلكــم وص ــورة ضبط ــه والئحتــه‬\n      ‫االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‪،‬واهلل املوفــق‪ .‬وصل ــى اهلل‬\n                                        ‫عل ــى نبينا محمد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n‫‪183‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":177,"source_page_end":183,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4e4f47655152915710ed17ee5c1a767881592b32039b28903d384fbcf6c98b8a","normalized_text_hash":"1527654b1aa7a83538c21df8bc02820ca8821cb03c64df685d7a8469b88e564a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p177-344846"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b44c14fe-5947-5f4b-aab6-6a7058b856b5","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -مستثمر -استرداد ثمن أجره مدفوعة لتعرض العقار لإلزالة -مراعاة اختاف األجرة الختاف املوسم -تقدير األجرة عن طريق قسم اخلبراء -إلزام املدعى عليه بإعادة جزء من ثمن األجرة -صرف النظر عن غير ذلك من طلبات للمدعى.","document_number":"34231967","case_number":"33644605","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/5","year":"1434","subject":"عقد -إجارة -مستثمر -استرداد ثمن أجره مدفوعة لتعرض العقار لإلزالة -مراعاة اختاف األجرة الختاف املوسم -تقدير األجرة عن طريق قسم اخلبراء -إلزام املدعى عليه بإعادة جزء من ثمن األجرة -صرف النظر عن غير ذلك من طلبات للمدعى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/6/5 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34231967 :‬‬\n                   ‫َر ْق ُم الدعوى‪33644605 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34281939‬تاريخه‪1434/7/29 :‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬مســتثمر ‪ -‬اســترداد ثمــن أجــره مدفوعــة لتعــرض‬\n‫العقــار لإلزالــة ‪ -‬مراعــاة اختــاف األجــرة الختــاف املوســم ‪ -‬تقديــر‬\n‫األجــرة عــن طريــق قســم اخلبــراء ‪ -‬إلــزام املدعــى عليــه بإعــادة جــزء‬\n‫مــن ثمــن األجــرة ‪ -‬صــرف النظــر عــن غيــر ذلــك مــن طلبــات للمدعــى‪.‬‬\n\n\n\n\n‫قــال املوفــق يف املغنــي ‪ »:28/8‬فــإن كان أجــر املــدة متســاويا فعليــه بقــدر‬\n‫مــا مضــى إن كان قــد مضــى النصــف فعليــه نصف األجــر وإن كان قد‬\n‫مضــى الثلــث فعليــه الثلــث كمــا يقســم الثمــن علــى املبيــع املتســاوي‬\n‫وإن كان مختلفــا كــدار أجرهــا يف الشــتاء أكثــر مــن أجرهــا يف‬\n‫الصيــف وأرض أجرهــا يف الصيــف أكثــر مــن الشــتاء أو دار لهــا موســم‬\n‫كــدور مكــة رجــع تقوميــه إلــى أهــل اخلبــرة ويقســط األجــر املســمى‬\n‫علــى حســب قيمــة املنفعــة كقســمة الثمــن علــى األعيــان املختلفــة يف‬\n                      ‫البيــع»‪ ،‬وينظــر أيضــا شــرح منتهــى اإلرادات ‪.108/5‬‬\n\n\n\n\n                                                                                     ‫‪118‬‬\n\f      ‫ادعــى املدعــي بدعــوى ضــد املدعــى عليــه بأنــه اســتأجر منــه عقــار ًا‬\n      ‫عشــر ســنوات يدفــع الثمــن بدايــة كل عــام ويف العــام الثانــي وبعدمــا‬\n      ‫دفــع األجــرة أول العــام صــدر قــرار بإزالــة املبنــى خــال العــام الثانــي‬\n      ‫وقبــل موســم احلــج وألنــه ال يســتفاد مــن املبنــي حقيقــة إال يف موســم احلــج‬\n      ‫وألن ثمــن األجــرة كان مرتفعــا لطــول املــدة فقــد طلــب إعــادة مــا ســلمه‬\n      ‫مــن ثمــن أجــرة الســنة الثانيــة وإعــادة تقديــر أجــرة الســنة األولــى التــي‬\n      ‫اســتفاد فيهــا مــن العقــار قبــل إزالتــه ورد لــه الفــارق بينــه وبــن األجــرة‬\n      ‫املســلمة‪ ،‬أقــر املدعــى عليــه بالعقــد والثمــن والواصــل وتاريــخ اإلخــاء‬\n      ‫وألن االتفــاق علــى األجــرة كان ســنويا فقــد طلــب تســليمه بقيــة األجــرة‬\n      ‫املســتحقة للعــام الثانــي وصــرف النظــر عــن دعــوى املدعــي‪ ،‬جــرى بعــث‬\n      ‫املعاملــة لهيئــة النظــر لتقديــر أجــرة العقــار للمــدة من‪1433/1/1‬ه ـ حتــى‬\n      ‫‪1433/7/30‬ه ـ حســب األجــرة املدونــة يف العقــد مــع مالحظــة املواســم‬\n      ‫املعتبــرة وأثرهــا يف األجــرة فــوردت بتقديرهــا بأربعمئــة و عشــرين ألــف‬\n      ‫ريــال ‪ -‬لتصــادق الطرفــن علــى مقــدار املبلــغ املدفــوع مــن أجــرة عــام‬\n      ‫‪1433‬ه ـ وأنــه مليــون وســتمائة ألــف ريــال كمــا تصادقــا علــى أن املــدة‬\n      ‫التــي بقــي فيهــا املدعــي أصالــة يف العقــار وعلــى تاريــخ اإلخــاء وفصــل‬\n      ‫التيــار الكهربائــي وألن هيئــة النظــر قــدرت أجــرة هــذه املــدة بأربعمائــة‬\n      ‫وعشــرين ألــف ريــال وألن عقــد اإلجــارة عقــد الزم للطرفــن وألن أجــرة‬\n      ‫العقــار مبكــة تختلــف حســب املواســم فأجرتهــا يف احلــج ورمضــان‬\n      ‫تختلــف عــن باقــي الســنة لــذا فيرجــع تقديــر األجــرة ألهــل اخلبــرة‪ ،‬قــال‬\n      ‫املوفــق يف املغنــي ‪ »:28/8‬فــإن كان أجــر املــدة متســاويا فعليــه بقــدر مــا‬\n\n‫‪119‬‬\n\f‫مضــى إن كان قــد مضــى النصــف فعليــه نصــف األجــر وإن كان قــد‬\n‫مضــى الثلــث فعليــه الثلــث كمــا يقســم الثمــن علــى املبيــع املتســاوي وإن‬\n‫كان مختلفــا كــدار أجرهــا يف الشــتاء أكثــر مــن أجرهــا يف الصيــف‬\n‫وأرض أجرهــا يف الصيــف أكثــر مــن الشــتاء أو دار لهــا موســم كــدور‬\n‫مكــة رجــع تقوميــه إلــى أهــل اخلبــرة ويقســط األجــر املســمى علــى حســب‬\n‫قيمــة املنفعــة كقســمة الثمــن علــى األعيــان املختلفــة يف البيــع»‪ ،‬ينظــر‬\n‫أيضــا شــرح منتهــى اإلرادات ‪108/5‬وبعــد خصــم األجــرة التــي قدرتهــا‬\n‫هيئــة النظــر للمــدة التــي بقــي فيهــا املدعــي يف العقــار مــن املبلــغ الــذي‬\n‫دفعــه املدعــي مــن أجــرة عــام ‪1433‬ه ـ فقــد حكمــت احملكمــة علــى‬\n‫املدعــى عليــه أصالــة بــأن يدفــع للمدعــي مليــون ومائــة وثمانــن ألف ريال‬\n‫ورد دعــوى املدعــي بإعــادة تقديــر أجــرة عــام ‪1432‬هــ‪ ،‬بعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــي وكالــة القناعــة وقــرر املدعــى عليــه عــدم‬\n‫القناعــة فأفهــم بالتعليمــات‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪....................‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33644605‬وتاريــخ‬\n‫‪ 1433/11/09‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331978291‬وتاريــخ‬\n‫‪ 1433/11/09‬ه ـ يف يــوم الثالثــاء املوافــق‪ 1433/11/23‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪09 : 30‬وفيهــا حضــر ‪...........................‬بالســجل املدنــي‬\n‫رقم………………‪..‬بوكالتــه عــن …………………أصالــة عــن‬\n‫نفســه وبصفتــه مديــر وشــريك لشــركة ‪ .......‬احملــدودة بالوكالــة‬\n                                                                                       ‫‪120‬‬\n\f      ‫الصــادرة مــن كتابــة العــدل الثانية مبكــة املكرمة برقم ‪5106/4935‬‬\n      ‫يف ‪1433/2/3‬ه ـ والتــي تخولــه املدافعــة واملرافعــة وحضــور اجللســات‬\n      ‫واإلقــرار والصلــح ‪...‬الــخ وادعــى علــى احلاضــر معــه ‪ .......‬بالســجل املدنــي‬\n      ‫رقــم ‪ .......‬بوكالتــه عــن ‪ .......‬بالوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة بغــرب مكــة برقــم ‪ 341732‬يف ‪1434/1/3‬ه ـ والتــي تخولــه‬\n      ‫إقامــة الدعــاوى واملرافعــة واملدافعــة والصلــح والتنــازل ‪..‬الــخ قائــا يف‬\n      ‫دعــواه عليــه لقــد اســتأجر موكلــي مــن املدعــى عليــه العمــارة الواقــع‬\n      ‫بحــي ‪ ...‬ملــدة عشــر ســنني بــدأ بتاريــخ ‪1432/01/01‬ه ـ وتنتهــي يف‬\n      ‫‪1441/12/30‬ه ـ بأجــرة ســنوية مليونــن ومائــة ألــف ريــال وقــد دفــع‬\n      ‫موكلــي أجــرة عــام ‪1432‬ه ـ كاملــة وانتفع بالعــن يف ذلك العام ثم دفع‬\n      ‫مــن أجــرة عــام ‪1433‬ه ـ مبلــغ وقــدره مليون وســتمائة وعشــرون ألف ريال‬\n      ‫فقــط ثــم دخــل العقــار يف مشــروع توســعة الســاحات الشــمالية وتقــررت‬\n      ‫إزالــة املبنــى وفصــل التيــار الكهربائــي عنــه يف ‪1433/8/1‬ه ـ ورفــع‬\n      ‫موكلــي يــده عــن املبنــى يف ذلــك التاريــخ وألن موكلــي لــم ينتفــع بالعــن‬\n      ‫يف ذلــك العــام ألن العقــار ال ينتفــع بــه إال يف موســم احلــج فقــط ويطلــب‬\n      ‫إلــزام املدعــى عليــه أصالــة بإعــادة مــا اســتلمه مــن أجــرة ذلــك العــام مبلــغ‬\n      ‫وقــدره مليــون وســتمائة وعشــرون ألــف ريالكمــا أن موكلــي إمنــا وافــق‬\n      ‫علــى أجــرة املبنــى املرتفعــة بســبب طــول املــدة وألن موكلــي لــم ينتفــع‬\n      ‫منــه إال لســنه واحــده فموكلــي يطلــب إعــادة تقديــر أجــرة الســنة التــي‬\n      ‫انتفــع بهــا وإلــزام املدعــى عليــه بدفــع الباقــي بعــد التقديــر هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليــه وكالــة عــن دعــوى املدعــي أجــاب قائــا صحيــح‬\n      ‫ان موكلــي اجــر العقــار علــى املدعــي أصالــة الواقــع بالتيســير ملــدة‬\n      ‫عشــر ســنني تبــدأ يف ‪1432/1/1‬ه ـ وتنتهــي يف‪1441/12/30‬ه ــبأجرة‬\n\n\n‫‪121‬‬\n\f‫ســنوية مليونــن ومائــة الــف ريــال وقــد اســتلم موكلــي أجــرة عام‪1432‬هـ‬\n‫كاملــة وأمــا أجــرة عام‪1433‬ه ـ فــا صحــة ملــا ذكــره املدعــي وكالــة‬\n‫فــإن موكلــه لــم يســلم ملوكلــي مليــون وســتمائة وعشــرين الــف‬\n‫ريــال وإمنــا ســلم ملوكلــي خمســمائة الــف ريــال فقــط وكان التســليم‬\n‫مبوجــب شــيك مســحوب علــى مصــرف ‪ ...‬يف شــهر جمــادى الثانيــة‬\n‫مــن عــام ‪1433‬ه ــوقد صــرف موكلــي هــذا الشــيك واســتلم املبلــغ ثــم‬\n‫دخــل املوقــع يف مشــروع توســعة الســاحات الشــمالية ومت فصــل التيــار‬\n‫الكهربائــي بتاريــخ ‪1433/8/1‬ه ــوألنأجرة كامــل العــام ‪1433‬ه ـ هــي‬\n‫مليونــان ومائــة ألــف ريــال ولــم يســتلم موكلــي مــن أجــرة ذلــك العــام‬\n‫إال خمســمائة ألــف ريــال وقــد انتفــع املدعــى عليــه بالعقــار ملــدة ســبعة‬\n‫أشــهر كاملــة مــن ‪1433/1/1‬ه ـ حتــى ‪1433/7/30‬ه ـ وألن أجــرة هــذه‬\n‫املــدة هــي مبلــغ وقــدره مليــون وأربعمائــة ألــف ريــال لــذا فــإن موكلــي‬\n‫يطلــب إلــزام املدعــى عليــه أصالــة بدفــع هــذا املبلــغ املتبقــى تســعمائة‬\n‫ألــف ريــال وأمــا ماذكــره املدعــي أصالــة مــن طلــب إعــادة تقديــر أجــرة‬\n‫العقــار الســنوية وعلــل ذلــك بأنــه وافــق عــن هــذه األجــرة بســببط وال ملــدة‬\n‫وانــه لــم ينتفــع مــن العقــار إال لعــام وســبعة أشــهر فــإن هــذا الطلــب غيــر‬\n‫صحيــح ألن بــن املدعــي أصالــة وموكلــي عقــد مذكــور فيــه أجــرة‬\n‫كل ســنة وأطلــب صــرف النظــر عــن هــذا الطلــب ألنــه غيــر صحيــح‬\n‫هــذه إجابــة موكلــي وبعــرض ذلــك علــى املدعــي وكالــة قــال الصحيــح‬\n‫مــا جــاء يف دعــوى موكلــي وموكلــي ســلم مليــون وســتمائة وعشــرين‬\n‫الــف ريــال مــن أجــرة عــام ‪1433‬ه ـ للمدعــى عليــه أصالــة حيــث ســلمه‬\n‫ثــاث شــيكات علــى مصــرف ‪ ...‬األول مببلــغ ســبعمائة وســبعني الــف‬\n‫ريــال والثانــي مبلــغ خمســمائة الــف ريــال والثالــث مببلــغ عشــرين الــف‬\n\n\n                                                                                        ‫‪122‬‬\n\f      ‫ريــال كمــا ان موكلــي اتفــق مــع املدعــى عليــه أصالة يف املادة السادســة‬\n      ‫مــن العقــد علــى إن يقــوم موكلــي بتأثيــث الفنــدق مببلــغ ثمامنائــة ألــف‬\n      ‫ريــال ويخصــم هــذا املبلــغ منأجــرة عام‪1432‬ه ـ و‪1433‬ه ـ علــى النحــو‬\n      ‫اآلتــي أوال ‪ /‬أربعمائــة وســبعني ألــف ريــال مــن أجــرة عام‪1432‬ه ــثانيا‪/‬‬\n      ‫ثالثمائــة وثالثــن ألــف ريــال مــن أجرةعام‪1433‬ه ــوبذا يتبــن لكــم أن‬\n      ‫موكلــي دفــع للمدعــى عليــه أصالــة مليــون وســتمائة وعشــرين ألــف‬\n      ‫ريــال وأمــا مــا ذكــره املدعــى عليــه مــن أجــرة الفترةمن‪1433/1/1‬ه ـ‬\n      ‫حتــى ‪1433/7/30‬ه ــهي مليــون وأربعمائــة ألــف ريــال فــا صحــة لــه الن‬\n      ‫هــذه الفتــرة ليــس لهــا أجــرة يف احلقيقــة الن العمــارة ال يســتفاد منهــا إال‬\n      ‫يف موســم احلــج فقــط وكامــا ألجــرة هــي ملوســم احلــج فقــط وأمــا باقــي‬\n      ‫العــام فليــس لــه أجــرة ‪ .‬هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫وكالــة قــال إننــي راجعــت موكلــي وتبــن أن مــا ذكــره املدعــي وكالــة‬\n      ‫بعضــه صحيــح وبعضــه غيــر صحيــح فالصحيــح منــه أن موكلــي اســتلم‬\n      ‫مــن املدعــي وكالــة مــن أجــرة عــام ‪1433‬ه ـ مبلــغ وقــدره مليون وســتمائة‬\n      ‫ألــف ريــال فقــط علــى النحــو اآلتــي ‪ -:‬اوال)‪ -:‬ســبعمائة وســبعون ألــف‬\n      ‫ريــال مبوجــب شــيك ‪ .‬ثانيــا)‪ -:‬خمســمائة ألــف ريــال مبوجــب شــيك‬\n      ‫أيضــا وهــو املبلــغ الــذي ذكرتــه يف اجللســة املاضيــة ‪ .‬ثالثــا)‪ -:‬ثالثمائــة‬\n      ‫وثالثــون ألــف ريــال وهــو اجلــزء الثانــي مــن ثمــن األثــاث الــذي اشــتراه‬\n      ‫املدعــي أصالــة بثمامنائــة ألــف ريــال واملنصــوص عليــه يف املــادة السادســة‬\n      ‫مــن العقــد وأمــا مــا ذكــر املدعــي مــن أن موكلــي اســتلم عشــرين ألــف‬\n      ‫ريــال فهــذا غيــر صحيــح ألن هــذا املبلــغ ليــس مــن األجــرة وإمنــا هــو داللــه‬\n      ‫دفعهــا املدعــي أصالــة ملوكلــي هكــذا قــرر وبعــرض ذلــك علــى املدعــى‬\n      ‫وكالــة قــال إن موكلــي يكتفــي بهــذا املبلــغ الــذي أقــر بــه املدعــى‬\n\n\n‫‪123‬‬\n\f‫عليــه وال يطالــب مببلــغ العشــرين ألــف ريــال الــذي أنكــره املدعــى عليــه‬\n‫وكالــه وبــذا يكــون أجمالــي مــا ســلمه موكلــي للمدعــى عليــه أصالــة‬\n‫مــن أجــرة عــام ‪1433‬ه ـ مبلــغ مليــون وســتمائة ألــف ريــال فقــط وموكلي‬\n‫يطلــب الــزام املدعــى عليــه أصالــة بدفعــة هكــذا قــرر ‪ ،‬فطلبــت مــن‬\n‫املدعــي وكالــة عقــد اإلجــارة فأبــرز عقــد ًا مــن مطبوعــات شــركة ‪...‬‬\n‫وهــذا نصــه ‪ -:‬احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‬\n‫وبعــد ففــي يــوم اخلميــس‪1432/5/17 :‬ه ـ املوافــق‪2010/4/21 :‬م بعــون‬\n                                         ‫اهلل وتوفيقــه مت االتفــاق بــن كل مــن ‪:‬‬\n‫‪-‬األستاذ ‪ ........................../‬سعودي بالسجل املدني رقم ‪.......................‬‬\n                        ‫وهــو (املؤجــر) ويشــار إليــه يف هذا العقد بالطرف األول‪.‬‬\n‫‪ --‬شــركة ‪ ..................‬وميثلهــا يف هــذا العقــد األســتاذ‪...................... /‬‬\n‫ســعودي بالســجل املدنــي رقــم ‪ ...........................‬بصفتــه مديــر ًا عام ـ ًا‬\n ‫للشــركة وهــو املســتأجر ويشــار إليــه يف هــذا العقــد بالطــرف الثانــي‪.‬‬\n                                                                                      ‫متهيد‪:‬‬\n‫ملــا كان الطــرف األول ميلــك منفعــة العقــار الواقــع يف ‪ ...‬أمــام احملكمــة‬\n‫القدميــة واململــوك لوقــف ‪ ....................‬مبوجــب الصــك الصــادر مــن‬\n‫محكمــة مكــه املكرمــه برقــم (‪)3/383‬وتاريــخ ‪ 1367/8/3‬ه ــو‬\n‫ذلــك بصفتــه مســتثمر ًا للوقــف مبوجــب صــك اإلذن باالســتثمار الصــادر‬\n‫مــن احملكمــه العامــه مبكــه املكرمــه برقــم ‪ 2/100/33‬بتاريــخ‬\n‫‪ 1430/1/21‬ه ـ واملكــون مــن دور أرضــي ‪ +‬بــدروم ‪ +‬دور ميزانــن‪+‬‬\n‫دور مطعــم‪ +‬دور خدمــات ‪ +‬تســعة ادوار متكــررة ‪ +‬دور أخيــر ورغــب‬\n‫يف تأجيــر املبنــى ملــدة طويلــة لــذا فقــد انعقــدت إرادة الطرفــن علــى‬\n                                                       ‫التأجيــر وفــق البنــود التاليــة ‪:‬‬\n\n\n                                                                                               ‫‪124‬‬\n\f                     ‫أوالً‪ :‬تعتبر املقدمة والتمهيد جزء ًا ال يتجزأ من هذا العقد‪.‬‬\n      ‫ثاني ـاً‪ :‬تكــون مــدة عقــد اإليجــار عشــر ســنوات اعتبــار مــن تاريــخ‬\n                                       ‫‪1432/1/1‬هــ‪ .‬وحتــى ‪1441/12/30‬هــ‪.‬‬\n      ‫ثالث ـاً‪ :‬تكــون القيمــة اإليجاريــة الســنوية للعقــار هــي (‪)2.100000‬‬\n      ‫تســتحق دفعــة واحــدة ويف حالــة تأخــر الطــرف الثانــي عــن دفــع اإليجــار‬\n      ‫املقــرر ملــدة شــهر عــن موعــد حلولــه فيعتبــر عقــد اإليجــار الغيــا ومــن‬\n      ‫حــق الطــرف األول اســتالم عمارتــه حــا ًال علم ـ ًا بــأن الشــيك الصــادر‬\n      ‫مــن الطــرف الثانــي هــو االســاس بالتاريــخ ويكــون الشــيك مصدق ـ ًا‬\n      ‫مــن البنــك ويكــون تاريخــه هــو املعتبــر أو بإيــداع حلســاب الطــرف األول‬\n                                           ‫مبوجــب احلســاب رقــم (‪ )........‬بنــك ‪......‬‬\n      ‫رابع ـاً‪ :‬قــرر الطــرف الثانــي اســتالمه للعقــار بحالــة جيــدة وكان‬\n      ‫االســتالم بتاريــخ ‪1431/11/20‬ه ـ كمــا قــرر الطــرف األول تنازلــه عــن‬\n      ‫القيمــة االيجاريــة للفتــرة مــا بــن اســتالم العقــار ونفــاذ العقــد ولــه حــق‬\n                                                                  ‫االنتفــاع يف هــذه املــده‪.‬‬\n      ‫خامسـاً‪ :‬قــرر الطــرف األول اســتالمه مــن الطــرف الثانــي كامــل ايجار‬\n      ‫الســنه األولــى التــي تبــدأ مــن ‪1432/1/1‬ه ـ حتــى ‪1432/12/30‬ه ـ‬\n      ‫وقــدره (مليونــن ومائــة ألــف ريــال فقــط) منهــا مادفــع شــيكات ومنهــا‬\n      ‫مــا دفــع نقــد ًا ومنهــا مــا خصــم مــن قيمــة التأثيث كما ذكر يف سادسـ ًا‬\n      ‫فقــرة (أ)‪ ،‬كمــا يقــرر الطــرف االول خلــو العقــار مــن أي التزامــات‬\n      ‫أخــرى أو حقــوق ألي أحــد أو مخالفــات بالبلديــه‪ ،‬ويف حالــة ظهــور أي‬\n      ‫مــن ذلــك فإنــه يجــب علــى الطــرف األول إزالتهــا دون أي تكلفــة ماديــة‬\n                                                                    ‫علــى الطــرف الثانــي‪.‬‬\n      ‫سادس ـاً‪ :‬أ‪ -‬علــى الطــرف األول تأثيــث الفنــدق مــن ســرر ومراتــب‬\n\n\n‫‪125‬‬\n\f‫ومكيفــات وتلفزيونــات وثالجــات وقــد فــوض الطــرف االول الطــرف‬\n‫الثانــي بالتأثيــث ويكــون مبلــغ التأثيــث هــو ‪( 800000‬ثمامنائــة ألــف‬\n‫ريــال فقــط) يخصــم مــن مبلــغ االيجــار للســنة األولــى التــي تبــدأ مــن‬\n‫‪1433/1/1‬ه ـ حتــى ‪1432/12/30‬ه ـ مبلــغ وقــدره ‪( 470000‬أربعمائــة‬\n‫وســبعون ألــف ريــال فقــط ) واملتبقــي وقــدره ‪( 330000‬ثالثمائــة وثالثون‬\n‫ألــف ريــال فقــط) يخصــم مــن ايجــار الســنه الثانــي هــو التــي تبــدأ مــن‬\n‫‪1433/1/1‬ه ـ حتــى ‪1433/12/30‬ه ـ ويكــون املتبقــي مــن ايجــار‬\n‫الســنه الثانيــه املذكــوره ‪ 1770000‬ريــال (مليــون وســبعمائة وســبعون‬\n‫ألــف ريــال فقــط ) بعــد أن مت إلغــاء احملضــر الســابق اخلــاص بالتأثيــث‬\n‫بعــد أن مت تخفيــض قيمــة التأثيــث مــن (مليــون وثالثمائــة وأحــد عشــر‬\n‫ألــف ريــال ) إلــى (ثمامنائــة ألــف ريــال فقــط ) ويكــون التأثيــث املطلــوب‬\n‫مــن الطــرف الثانــي كمــا هــو مذكــور يف بدايــة البنــد سادس ـ ًا وإذا‬\n‫رغــب الطــرف الثانــي إحضــار أثاثـ ُا إضافيـ ًا فــا مانــع علــى أن يحــق لــه‬\n‫ســحبه مــع نهايــة العقــد ويراعــي عنــد تســليم املبنــى مــدة اإلســتهالك‬\n          ‫للتأثيــث املذكــور ويكــون قبولــه للتأثيــث يف حالتــه الراهنــه‪.‬‬\n‫ب‪ -‬يتــم دفــع مبلــغ وقــدره ‪( 770000‬ســبعمائة وســبعون ألــف ريــال فقط)‬\n‫يف ‪ 1432/9/15‬ه ـ وهــي دفعــه مقدمــه مــن الســنه الثانيــه التــي تبــدأ يف‬\n‫‪1433/1/1‬ه ـ ويتبقــى مليــون ريــال تدفــع يف ‪1433/1/1‬ه ـ لهــذه الســنه‬\n                                                                           ‫فقط‪.‬‬\n‫ســابعاً‪ -:‬اتفــق الطرفــان علــى إن يكــون الدكاكــن االثنــن الصغيــره‬\n‫وغرفــة احلــارس الصغيــره التــي باجلهــة اجلنوبيــة ليســت يف اإليجــار‬\n‫وكذلــك البــدروم الــذي مدخلــه مــن اجلهــة الشــماليه مبدخــل خــاص ‪.‬‬\n‫ثامنـاً‪ :‬يجــوز للطــرف الثانــي تأجيــر العقــار محــل العقــد ملــن يشــاء مــدة‬\n\n\n                                                                                     ‫‪126‬‬\n\f                           ‫العقــد بــدون الرجــوع للطــرف األول أو أخــذ موافقتــه ‪.‬‬\n      ‫تاســع ًا ‪ :‬يســري هــذا العقــد علــى الطرفــن وورثتهمــا الشــرعيني طيلــة‬\n                      ‫مدتــه وال يســقط بوفــاة أحدهمــا بــل يكــون ملزمــا لهمــا‪.‬‬\n      ‫عاشــر ًا أقــر الطرفــان مبــا ورد بهــذا العقــد و إطالعهمــا علــى مــا جــاء‬\n      ‫فيــه إطالعــا ً نافيـ ًا للجهالــة والغــرر كمــا يلغــي هــذا العقــد كل ماســواه‬\n                                                                  ‫مــن العقــود الســابقه‪.‬‬\n      ‫احلــادي عشــر ‪ :‬يتكــون هــذا العقــد مــن مقدمــة ومتهيــد و أحــد عشــر‬\n      ‫بنــد مرتبطــات ببعضهــا وقــد حــرر هــذا العقــد مــن نســختني بيــد كل‬\n      ‫مــن الطرفــن نســخة منهــا‪ .‬ا‪.‬ه ـ ‪ ،‬وبعــرض هــذا العقــد علــى املدعــى‬\n      ‫عليــه وكالــة صــادق عليــه وقــال إن املــادة العاشــرة مــن العقــد تــدل علــى‬\n      ‫أن األجــرة املتفــق عليــه هــي برضــا الطرفــن وليــس فيهــا غــرر وال غــن‬\n      ‫وألن أجــرة املــدة مــن ‪1433/1/1‬ه ـ حتــى ‪1433/7/30‬ه ـ هــي مليــون‬\n      ‫وأربعمائــة ألــف ريــال وألن موكلــي اســتلم مــن املدعــي أصالــة مليــون‬\n      ‫وســتمائة ألــف ريــال لــذا فــإن املتبقــي للمدعــي أصالــة مائتــي ألــف ريــال‬\n      ‫وموكلــي مســتعد بدفــع هــذا املبلــغ للمدعــي أصالــة ألنــه حقــه هكــذا‬\n      ‫قــرر ‪،‬وعليــه فقــد جــرى بعــث املعاملــة لهيئــة النظــر لتقديــر أجــرة العقــار‬\n      ‫للمــدة مــن ‪1433/1/1‬ه ـ حتــى ‪1433/7/30‬ه ـ حســب األجــرة املدونــه‬\n      ‫يف العقــد مــع مالحظــة املواســم املعتبــرة وأثرهــا يف األجــرة وذلــك‬\n      ‫بخطابــي رقــم ‪ 331978291‬يف ‪1434/4/24‬ه ـ فــوردت اإلفــادة مــن‬\n      ‫هيئــة النظــر باخلطــاب رقــم ‪ 331978291‬يف ‪1434/05/08‬ه ـ وهــذا‬\n      ‫نــص احلاجــة منــه «تقــدر اجــرة العقــار للفتــرة مــن ‪1433/1/1‬ه ـ حتــى‬\n      ‫‪1433/07/30‬ه ـ مبلــغ وقــدره ( ‪ 420.000‬فقــط اربعمائــة و عشــرون‬\n      ‫الــف ريــال ال غيــر ) ا‪.‬ه ـ « ثــم قــرر الطرفــان أن بينهمــا محاولــة صلــح‬\n\n\n‫‪127‬‬\n\f‫وطلبــا امهالهمــا لذلــك ثــم يف جلســة أخــرى حضــر الطرفــان وكالــة‬\n‫وقــررا أنهمــا وموكليهمــا لــم يتوصــا إلــى صلــح وقــرر املدعــي وكالــة‬\n‫أن موكلــي يطالــب أيضــا إعــادة تقديــر أجــرة عــام ‪1432‬ه ـ وهــي الســنة‬\n‫التــي اســتفادتها بالكامــل ألن موكلــي إمنــا وافــق علــى األجــرة الســنوية‬\n‫املرتفعــة واملدونــة يف العقــد بســبب طــول املــدة ولكــن بعــد اإلزالــة فــان‬\n‫موكلــي يــرى أن هــذه األجــرة مرتفعــة وهــو يطلــب إعــادة تقديــر أجــرة‬\n‫تلــك الســنة هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال‬\n‫إن العقــد بــن الطرفــن ملــزم لهمــا واألجــرة منصــوص فيــه أنهــا ســنوية‬\n‫والعقــد برضــي الطرفــن هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وبعــد االطــاع علــى عقــد اإلجــارة بــن الطرفــن ومصادقتهمــا‬\n‫عليــه وألن الطرفــن تصادقــا علــى مقــدار املبلــغ املدفــوع مــن أجــرة عــام‬\n‫‪1433‬ه ـ وأنــه مليــون وســتمائة ألــف ريــال كمــا تصادقــا علــى أن املــدة‬\n‫التــي بقــي فيهــا املدعــي أصالــة يف العقــار وعلــى تاريــخ اإلخــاء وفصــل‬\n‫التيــار الكهربائــي وألن هيئــة النظــر قــدرت أجــرة هــذه املــدة بأربعمائــة‬\n‫وعشــرين ألــف ريــال وألن عقــد اإلجــارة عقــد الزم للطرفــن وألن أجــرة‬\n‫العقــار مبكــة تختلــف حســب املواســم فأجرتهــا يف احلــج ورمضــان‬\n‫تختلــف عــن باقــي الســنة ولــذا فيرجــع تقديــر األجــرة ألهــل اخلبــرة قــال‬\n‫املوفــق يف املغنــي ‪ ( 28/8‬فــإن كان أجــر املــدة متســاويا فعليــه بقــدر مــا‬\n‫مضــى إن كان قــد مضــى النصــف فعليــه نصــف األجــر وإن كان قــد‬\n‫مضــى الثلــث فعليــه الثلــث كمــا يقســم الثمــن علــى املبيــع املتســاوي وإن‬\n‫كان مختلفــا كــدار أجرهــا يف الشــتاء أكثــر مــن أجرهــا يف الصيــف‬\n‫وأرض أجرهــا يف الصيــف أكثــر مــن الشــتاء أو دار لهــا موســم كــدور‬\n‫مكــة رجــع تقوميــه إلــى أهــل اخلبــرة ويقســط األجــر املســمى علــى حســب‬\n\n\n                                                                                     ‫‪128‬‬\n\f      ‫قيمــة املنفعــة كقســمة الثمــن علــى األعيــان املختلفــة يف البيــع ) ينظــر‬\n      ‫أيضــا شــرح منتهــى اإلرادات البــن النجــار ‪108/5‬وبعــد خصــم األجــرة‬\n      ‫التــي قدرتهــا هيئــة النظــر للمــدة التــي بقــي فيهــا املدعــي يف العقــار مــن‬\n      ‫املبلــغ الــذي دفعــه املدعــي مــن أجــرة عــام ‪1433‬ه ـ فقــد حكمــت علــى‬\n      ‫املدعــى عليــه أصالــة بــأن يدفــع للمدعــي مليــون ومائــة وثمانــن ألف ريال‬\n      ‫ورددت دعــوى املدعــي بإعــادة تقديــر أجرة عام ‪1432‬هـ وبعرض احلكم‬\n      ‫علــى الطرفــن قــرر املدعــي وكالــة القناعــة وقــرر املدعــى عليــه عــدم‬\n      ‫القناعــة وطلــب رفعــه حملكمــة االســتئناف بعــد تقــدمي الئحــة اعتراضيــة‬\n      ‫عليــه فأفهمتــه مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم الصــك‬\n      ‫وتقــدمي الالئحــة االعتراضيــة خــال ثالثــن يومــا مــدة االعتــراض فــاذا‬\n      ‫تاخــر ســقط حقــه يف طلــب االســتئناف واكتســب احلكــم القطعيــة‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                               ‫حــرر يف ‪1434/6/5‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بشــرح فضيلــة الرئيــس برقــم ‪ 33/1978291‬يف ‪1434/8/9‬ه ـ علــى‬\n      ‫خطــاب رئيــس محكمــة االســتئناف مبنطقــة مكــة املكرمــة املكلــف‬\n      ‫برقــم ‪ 331978291‬يف ‪1434/8/6‬ه ـ برفقهــا قــرار التصديــق مبوجــب‬\n                    ‫القــرار رقــم ‪ 34281939‬يف ‪1434/7/29‬ه ـ وهــذا نصــه‪-:‬‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ -:‬فقــد‬\n      ‫جــرى منــا نحــن رئيــس وأعضــاء الدائــرة احلقوقيــة الثالثــة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى هــذا الصــك الصادر‬\n      ‫مــن فضيلــة الشــيخ ‪ ....................‬القاضــي باحملكمــة العامــة مبكــة‬\n      ‫املكرمــة واملســجل بعــدد ‪34231967‬وتاريــخ ‪1434/6/5‬ه ـ املتضمــن‬\n\n\n‫‪129‬‬\n\f‫دعــوى شــركة ‪ ...........‬ضــد ‪ ...........‬يف مبلــغ مالــي احملكــوم فيــه مبــا‬\n‫دون باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــرر باألكثريــة املوافقــة علــى احلكــم ‪ .‬وبــاهلل تعالــى التوفيــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ ،‬قاضــي اســتئناف‬\n‫ختــم وتوقيــع ‪ ...........‬قاضــي اســتئناف ختــم وتوقيــع ‪ ...........‬لــي وجهــة‬\n‫نظــر ‪ ،‬رئيــس الدائــرة ختــم وتوقيــع ‪...........‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/15‬ه ـ‬\n‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n‫نح ــن رئيس وأعضاء الدائ ــرة احلقوقي ــة الثالثة يف محكم ــة االستئناف‬\n‫مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى ه ــذا الصــك الص ــادر مــن‬\n‫فضي ــلة الشي ــخ ‪ ...............‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n‫واملســجل بعــدد ‪ 34231967‬وتــاري ــخ ‪1434/6/5‬ه ـ املتضمــن دعــوى‬\n‫شــركة ‪...........‬ضــد ‪ ...........‬يف مبلــغ مالــي احملكــوم فيــه مبــا دون‬\n‫باطنه‪ .‬وبــدراس ــة احلك ــم وص ــورة ضبط ــه والئحته االعتراضية تقـ ـ ـ ــرر‬\n‫باألكثريــة املـ ــوافقـ ـ ـ ــة علــى احلكــم‪ .‬وبــاهلل تعالــى التوفيــق وصل ــى اهلل‬\n                                ‫عل ــى نبي ــنا محم ــد وعل ــى آلـه وصحب ــه وسـلم‪.‬‬\n\n\n\n\n                                                                                          ‫‪130‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":118,"source_page_end":130,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5c21fef458ded7fc51ff74c7d1defbdce8f0d677aa3bd7adddc623deb1b19bc1","normalized_text_hash":"6c344aac3bcbf7e51b499646de8e970df652346b164e3f0d476b8eef6f83320d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p118-34231967"},{"id":"97c14733-3eee-568c-a7d8-96c03de86879","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -طلب إخاء عقار -البينة على املدعى واليمن على من انكر -توجيه اليمن على املدعي -نكول املدعي عن اليمن - حكم بصرف النظر عن دعوى املدعي لنكوله عن اليمن.","document_number":"332031116","case_number":"33656979","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/24","year":"1434","subject":"عقد -إجارة -طلب إخاء عقار -البينة على املدعى واليمن على من انكر -توجيه اليمن على املدعي -نكول املدعي عن اليمن - حكم بصرف النظر عن دعوى املدعي لنكوله عن اليمن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/24 :‬هـ‬\n                       ‫ُ‬                  ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪332031116 :‬‬\n                           ‫َر ْق ُم الدعوى‪33656979 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪ 34376312‬تاريخه‪1434/12/2 :‬هـ‬\n\n\n        ‫عقــد ‪ -‬إجــارة ‪ -‬طلــب إخــاء عقــار ‪ -‬البينــة علــى املدعــى واليمــن علــى‬\n        ‫مــن انكــر‪ -‬توجيــه اليمــن علــى املدعــي ‪ -‬نكــول املدعــي عــن اليمــن ‪-‬‬\n                  ‫حكــم بصــرف النظــر عــن دعــوى املدعــي لنكولــه عــن اليمــن‪.‬‬\n\n\n\n\n        ‫قولــه صلــى اهلل عليــه وســلم (( البينــة علــى املدعــي واليمــن علــى مــن‬\n                                                                              ‫أنكــر ))‬\n\n\n\n\n        ‫ادعــى املدعــي بــأن املدعــى عليــه اســتأجر منه بوفيــه مت ذكر وصفها يف‬\n        ‫نــص القضيــة بأجــرة قدرهــا أربعــون ألــف ريــال ملــدة ثالث ســنوات بتاريخ‬\n        ‫‪1432/2/15‬ه ـ والدفــع مقدم ـ ًا كل ســتة أشــهر وانــه تأخــر يف ســداد‬\n        ‫األجــرة ولــم يلتــزم بهــا يف وقتهــا كمــا انــه اســتغل الرصيــف للتخزيــن‬\n        ‫وجلســة الزبائــن ممــا تعــرض معــه للمســائلة مــن جهــة البلديــة كمــا قــام‬\n        ‫بصبــغ الواجهــة ولــم يتقيــد مبــا جــاء يف عقــد اإليجــار وطلــب املدعــي‬\n        ‫فســخ عقــد اإليجــار وإلــزام املدعــى عليــه بإخــاء البوفيــه وتســليمها‬\n        ‫للمدعــي‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى عقــد اإليجــار واألجــرة‬\n        ‫وقــرر أن اجللســة علــى الرصيــف مت إزالتهــا ومت صبــغ الواجهــة الن احملــل‬\n        ‫ســابق ًا كان مغســلة وملــا مت فتــح البوفيــه مت صبــغ الواجهــة وتنظيفهــا‬\n‫‪131‬‬\n\f‫وأمــا األجــرة فقــرر انــه اتفــق مــع املدعــي علــى تقســيط املبلــغ عشــرة‬\n‫آالف ريــال كل ثالثــة أشــهر‪ ،‬أنكــر املدعــي دعــوى تقســيط األجــرة‬\n‫التــي دفــع بهــا املدعــى عليــه وكالــة وليســت لديــه بينــه وطلــب املدعــى‬\n‫عليــه ميــن املدعــي ونــكل عنهــا‪ ،‬قــرر ناظــر القضيــة ملــا ســبق صــرف‬\n‫النظــر عــن الدعــوى ‪ ،‬صــدر قــرار محكمــة االســتئناف باملصادقــة علــى‬\n                                                                      ‫احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة العامــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام املســاعد برقــم ‪ 33656979‬وتاريــخ ‪ 1433/11/16‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332031116‬وتاريــخ ‪ 1433/11/16‬ه ـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1434/01/10‬ه ـ حضــر ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم وادعــى علــى احلاضــر معــه ســعودي بالســجل‬\n‫رقــم الوكيــل الشــرعي عــن بالوكالــة الصــادرة مــن محكمــة ‪..........‬‬\n‫العامــة برقــم ‪..........‬وتاريــخ ‪1432/2/5‬ه ـ ولكــون املدعــى عليــه لــم‬\n‫يحضــر أصــل الوكالــة فقــد جــرى رفــع اجللســة وتأجلــت إلــى يــوم االثنــن‬\n‫‪1434/1/19‬ه ـ الســاعة العاشــرة وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/1/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/02/06‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر الطرفــان وقــال املدعــى عليــه وكالــة‪:‬‬\n‫إننــي لــم أســتطع إحضــار الوكالــة األصــل لــذا جــرى رفــع اجللســة‬\n‫إلحضارهــا وتأجلــت ليــوم االثنــن ‪1434/02/11‬ه ـ الســاعة العاشــرة‬\n                                                                                   ‫‪132‬‬\n\f      ‫والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/06‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق ‪1434/02/18‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي واملدعــى عليــه املذكــور هويتــه‬\n      ‫بعاليــه الوكيــل الشــرعي عــن بالوكالــة الصــادرة مــن كتابــة عــدل‬\n      ‫محافظــة أحــد رفيــدة برقــم ‪..........‬وتاريــخ ‪1434/2/12‬ه ـ وادعــى األول‬\n      ‫قائــا لقــد أجــرت مــوكل املدعــى عليــه البوفيــه الواقعــة بعمارتــي‬\n      ‫الواقعــة بحــي ‪..........‬علــى شــارع ‪..........‬بقيمــة قدرهــا أربعــون ألــف ريــال‬\n      ‫ملــدة ثــاث ســنوات ابتــداء بتاريــخ ‪1432/2/15‬ه ـ والدفــع مقدمــا كل‬\n      ‫ســتة أشــهر وهــو يتأخــر يف ســداد األجــرة وال يلتــزم بهــا يف وقتهــا كمــا‬\n      ‫أنــه اســتغل الرصيــف للتخزيــن وجلســة للزبائــن ممــا تعرضــت بســببه‬\n      ‫للمســاءلة مــن جهــة بلديــة ‪..........‬كمــا قــام بصبــغ الواجهــة ولــم يتقيــد‬\n      ‫مبــا جــاء يف عقــد اإليجــار وحيــث احلــال مــا ذكــر فإننــي أطلــب فســخ‬\n      ‫العقــد وإلزامــه بإخــاء البوفيــة وتســليمها لــي هــذه دعــواي ولكــون‬\n      ‫وكالــة املدعــى عليــه ناقصــة ال تتضمــن حــق املرافعــة ومــا يتبعهــا فقــد‬\n      ‫جــرى رفــع اجللســة وتاجلــت ليــوم األحــد املوافــق ‪1434/4/7‬ه ـ التاســعة‬\n      ‫والنصــف وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم حــرر يف ‪1434/02/18‬ه ـ‬\n      ‫ويف جلســة أخــرى حضــر الطرفــان وأحضــر املدعــى عليــه وكالــة مــن‬\n      ‫موكلــه صــادرة مــن كتابــة عــدل محافظــة أحــد رفيــدة برقــم ‪..........‬يف‬\n      ‫‪1434/5/29‬ه ـ تخولــه املرافعــة وكافــة إجــراءات التقاضــي وبعــرض‬\n      ‫الدعــوى عليــه قــال مــا ذكــره املدعــي يف دعــواه مــن اســتئجار موكلــي‬\n      ‫منــه البوفيــة التــي ذكــر بالقيمــة واملــدة التــي ذكــر وأن الدفــع مقــدم‬\n\n\n‫‪133‬‬\n\f‫كل ســتة أشــهر فهــذا صحيــح وأمــا مــا ذكــره مــن أن موكلــي ال يلتــزم‬\n‫بســداد األجــرة ولــم يلتــزم مبــا جــاء يف العقــد فغيــر صحيــح وأمــا مــا‬\n‫ذكــره مــن اســتغالل موكلــي للرصيــف فقد كان يوجد فيه كراســي‬\n‫ومت إزالتهــا وأمــا صبــغ الواجهــة فقــد كان احملــل مغســلة وملــا مت فتــح‬\n‫البوفيــه مت صبــغ الواجهــة وتنظيفهــا هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫املدعــي قــال الصحيــح مــا ذكرتــه ولــدي البينــة وأطلــب رفــع اجللســة‬\n‫إلحضارها ويف جلســة أخرى حضر الطرفان وبســؤال املدعي عن بينته‬\n‫علــى ماذكــر قــال إن اجللســة التــي وضعهــا علــى الرصيــف للزبائــن قــد‬\n‫أزالهــا ولــم يبــق إال خــزان املــاء وبســؤاله هــل مت مســاءلته مــن قبــل البلديــة‬\n‫بعدهــا قــال ال وقــدم بيانــا يبــن فيــه تاريــخ اســتحقاق االيجــار وتاريــخ‬\n‫ســداده وبعرضــه علــى املدعــى عليــه قــال مــا جــاء يف صحيــح والســبب يف‬\n‫تأخــري عــن ســداد االيجــار هــو أننــي اتفقــت معــه علــى ذلــك وطلبــت منــه‬\n‫أن يقســط علــي املبلــغ عشــرة آالف كل ثالثــة أشــهر وبعــرض ذلــك علــى‬\n‫املدعــي قــال ماذكــره املدعــى عليــه وكالــة غيــر صحيــح والصحيــح‬\n‫أننــي لــم اتفــق معــه علــى تقســيط املبلــغ إال مــرة واحــدة وبعــرض ذلــك‬\n‫علــى املدعــى عليــه قــال الصحيــح ماذكرتــه وبســؤاله هــل لديــه بينــة‬\n‫علــى ذلــك قــال ال وأطلــب ميينــه وبعــرض اليمــن علــى املدعــي قــال إننــي‬\n‫لــن أحلــف إال علــى أننــي قســطت عليــه املبلــغ إال مــرة واحــدة فجــرى‬\n‫إفهامــه بحلــف اليمــن علــى نفــي مــا ذكــره املدعــى عليــه كامــا فقــال‬\n‫لــن أحلــف علــى ذلــك فكررتــه عليــه ثالثــا فرفــض فبنــاء علــى ماتقــدم‬\n‫مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه وكالــة بصحــة مــا جــاء يف‬\n‫دعــوى املدعــي مــن اســتئجار موكلــه منه احملــل املذكــور بالقيمة واملدة‬\n‫التــي ذكــر وملــا قــرره املدعــي مؤخــرا مــن أنــه مت إزالــة مــا كان موجــودا‬\n\n\n                                                                                           ‫‪134‬‬\n\f      ‫علــى الرصيــف وألن املدعــى عليــه أقــر بأنــه تأخــر يف الســداد بنــاء علــى‬\n      ‫اتفــاق بــن املدعــي وبــن موكلــه ولــم يقــم بينــة علــى ذلــك وطلــب ميــن‬\n      ‫املدعــي وألن املدعــي نــكل عــن اليمــن ولقولــه صلــى اهلل عليــه وســلم‬\n      ‫(البينــة علــى املدعــي واليمــن علــى مــن أنكــر) فقــد صرفــت النظــر‬\n      ‫عــن دعــوى املدعــي وبعرضــه علــى املدعــي قــرر عــدم قناعتــه باحلكــم‬\n      ‫وطلــب رفــع املعاملــة حملكمــة االســتئناف فأفهمتــه أن عليــه التقــدم بعــد‬\n      ‫خمســة أيــام الســتالم نســخة مــن الصــك وتقــدمي الالئحــة االعتراضيــة‬\n      ‫خــال املــدة املقــررة نظامــا وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/30‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء ‪ 1434/12/25‬ه ـ افتتحــت‬\n      ‫اجللســة بنــاء علــى عــودة املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية برقــم ‪ 342093878‬يف ‪1434/12/17‬ه ـ وبرفقهــا قــرار‬\n      ‫أصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة األولــى رقــم ‪34376312‬‬\n      ‫يف ‪1434/12/2‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1434/12/25‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n      ‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف‬\n      ‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة العامــة مبدينــة بالدمــام برقــم ‪332031116‬‬\n      ‫وتاريــخ ‪1434/8/24‬ه ـ واملقيــدة لدينــا برقــم ‪ 342093878‬وتاريــخ‬\n      ‫‪1434/9/1‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ /‬املسـ ّـجل برقــم ‪ 34286020‬وتاريــخ ‪1434/8/2‬ه ـ‬\n\n\n‫‪135‬‬\n\f‫اخلــاص بدعــوى‪ ...........‬ضــد‪ ...........‬يف قضيــة حقوقيــة وقــد تضمــن‬\n‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة‬\n‫علــى احلكــم ‪ ،‬ولبيانــه حــرر يف ‪1434/12/2‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n                                                                              ‫‪136‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":131,"source_page_end":136,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"28bf1df4288ab440f01ac74722535fbf779020842fd20aff633c2712a73fca82","normalized_text_hash":"1e2b6c1c4662f1cd6b93ca58b6db795b999e4e274bb68e2d95a94975546a73bf","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p131-332031116"},{"id":"8f73326c-3d65-57ff-ad5d-69b7e0caff9e","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة مع الوعد بالتملك -سيارة -حادث -بيع السيارة للغير من قبل املدعى عليه -احتساب أقساط السيارة بعد احلادث- سبب عدم السداد راجع للشركة املدعى عليها -طلب فسخ العقد ورفع االسم من القائمة السوداء -األجرة تستحق على املستاخر عند متكنه من االنتفاع -إثبات فسخ العقد واحلكم برفع اسم املدعى من القائمة السوداء.","document_number":"34240533","case_number":"33681073","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/13","year":"1434","subject":"عقد -إجارة مع الوعد بالتملك -سيارة -حادث -بيع السيارة للغير من قبل املدعى عليه -احتساب أقساط السيارة بعد احلادث- سبب عدم السداد راجع للشركة املدعى عليها -طلب فسخ العقد ورفع االسم من القائمة السوداء -األجرة تستحق على املستاخر عند متكنه من االنتفاع -إثبات فسخ العقد واحلكم برفع اسم املدعى من القائمة السوداء.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/6/13 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34240533 :‬‬\n                         ‫َر ْق ُم الدعوى‪33681073 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪/34377281‬ق‪/2‬أ تاريخه‪1434/12/3 :‬هـ‬\n\n\n\n      ‫عقــد ‪ -‬إجــارة مــع الوعــد بالتملــك ‪ -‬ســيارة ‪ -‬حــادث ‪ -‬بيــع الســيارة‬\n      ‫للغيــر مــن قبــل املدعــى عليــه ‪ -‬احتســاب أقســاط الســيارة بعــد احلادث‪-‬‬\n      ‫ســبب عــدم الســداد راجــع للشــركة املدعــى عليهــا ‪ -‬طلــب فســخ العقــد‬\n      ‫ورفــع االســم مــن القائمــة الســوداء ‪ -‬األجــرة تســتحق علــى املســتاخر‬\n      ‫عنــد متكنــه مــن االنتفــاع ‪ -‬إثبــات فســخ العقــد واحلكــم برفــع اســم‬\n                                                ‫املدعــى مــن القائمــة الســوداء‪.‬‬\n\n\n\n\n      ‫‪ .1‬قــول اخلرقــي رحمــه اهلل ‪»:‬فــإن جــاء أمــر غالــب يحجــز املســتأجر عــن‬\n          ‫منفعــة مــا وقــع عليــه العقــد لزمــه مــن األجــر مبقــدار مــدة انتفاعــه»‪.‬‬\n      ‫‪ .2‬قــول املوفــق رحمــه اهلل يف املغنــي أن العــن املســتأجرة «إذا غصبــت‬\n      ‫فللمســتأجر الفســخ ألن فيــه تأخيــر حقــه ‪ ،‬فــإن فســخ فاحلكــم فيــه‬\n      ‫كمــا لــو انفســخ العقــد بتلــف العني ســواء وإن لم يفســخ حتى انقضت‬\n      ‫مــدة اإلجــارة ‪ ،‬فلــه اخليــار بــن الفســخ والرجــوع باملســمى وبــن البقــاء‬\n                                    ‫علــى العقــد ومطالبــة الغاصــب بأجــر املثــل»‪.‬‬\n                                                                 ‫‪ .3‬ال ضرر وال ضرار‪.‬‬\n                                                   ‫‪ .4‬املادة (‪ )55‬من نظام املرافعات‪.‬‬\n\n\n\n\n‫‪137‬‬\n\f‫ادعــت املدعيــة بدعــوى ضــد الشــركة املدعــى عليهــا بأنهــا اســتأجرت‬\n‫منهــا ســيارة بنظــام التأجيــر املنتهــي بالتمليــك وقامــت بتســديد بعــض‬\n‫األجــرة ثــم حصــل حــادث مــروري أديــن فيــه الطــرف املقابــل بالنســبة‬\n‫الكاملــة ولــم يقبــل املــرور مراجعتهــا فســلمت األوراق للشــركة املدعــى‬\n‫عليهــا فتفاجــأت موكلتــه بــإدراج اســمها يف القائمــة الســوداء (‪)000‬‬\n‫وقيامهــا ببيــع الســيارة علــى الغيــر عليــه فقــد طلبــت املدعيــة إلــزام‬\n‫الشــركة املدعــى عليهــا برفــع اســمها مــن القائمــة وتســليمها ســيارة‬\n‫جديــدة عوض ـ ًا عــن الســيارة التالفــه‪ ،‬أجــاب وكيــل الشــركة بصحــة‬\n‫العقــد واألقســاط املســددة وحصــول احلــادث والتبليــغ بــه يف وقتــه ووضــع‬\n‫موكلتــه علــى القائمــة الســوداء وبيــع الشــركة للســيارة محــل الدعــوى‬\n‫وأنــه ملــا أبلــغ باحلــادث مــن قبــل مديــر الشــرطة ذهــب للمــرور فأكــدوا‬\n‫وجــود رقــم احلــادث ولكــن األوراق مفقــودة ووعــد بالبحــث عنهــا‬\n‫وراجعهــم عــدة مــرات ولكــن لــم يجــدوا أوراق احلــادث وألن األقســاط‬\n‫تســتمر علــى املدعيــة فقــد ترتــب يف ذمتهــا مبالــغ متأخــرة فجــرى بيــع‬\n‫الســيارة لعــدم مراجعتهــا للشــركة ومطالبتهــا بالســيارة يف املــدة‬\n‫احملددة من قبل الشــركة‪ ،‬جرى ســؤاله ملاذا مت بيع الســيارة مع كون‬\n‫العقــد الزال ســاري ًا وهــل مت إبــاغ املدعيــة بذلــك فقــال تركنــا الســيارة‬\n‫مــده معينــة فلمــا لــم تــأت املســتأجرة باملطالبــة بهــا مت بيعهــا‪ ،‬أنكــر‬\n‫وكيــل املدعيــة عــدم مراجعتــه للشــركة وقــرر بأنــه كان يراجعهــم‬\n‫باالســتمرار حتــى أخبــر بــأن الســيارة بيعــت وطلــب فســخ العقــد‪ ،‬قــرر‬\n‫وكيــل املدعــي بأنــه يطلــب البــت يف موضــوع رفــع اســم موكلتــه مــن‬\n\n                                                                                    ‫‪138‬‬\n\f      ‫القائمــة الســوداء وأنــه يرغــب فصــل الدعــوى مبطالبــة بســيارة جديــدة‬\n      ‫عــن هــذه الدعــوى‪ ،‬عليــه وألن املدعــي ادعــى بكــون الشــركة املدعــى‬\n      ‫عليهــا قــد وضعــت اســم موكلتــه يف القائمــة الســوداء نظــرا لتأخرهــا‬\n      ‫يف ســداد بعــض أقســاط الســيارة املســتأجرة منهــم بســبب مــن قبــل‬\n      ‫الشــركة لعــدم متابعتهــم موضــوع احلــادث يف املــرور وقــد أقــر املدعــى‬\n      ‫عليــه وكالــة بــأن التخلــف عــن األقســاط كان بعــد احلــادث ولــم يكــن‬\n      ‫مــن قبــل املدعيــة أصالــة وإمنــا كان التأخــر يف متابعــة أوراق احلــادث‬\n      ‫كان مــن املــرور إذ فقــدت أوراق احلــادث مــن قبلهــم ولــم يتمكــن مــن‬\n      ‫متابعــة أوراق احلــادث ونظــرا لكــون األجــرة تســتحق علــى املســتأجر‬\n      ‫عنــد متكنــه مــن االنتفــاع فــإن تعــذر انتفاعــه بهــا مــن قبــل املؤجــر أو‬\n      ‫مــن قبــل طــرف أجنبــي فــا يســتحق املؤجــر أجــرة املــدة التــي تعــذر فيهــا‬\n      ‫االنتفــاع وألن العــن املســتأجرة (إذا غصبــت فللمســتأجر الفســخ ألن‬\n      ‫فيــه تأخيــر حقــه‪ ،‬فــإن فســخ فاحلكــم فيــه كمــا لــو انفســخ العقــد‬\n      ‫بتلــف العــن ســواء وإن لــم يفســخ حتــى انقضــت مــدة اإلجــارة ‪ ،‬فلــه‬\n      ‫اخليــار بــن الفســخ والرجــوع باملســمى وبــن البقــاء علــى العقــد ومطالبــة‬\n      ‫الغاصــب بأجــر املثــل) وقــد طالــب املســتأجر بالفســخ ومبــا أن املدعــى‬\n      ‫عليهــا قــد تعســفت يف اســتعمال حقهــا يف وضــع املدعيــة علــى القائمــة‬\n      ‫الســوداء ولــم يحصــل منهــا خلــل يف ســداد األقســاط يف وقتهــا وقــد‬\n      ‫جــاءت الشــريعة برفــع الضــرر عــن املتضرريــن ومــن القواعــد الفقهيــة‬\n      ‫الكبــرى (ال ضــرر وال ضــرار) ولــكل مــا ســبق فقــد صــدر حكــم علــى‬\n      ‫املدعــى عليهــا برفــع اســم املدعيــة مــن القائمــة الســوداء لــدى شــركة‬\n      ‫(‪ )...........‬وثبــت لديهــا إرجــاء املدعــي وكالــة مطالبتــه بســيارة جديــدة‬\n      ‫بديلــة مــن الســيارة التــي باعتهــا الشــركة املدعــى عليهــا وإقــراره بطلــب‬\n\n\n‫‪139‬‬\n\f‫فصلهــا عــن هــذه الدعــوى‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة باخلبــر املســاعد برقــم ‪ 33681073‬وتاريــخ ‪1433/11/28‬ه‬\n‫املقيــدة باحملكمــة برقــم ‪ 332138646‬وتاريــخ ‪1433/11/28‬ه ففــي‬\n‫يــوم االثنــن املوافــق ‪1434/02/04‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n‫‪ 09‬وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ )........‬بصفتــه وكيــا عــن املدعيــة (‪ ).....‬ســعودية اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ ).....‬بالوكالــة رقــم (‪ ).....‬يف ‪1433/11/28‬ه ـ‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة باخلبــر واملخــول لــه فيهــا املرافعــة‬\n‫واملدافعــة وســماع الدعــوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح‬\n‫والتنــازل واإلبــراء وطلــب اليمــن ورده واالمتنــاع عنــه وإحضــار البينــات‬\n‫وقبــول احلكــم واالعتــراض عليــه واســتالم املبالــغ والصكــوك ولــم‬\n‫حتضــر املدعــى عليهــا شــركة (‪ ).....‬وال مــن ميثلهــا شــرعا ولــم تردنــا‬\n‫إفــادة بتبليغهــم مــن عدمــه فبنــاء علــى املــادة (‪ )55‬مــن نظــام املرافعــات‬\n‫الشــرعية فقــد قــررت رفــع اجللســة لتبليــغ املدعى عليها ويف جلســة أخرى‬\n‫حضــر املدعــي وكالــة (‪ ).....‬املثبتــة هويتــه ووكالتــه ســابق ًا ولــم حتضــر‬\n‫املدعــى عليهــا شــركة (‪ ).....‬وال مــن ميثلهــا شــرع ًا وقــد كتــب خطــاب‬\n‫لتبليغهــا برقــم ‪ 34318839‬يف ‪1434/2/9‬ه ـ وأفــاد محضــر اخلصــوم‬\n‫بأنــه مت تبليــغ املدعــى عليهــا بتوقيــع الوكيــل الشــرعي للشــركة (‪).....‬‬\n‫فبنــاء علــى املــادة (‪ )55‬مــن نظــام املرافعــات الشــرعية فقــد قــررت ســماع‬\n\n                                                                                     ‫‪140‬‬\n\f      ‫ا يف دعــواه إن موكلتــي‬    ‫الدعــوى غيابي ـ ًا فادعــى املدعــي وكالــة قائ ـ ً‬\n      ‫قــد اســتأجرت مــن الشــركة املدعــى عليهــا ســيارة (‪2008 ).....‬م رقــم‬\n      ‫اللوحــة (‪ ).....‬بنظــام اإليجــار املنتهــي بالتمليــك يف ‪1428/11/8‬ه ـ مببلــغ‬\n      ‫‪93960‬ريــال مقســطة علــى ‪ 60‬قســط ًا شــهري ًا قــدر القســط الواحــد‬\n      ‫‪1566‬ريــال اعتبــار ًا مــن ‪2008/1/1‬م علمـ ًا أن فيــه دفعــة مقدمــة قدرهــا‬\n      ‫(‪6500‬ريــال) وقــد مت تســديد املبلــغ املقــدم وبعــض األقســاط وبلــغ مقدار‬\n      ‫مــا ســدد ‪14000‬ريــال ثــم حصــل علــى الســيارة حــادث مــروري يف شــهر‬\n      ‫صفــر مــن عــام ‪1429‬ه ـ يف مدينــة اجلبيل الصناعية وكان يقود الســيارة‬\n      ‫(‪ ).....‬أخــو موكلتــي وقــد كانــت نســبة اإلدانــة يف احلــادث ‪ %100‬علــى‬\n      ‫الطــرف املقابــل وقــد باشــر مــرور اجلبيــل هــذا احلــادث وراجعتهــم عــدة‬\n      ‫مــرات فأفهمونــي بــأن الســيارة مســجلة باســم الشــركة وأنهــا هــي التــي‬\n      ‫تتابــع املوضــوع فتركــت املتابعــة وســلمتهم كامــل األوراق علمــا أنــه مت‬\n      ‫إبالغهــم باحلــادث مــن حــن حصولــه ثــم تفاجــأت موكلتــي بعــد ذلــك‬\n      ‫بكــون الســيارة قــد بيعــت علــى طــرف ثالــث بغيــر علمهــا كمــا تفاجأت‬\n      ‫بوضــع اســمها علــى القائمــة الســوداء وقــد راجعــت الشــركة فأفهمونــي‬\n      ‫بأننــي ال بــد أن أســدد كامــل قيمــة الســيارة وهــم قــد باعــوا الســيارة‬\n      ‫فأفهمتهــم بــأن الســيارة حصــل عليهــا حــادث وأن الشــركة باعتهــا بغيــر‬\n      ‫علــم موكلتــي فقالــوا ســدد النصــف إذن فرفضــت ذلــك وكل موظــف‬\n      ‫يتنصــل مــن املســؤولية فأطلــب إلزامهــم باآلتــي أوال رفــع اســم موكلتــي‬\n      ‫مــن القائمــة الســوداء ثاني ـ ًا إلزامهــم بإبــدال موكلتــي بســيارة جديــدة‬\n      ‫عوض ـ ًا عــن الســيارة التــي باعوهــا بغيــر علمهــا هكــذا ادعــى فطلبــت‬\n      ‫منــه البينــة علــى دعــواه فأبــرز العقــد الــذي بــن موكلتــه وبــن الشــركة‬\n      ‫املدعــى عليهــا وهــو مطابــق ملــا ذكــر بعاليــه كمــا جــرى ســؤاله هــل‬\n\n\n‫‪141‬‬\n\f‫لديــه مــا يثبــت وقــوع احلــادث ونســبة اإلدانــة فقــال ليــس لــدي شــيء‬\n‫مــن ذلــك وكامــل األوراق لــدى مــرور محافظــة اجلبيــل هكــذا أجــاب‬\n‫ونظــرا لضــرورة التثبــت مــن هــذا األمــر فقــد قــررت الكتابــة إلــى مــرور‬\n‫محافظــة اجلبيــل لطلــب اإلفــادة عــن احلــادث املذكــور ويف جلســة أخــرى‬\n‫حضــر املدعــي وكالــة املثبتــة هويتــه ووكالتــه مســبقا وحضــر معــه‬\n‫املدعــى عليــه (‪ ).....‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ ).....‬وكيــا‬\n‫عــن (‪ ).....‬بصفتــه شــريكا بشــركة (‪ ).....‬مبوجــب الســجل التجــاري‬\n‫رقــم (‪ ).....‬يف ‪1417/07/06‬ه مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل اخلبــر برقــم ‪ 37631‬يف ‪1432/11/20‬ه ـ واملخــول لــه فيهــا إقامــة‬\n‫الدعــوى واملرافعــة واملدافعــة وقبــول االحــكام واالعتــراض واالســتئناف‬\n‫واإلبــراء وكانــت اجللســة الســابقة قــد رفعــت ألجــل الكتابــة إلــى مــرور‬\n‫محافظــة اجلبيــل ألجــل االستفســار عــن احلــادث ولــم تتــم مخاطبتهــم‬\n‫لكــون املوظــف املختــص نســي ذلــك وقــد جــرى عــرض الدعــوى علــى‬\n‫املدعــى عليــه وكالــة فأجــاب قائــا ‪ :‬مــا ذكــره املدعــي وكالــة يف‬\n‫دعــواه مــن حصــول العقــد واألقســاط املســددة وحصــول احلــادث وتبليغنــا‬\n‫باحلــادث يف وقتــه ووضــع موكلتــه علــى القائمــة الســوداء وبيــع الشــركة‬\n‫للســيارة محــل الدعــوى فهــو صحيــح علمــا أننــي شــخصي ًا ملــا أبلغــت‬\n‫مــن قبــل مديــر الشــرطة باحلــادث ذهبــت إلــى مــرور محافظــة اجلبيــل‬\n‫فأكــد لــي وجــود رقــم احلــادث ولكــن األوراق مفقــودة ووعــد بالبحــث‬\n‫عنهــا وراجعتــه عــدة مــرات ولكــن لــم يجــدوا أوراق احلــادث ومبــا أن‬\n‫األقســاط تســتمر علــى املدعيــة فقــد ترتــب يف ذمتهــا مبالــغ متأخــرة ثــم‬\n‫مت بيــع الســيارة لعــدم مراجعتهــم للشــركة ومطالبتهــم بالســيارة يف‬\n‫املــدة احملــددة مــن قبــل الشــركة هكــذا أجــاب فجــرى ســؤاله ملــاذا‬\n\n\n                                                                                   ‫‪142‬‬\n\f      ‫مت وضــع اســم املدعيــة يف القائمــة الســوداء مــع علــم الشــركة بكــون‬\n      ‫الســبب يف التأخيــر يف ســداد األقســاط خارجــا عــن إرادتهــا فقــال لــو‬\n      ‫تركناهــا لتســبب لنــا باخلســارة هكــذا أجــاب فجــرى ســؤاله ملــاذا مت‬\n      ‫بيــع الســيارة مــع كــون العقــد الزال ســاري ًا وهــل مت إبــاغ املدعيــة بذلــك‬\n      ‫فقــال تركنــا الســيارة مــده معينــة فلمــا لــم تــأت املســتأجرة باملطالبــة‬\n      ‫بهــا مت بيعهــا هكــذا أجــاب وبعرضــه علــى املدعــي وكالــة أجــاب قائــا‬\n      ‫بــل كنــت أراجــع الشــركة بــن احلــن وآخــر للســؤال عــن احلــادث حتــى‬\n      ‫مت إبالغــي أخيــرا بأنــه مت بيــع الســيارة ثــم وضــع اســم موكلتــي يف‬\n      ‫القائمــة الســوداء وأطلــب فســخ العقــد بيننــا وإلغــاء وضــع اســم موكلتــي‬\n      ‫مــن القائمــة الســوداء هكــذا أجــاب وبعرضــه علــى املدعــى عليــه‬\n      ‫وكالــة أجــاب قائــا إن موكلتــي ترفــض ذلــك حتــى تســدد الباقــي مــن‬\n      ‫املديونيــة وقدرهــا خمســة وأربعــون ألــف ريــال تقريبــا فجــرى ســؤاله هــل‬\n      ‫كانــت املدعيــة ملتزمــة بســداد األقســاط قبــل حلــول احلــادث فقــال ال‬\n      ‫أعلــم وأحتــاج الرجــوع إلــى حســابات الشــركة هكــذا أجــاب ثــم قــرر‬\n      ‫املدعــي وكالــة قائــا أطلــب البــت يف موضــوع رفــع اســم موكلتــي مــن‬\n      ‫القائمــة الســوداء وأقــرر بأننــي أرغــب فصــل الدعــوى مبطالبــة بســيارة‬\n      ‫جديــدة عــن هــذه الدعــوى وســأقدم بهــا دعــوى مســتقلة بــإذن اهلل‬\n      ‫هكــذا أجــاب فبنــاء علــى مــا تقــدم وبعــد ســماع الدعــوى واإلجابــة ومبــا‬\n      ‫أن املدعــي ادعــى بكــون الشــركة املدعــى عليهــا قــد وضعــت اســم‬\n      ‫موكلتــه يف القائمــة الســوداء نظــرا لتأخرهــا يف ســداد بعــض أقســاط‬\n      ‫الســيارة املســتأجرة منهم واملذكورة بياناتها يف اجللســة املاضية وكان‬\n      ‫التخلــف بعــد حصــول احلــادث الــذي لــم تتمكــن موكلتــه مــن االســتفادة‬\n      ‫مــن الســيارة بســبب مــن قبــل الشــركة لعــدم متابعتهــم موضــوع احلــادث‬\n\n\n‫‪143‬‬\n\f‫يف املــرور وقــد أقــر املدعــى عليــه وكالــة بــأن التخلــف عــن األقســاط‬\n‫كان بعــد احلــادث ولــم يكــن مــن قبــل املدعيــة أصالة وإمنــا كان التأخر‬\n‫يف متابعــة أوراق احلــادث كان مــن املــرور إذ فقــدت أوراق احلــادث مــن‬\n‫قبلهــم وملتمكــن متابعــة أوراق احلــادث ونظــرا لكــون األجــرة تســتحق‬\n‫علــى املســتأجر عنــد متكنــه مــن االنتفــاع فــإن تعــذر انتفاعــه بهــا مــن‬\n‫قبــل املؤجــر أو مــن قبــل طــرف أجنبــي فــا يســتحق املؤجــر أجــرة املــدة‬\n‫التــي تعــذر فيهــا االنتفــاع قــال اخلرقــي رحمــه اهلل‪( :‬فــإن جــاء أمــر غالــب‬\n‫يحجــز املســتأجر عــن منفعــة مــا وقــع عليــه العقــد؟ لزمــه مــن األجــر‬\n‫مبقــدار مــدة انتفاعــه) وذكــر املوفــق رحمــه اهلل يف املغنــي تقســيمات‬\n‫لهــذه املســألة وينطبــق علــى هــذه القضيــة مــا إذا حصــل التعــذر بســبب‬\n‫غصــب العــن املؤجــرة حيــث إن فقــدان أوراق احلــادث وعــدم التمكــن‬\n‫مــن االنتفــاع بهــا إال بهــذه األوراق يعتبــر يف حكــم غصــب األجنبــي لهــذه‬\n‫العــن وقــد ذكــر املوفــق رحمــه اهلل يف املغنــي أن العــن املســتأجرة (إذا‬\n‫غصبــت فللمســتأجر الفســخ ألن فيــه تأخيــر حقــه؟ فــإن فســخ فاحلكــم‬\n‫فيــه كمــا لــو انفســخ العقــد بتلــف العــن ســواء وإن لــم يفســخ حتــى‬\n‫انقضــت مــدة اإلجــارة؟ فلــه اخليــار بــن الفســخ والرجــوع باملســمى وبــن‬\n‫البقــاء علــى العقــد ومطالبــة الغاصــب بأجــر املثــل) وقــد طالــب املســتأجر‬\n‫بالفســخ وحيــث لــم يدفــع أجــرة للمــدة التــي تعــذر فيهــا االنتفــاع ومبــا أن‬\n‫املدعــى عليهــا قــد تعســفت يف اســتعمال حقهــا يف وضــع املدعيــة علــى‬\n‫القائمــة الســوداء ولــم يحصــل منهــا خلــل يف ســداد األقســاط يف وقتهــا‬\n‫وقــد جــاءت الشــريعة بجلــب املصالــح وتكميلهــا ودفــع املفاســد وتقليلهــا‬\n‫وجــاءت برفــع الضــرر عــن املتضرريــن ومــن القواعــد الفقهيــة الكبــرى‬\n‫(ال ضرر وال ضرار) ولكل ما ســبق فقد ألزمت املدعى عليها شــركة‬\n\n\n                                                                                        ‫‪144‬‬\n\f      ‫(‪ ).....‬برفــع اســم املدعيــة (‪ ).....‬مــن القائمــة الســوداء لــدى شــركة (‪).....‬‬\n      ‫وثبــت لــدي إرجــاء املدعــي وكالــة ملطالبتــه بســيارة جديــدة بديلــة مــن‬\n      ‫الســيارة التــي باعتهــا الشــركة املدعــى عليهــا وإقــراره بطلــب فصلهــا‬\n      ‫عــن هــذه الدعــوى وبــه حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي‬\n      ‫وكالــة قناعتــه باحلكــم وقــرر املدعــى عليــه عــدم قناعتــه باحلكــم‬\n      ‫وطلــب رفــع املعاملــة حملكمــة االســتئناف بالئحــة اعتراضيــة وأفهــم‬\n      ‫مبقتضــى تعليمــات االســتئناف وبــاهلل التوفيــق حــرر يف ‪1434/6/13‬ه‬\n                                               ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده أمــا بعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بخطــاب رئيســها رقــم ‪ 342186558‬يف ‪1434/12/16‬ه ـ وقــد ظهــر‬\n      ‫علــى الصــك مــن قبــل الدائــرة احلقوقيــة الثانيــة يف محكمــة االســتئناف‬\n      ‫مبــا نصــه‪( :‬احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم‬\n      ‫‪ 34240533‬وتاريخ ‪1434/6/13‬هـ الصادر من فضيلة القاضي الشيخ‬\n      ‫(‪ ).....‬وأصدرنــا القــرار رقــم ‪/34377281‬ق‪/2‬أ وتاريــخ ‪1434/12/3‬ه ـ‬\n      ‫املتضمــن املصادقــة علــى احلكــم قاضــي اســتئناف (‪ ).....‬قاضــي‬\n      ‫اســتئناف (‪ ).....‬رئيــس الدائــرة (‪ ).....‬أختامهــم وتوقيعاتهــم) انتهــى نصــه‬\n      ‫وبــاهلل التوفيــق حــرر يف ‪1434/12/25‬ه ـ وصلــى اهلل وســلم علــى نبينــا‬\n                                                                                    ‫محمــد‪.‬‬\n      ‫احلمــد هلل وحــده أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقية‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪ 342186558‬وتاريــخ ‪1434/9/15‬ه ـ الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة اخلبــر املســاعد برقــم‬\n      ‫‪ 332138646‬وتاريــخ ‪1434/9/7‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n\n\n‫‪145‬‬\n\f‫فضيلــة القاضــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم ‪34240533‬‬\n‫وتاريــخ ‪1434/6/13‬ه ـ اخلــاص بدعــوى (‪ ).....‬ضــد (‪ ).....‬يف قضيــة‬\n‫حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/12/3‬ه ـ ‪.‬‬\n\n\n\n\n                                                                               ‫‪146‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":137,"source_page_end":146,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1832740e295ef7842a7b9eb9341b2944f221b8eb9100375770350b096ff16d39","normalized_text_hash":"8515d5ddc29301a7d600879f9905ede5f3ad6ccb514892b4c7067bb09be725b8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p137-34240533"},{"id":"e0249bdc-3819-507e-ac81-37d528ed992b","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة املؤجر بإصاح التلفيات ودفع األجرة -دفع املدعى عليه بأن التلفيات استهالكية ليست بتفريط وأنه أخلى العن- تقرير هيئة النظر -قرار أهل اخلبرة بأن التلفيات بتفريط وجود أعمال أحدثها عليه إزالتها -تضمن املدعي عليه التلفيات وإزالة ما أحدثه وإخاء العن قبل نهاية العام ودفع أجرته .","document_number":"34302116","case_number":"33683430","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/22","year":"1434","subject":"إجارة -مطالبة املؤجر بإصاح التلفيات ودفع األجرة -دفع املدعى عليه بأن التلفيات استهالكية ليست بتفريط وأنه أخلى العن- تقرير هيئة النظر -قرار أهل اخلبرة بأن التلفيات بتفريط وجود أعمال أحدثها عليه إزالتها -تضمن املدعي عليه التلفيات وإزالة ما أحدثه وإخاء العن قبل نهاية العام ودفع أجرته .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/22 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34302116 :‬‬\n                         ‫َر ْق ُم الدعوى‪33683430 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34349104‬تاريخه‪1434/11/4 :‬هـ‬\n\n\n      ‫إجــارة‪ -‬مطالبــة املؤجــر بإصــاح التلفيــات ودفــع األجــرة‪ -‬دفــع املدعــى‬\n      ‫عليــه بــأن التلفيــات اســتهالكية ليســت بتفريــط وأنــه أخلــى العــن‪-‬‬\n      ‫تقريــر هيئــة النظــر‪ -‬قــرار أهــل اخلبــرة بــأن التلفيــات بتفريــط وجــود‬\n      ‫أعمــال أحدثهــا عليــه إزالتهــا‪ -‬تضمــن املدعــي عليــه التلفيــات وإزالــة‬\n                     ‫مــا أحدثــه وإخــاء العــن قبــل نهايــة العــام ودفــع أجرتــه ‪.‬‬\n\n\n\n\n      ‫‪ .1‬املســتأجر إذا فــرط أو تعــدى يف العــن املســتأجرة ضمــن‪ .‬ينظــر‬\n                                                     ‫كشــاف القنــاع ‪.139/9‬‬\n      ‫‪ .2‬مــا كان مــن عمــارة العــن املؤجــرة ليــس الزمــا للمســتأجر‪ .‬ينظــر‬\n                                                      ‫كشــاف القنــاع ‪.109/9‬‬\n\n\n\n\n      ‫تقــدم املدعــي بدعــوى ضــد الشــركة املدعــى عليهــا بأنــه أجرهــا عقــارا‬\n      ‫ملــدة خمــس ســنوات تبــدأ يف ‪1430/9/1‬ه ـ وتنتهــي يف ‪1435/8/30‬ه ـ‬\n      ‫بثمانــن ألــف ريــال للســنة األولــى وثمانيــة وثمانــن ألــف ريــال للســنة‬\n      ‫الثانيــة وســتة تســعني ألفــا وثمامنائــة ريــال للســنة الثالثــة ومائــة وســتة‬\n      ‫آالف وأربعمائــة وثمانــن ريــاال للســنة الرابعــة ومائــة وســبعة عشــر ألفــا‬\n      ‫ومائــة وأربعــة وســتني ريــاال للســنة اخلامســة علــى أن تســلم األجــرة يف‬\n\n‫‪147‬‬\n\f‫بدايــة شــهر رمضــان مــن كل ســنة إيجاريــه وأنــه اســتلم أجــرة الســنني‬\n‫الثــاث األول ثــم بتاريــخ ‪1433/7/28‬ه ـ وردت رســالة مــن املدعــى عليها‬\n‫ترغــب فيهــا بفســخ العقــد وأنهــا ستســلم العقــار لــه يف ‪1433/9/1‬ه ـ‬\n‫وقــد رد عليهــم بأنــه إذا ســلمت الشــركة العقــار ســليما نظيفــا كمــا مت‬\n‫تســليمه لهــا بــدون تلفيــات وال تعديــات فإنــه موافــق علــى ذلــك فطلبــت‬\n‫الشــركة منــه احلضــور لالطــاع علــى البيــت وبيــان مــا فيــه مــن تلفيــات‬\n‫فشــاهد تلفيــات كبيــرة يف العقــار تســببت فيهــا الشــركة وأبلغهــا انــه‬\n‫لــن يســتلم العقــار وال يوافــق علــى فســخ العقــد وأنــه يطالــب الشــركة‬\n‫بأجــرة هــذا العــام وإصــاح تلفيــات العقــار قبــل اســتالمه فطلبــت‬\n‫الشــركة منــه بيــان تكلفــة إصــاح العقــار فأحضــر املختصــن وتبــن‬\n‫أن اإلصــاح يكلــف خمســة وســتني ألــف ريــال وطلــب منهــم موكلــي‬\n‫دفــع هــذا املبلــغ فرفضــت الشــركة لــذا فيطلــب إلــزام املدعــى عليــه‬\n‫بدفــع أجــرة الســنة اجلاريــة التــي بــدأت يف ‪1433/9/1‬ه ـ مئــة وســتة آالف‬\n‫وأربعمئــة وثمانــن ريــال وتكلفــة إصــاح العقــار للتلفيــات التــي تســببت‬\n‫فيهــا الشــركة خمســة وســتني ألــف ريــال‪ ،‬أقــر وكيــل املدعــى عليهــا‬\n‫بالعقــد والثمــن إال أنــه دفــع بــأن العقــد تضمــن بــأن ملوكلتــه فســخ العقد‬\n‫متــى شــاءت علــى أن تدفــع أجــرة الســنة التــي جــرى فســخ العقــد خاللهــا‬\n‫كاملــة وأن موكلتــه لــم تتــرك تلفيــات وإن مــا يطالــب بــه مجــرد أعيــان‬\n‫اســتهالكية جــرت العــادة تلفهــا مبضــي املــدة وأعمــال جبــس وفواصــل‬\n‫عملــت برضــاه وطوعــه واختيــاره وأنهــا ســلمت العقــار لــه لــذا فتطلــب‬\n‫رد دعــواه‪ ،‬جــرى الكتابــة لهيئــة النظــر فعــادت اإلفــادة بأنهــا تــرى مــا‬\n‫يلــي‪ :‬أوال‪ /‬إزالــة الفواصــل الصناعيــة لعــدم توافقهــا ألصــول الصنعــة‬\n‫مــن جهــة عــدم مالئمتهــا ملــا هــي فيــه‪ .‬ثانيــا‪ :‬إزالــة البــاب املوضــوع بالــدور‬\n\n\n                                                                                            ‫‪148‬‬\n\f      ‫العلــوي وبنــاء اجلــدار املهــدوم بالــدور األول وإعــادة تأهيلــه حســب أصــول‬\n      ‫الصنعــة وتقديــر ذلــك ألفــان وثالثمئــة ريال ‪ .‬ثالثــا‪ /‬تركيب درفة املنيوم‬\n      ‫ويقــدر ذلــك بخمســمائة ريــال‪ .‬رابعــا‪ /‬تركيــب األدوات التالفــة وتقديــر‬\n      ‫ذلــك ثالثــة آالف وأربعمائــة ريــال‪ .‬خامســا‪ /‬تســليم مفاتيــح األبــواب‬\n      ‫أو تغيــر القلــوب وتقديــر ذلــك مائتــان وخمســن ريــال‪ .‬سادســا‪/‬عمل‬\n      ‫نظافــة للموقــع مــع ترويــب مواضــع التنديــة يف دورات امليــاه ويقــدر ذلــك‬\n      ‫بخمســمائة ريــال‪ .‬ســابعا ‪ /‬تعــذر اختبــار عمــل املكيفــات ومضخــات‬\n      ‫امليــاه لعــدم وجــود كهربــاء باملوقــع هــذا مــا جــرى تقديــره ‪.‬إ‪.‬ه ـ ثــم جــرى‬\n      ‫إعــادة املعاملــة لهيئــة النظــر لإلفــادة عــن التلفيــات املوجــودة يف العقــار‬\n      ‫وهــل هــي طبيعيــة أم نتيجــة تعــد أو تفريــط مــن املســتأجر وحصرهــا‬\n      ‫مفصــا وكذلــك حصــر أدوات احلمــام املفقــودة مفصــا وتقديرهــا‪،‬‬\n      ‫عــادت اإلفــادة باإلشــارة للتلفيــات وبعــض القطــع املنزوعــة واإلشــارة‬\n      ‫لســعرها التالفــة وأنهــا نتيجــة اإلهمــال‪ ،‬عليــه وبعــد االطــاع علــى العقــد‬\n      ‫بــن الطرفــن والن الفقــرة الثالثــة مــن العقــد نصــت علــى أنــه ال يحــق‬\n      ‫للطــرف الثانــي إضافــة أو تغييــر معالــم العــن املؤجــرة مــن دهانــات أو‬\n      ‫أعمــال ديكــور إال بعــد موافقــة الطــرف األول ‪ ،‬كمــا يتحمــل الطــرف‬\n      ‫الثانــي جميــع أعمــال الصيانــة مــع مراعــاة احتســاب اإلســتهالك‬\n      ‫الطبيعــي للمبنــى و محتوياتــه عنــد نهايــة العقــد ‪ ،‬وقــد وافــق الطــرف‬\n      ‫األول علــى الســماح للطــرف الثانــي بعمــل فواصــل جيبســون بــورد أو‬\n      ‫خشــبية لتقســيم املســاحات الكبيــرة بالبيــت حتــى ميكــن اســتخدامها‬\n      ‫وعلــى حســاب الطــرف الثانــي ‪ ،‬كمــا أن الفقــرة اخلامســة مــن العقــد‬\n      ‫نصــت علــى أنــه يف حالــة رغبــة الطــرف الثانــي بإخــاء املــكان املؤجــر‬\n      ‫عليــه إبــاغ الطــرف األول قبــل انتهــاء مــدة العقــد بشــهر علــى األقــل ‪،‬‬\n\n\n‫‪149‬‬\n\f‫ويف حــال رغــب يف إخــاء العقــار قبــل نهايــة املــدة يلتــزم الطــرف الثانــي‬\n‫بســداد كامــل اإليجــار للســنة اإليجاريــة التــي يرغــب اإلخــاء خاللهــا‪،‬‬\n‫وألن املدعــى عليــه قــام بأعمــال يف العــن املســتأجرة بــدون إذن املدعــي‬\n‫أصالــة كمــا أن األعمــال التــي اســتأذن فيهــا لــم يقــم بعملهــا وفــق أصــول‬\n‫الصنعــة كمــا أنــه حينمــا رغــب إنهــاء العقــد لــم يقــم بإصــاح مــا أتلفــه‬\n‫أو قــام بتغييــره أو مــا فقــد منــه قبــل الوقــت احملــدد وهــو ‪1433/9/1‬ه ـ‬\n‫وألن املدعــي أصالــة حينمــا امتنــع مــن اســتالم العــن حتــى يتــم اصالحهــا‬\n‫ودفــع تكلفــة اإلصــاح فــإن تصرفــه صحيحــا ألن ذلــك يحتــاج إلــى وقت‬\n‫وثمــن وهــو نتيجــة تعــدي أو تفريــط مــن املســتأجر واملســتأجر إذا فــرط‬\n‫أو تعــدى يف العــن املســتأجرة ضمــن ينظــر كشــاف القنــاع ‪،139/9‬‬\n‫وألن ممــا قررتــه هيئــة النظــر هــو عمــل نظافــة للموقــع وترويــب مواضــع‬\n‫التنديــة يف دورات امليــاه مببلــغ خمســمائة ريــال وألن هــذا مــن عمــارة‬\n‫العــن املؤجــرة وليــس الزمــا للمســتأجر ينظــر كشــاف القنــاع ‪،109/9‬‬\n‫لذلــك كلــه فقــد حكمــت الدائــرة علــى املدعــى عليــه أصالــة بــأن يدفع‬\n‫للمدعــي مــا يلــي‪ :‬أوال ‪ /‬تكلفــة اإلصالحــات واملفقــودات يف املبنــى التي‬\n‫قدرتهــا هيئــة النظــر فيمــا عــدا تنظيــف املوقــع وترويــب مواقــع التنديــة‬\n‫يف دورات امليــاه‪ .‬ثانيــا ‪ /‬أجــرة املــدة التــي بــدأت يف ‪1433/9/1‬هــ‪ .‬ثالثا‪/‬‬\n‫دفــع اســتهالك املــاء والكهربــاء حتــى ‪1434/8/30‬ه ـ رابعــا ‪ /‬إلــزام‬\n‫املدعــى عليــه أصالــة بإخــاء املبنــى يف مــدة أقصاهــا ‪1434/9/1‬ه ـ‬\n‫وتســليمه للمدعــي أصالــة خاليــا مــن الشــواغل ‪-‬بعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــي وكالــة القناعــة وقــرر املدعــى عليــه وكالــة عــدم‬\n‫القناعــة وطلــب رفعــه حملكمــة االســتئناف فأفهــم بالتعليمــات‪ -‬صــدق‬\n                                             ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n                                                                                     ‫‪150‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪... .................‬القاضــي يف احملكمــة‬\n      ‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33683430‬وتاريــخ‬\n      ‫‪1433/11/30‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332150769‬وتاريــخ‬\n      ‫‪1433/11/30‬هـ حضر ‪.................‬بالســجل املدني رقم ‪1001974151‬‬\n      ‫بوكالتــه عــن أبيــه ‪.................................‬بالوكالــة الصــادرة مــن‬\n      ‫كتابــة العــدل الثانيــة مبكــة برقــم ‪ 35244/5049‬يف ‪1432/12/23‬هـ‬\n      ‫والتــي تخولــه إقامــة وســماع الدعــاوى واملرافعــة واملدافعــة واإلقــرار‬\n      ‫والصلــح والتنــازل والتأجيــر واســتالم األجــرة ‪..‬الــخ وادعــى علــى‬\n      ‫احلاضــر معــه ‪ .........................‬بالســجل املدنــي رقــم ‪1008486803‬‬\n      ‫بوكالتــه عــن ‪ ...........................‬بصفتــه رئيــس مجلــس املديريــن‬\n      ‫لشــركة ‪ ..........................‬بالســجل التجــاري رقــم ‪ ........................‬يف‬\n      ‫‪1411/8/9‬ه ـ وذلــك بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n      ‫مبكــة برقــم ‪ 20724/4566‬يف ‪1431/6/25‬ه ـ والتــي تخولــه إقامــة‬\n      ‫وســماع عمــوم الدعــاوى واملرافعــة واملدافعــة ‪..‬الــخ قائــا يف دعــواه‬\n      ‫عليــه لقــد أجــر موكلــي والــدي علــى شــركة ‪ ...........................‬العقــار‬\n      ‫الواقــع مبكــة حــي الهجــرة ملــدة خمــس ســنني بــدأت يف ‪1430/9/1‬ه ـ‬\n      ‫وتنتهــي يف ‪1435/8/30‬ه ـ بأجــرة ســنوية ثمانــن ألــف ريــال للســنة‬\n      ‫األولــى وثمانيــة وثمانــن ألــف ريــال للســنة الثانيــة وســتة تســعني ألفــا‬\n      ‫وثمامنائــة ريــال للســنة الثالثــة ومائــة وســتة آالف وأربعمائــة وثمانــن‬\n      ‫ريــاال للســنة الرابعــة ومائــة وســبعة عشــر ألفــا ومائــة وأربعــة وســتني‬\n\n‫‪151‬‬\n\f‫ريــاال للســنة اخلامســة علــى أن تســلم األجــرة يف بدايــة شــهر رمضــان مــن‬\n‫كل ســنة إيجاريــه وقــد اســتلم موكلــي أجــرة الســنني الثــاث األولــى‬\n‫ثــم بتاريــخ ‪1433/7/28‬ه ـ وردتنــا رســالة مــن املدعــى عليــه يذكــر‬\n‫أن الشــركة ترغــب يف فســخ العقــد وال ترغــب االســتمرار فيــه وأنهــا‬\n‫ستســلم العقــار ملوكلــي يف ‪1433/9/1‬ه ـ وقــد رد موكلــي عليهــم‬\n‫بأنــه إذا ســلمت الشــركة العقــار ســليما نظيفــا كمــا مت تســليمه لهــا‬\n‫بــدون تلفيــات وال تعديــات فــإن موكلــي موافــق علــى ذلــك فطلبــت‬\n‫الشــركة مــن موكلــي احلضــور لالطــاع علــى البيــت وبيــان مــا فيــه‬\n‫مــن تلفيــات فحضــر موكلــي إلــى العقــار وشــاهد تلفيــات كبيــرة يف‬\n‫العقــار تســببت فيهــا الشــركة وأبلــغ الشــركة انــه لــن يســتلم العقــار‬\n‫وال يوافــق علــى فســخ العقــد وأنــه يطالــب الشــركة بأجــرة هــذا العــام‬\n‫وإصــاح تلفيــات العقــار قبــل اســتالمه فطلبــت الشــركة مــن موكلــي‬\n‫بيــان تكلفــة إصــاح العقــار فأحضــر موكلــي املختصــن وتبــن أن‬\n‫اإلصــاح يكلــف خمســة وســتني ألــف ريــال وطلــب منهــم موكلــي دفــع‬\n‫هــذا املبلــغ فرفضــت الشــركة ذلــك فأطلــب إلــزام املدعــى عليــه بدفــع‬\n‫أجــرة هــذا الســنة التــي بــدأت يف ‪1433/9/1‬ه ـ مبلــغ وقــدره مائــة وســتة‬\n‫آالف وأربعمائــة وثمانــون ريــاال وتكلفــة إصــاح العقــار للتلفيــات التــي‬\n‫تســببت فيهــا الشــركة مبلــغ وقــدره خمســة وســتون ألــف ريــال هــذه‬\n‫دعــواي وبســؤال املدعــي وكالــة عــن دعــوى املدعــي أبــرز إجابتــه بورقــة‬\n‫هــذا نصهــا نوجــز ردنــا علــى الئحــة الدعــوى املقدمــة مــن املدعــي ونقســم‬\n‫ردنــا علــى شــقني األول مــا يتعلــق بحــق املدعــى عليــه بفســخ العقــد قبــل‬\n‫انتهــاء أجلــه ومدتــه العقــد شــريعة املتعاقديــن واملســلمون علــى شــروطهم‬\n‫فعقــد اإليجــار أعطــي للمدعــى عليهــا موكلتــي حــق فســخ العقــد قبــل‬\n\n\n                                                                                    ‫‪152‬‬\n\f      ‫انتهــاء مدتــه شــريطة أن يتــم ســداد اإليجــار للســنة اإليجاريــة التــي‬\n      ‫ينفســخ فيهــا العقــد وذلــك بالبنــد سادســا مــن العقــد صفحــة رقــم (‬\n      ‫‪ )2‬والتــي تنــص علــى ( يف حالــة رغبــة الطــرف الثانيــة بإخــاء املــكان‬\n      ‫املؤجــر عليــه إبــاغ الطــرف األول قبــل انتهــاء مــدة العقــد بشــهر علــى‬\n      ‫األقــل ويف حــال رغــب يف إخــاء العقــار قبــل نهايــة املــدة يلتــزم الطــرف‬\n      ‫الثانــي بســداد كامــل اإليجــار للســنة اإليجاريــة التــي يرغــب اإلخــاء‬\n      ‫خاللهــا ) وبالفعــل فقــد ســددت املدعــى عليهــا األجــرة كاملــة للســنة‬\n      ‫التــي مت الفســخ خاللهــا وهــو مــا أقــر بــه املدعــي يف الئحــة دعــواه حيــث‬\n      ‫اقــر بســدادنا األجــرة لــه واســتالمه إياهــا وكذلــك اقــر بإخطــار املدعــى‬\n      ‫عليهــا لــه بفســخ العقــد حيــث أن العقــد بالبنــد اخلامــس أعطــي للمدعــى‬\n      ‫عليهــا حــق الفســخ شــريطة اإلخطــار املســبق قبــل نهايــة الســنة االيجاريــة‬\n      ‫مبــدة شــهر وهــو مــا اقــر بــه املدعــي يف الئحــة دعــواه يف أنــه تســلم‬\n      ‫اإلخطــار يف ‪1433/7/28‬ه ــومن هنــا يتضــح أن املدعــى عليهــا مــن حقها‬\n      ‫فســخ العقــد وإنهــاؤه قبــل حلــول اجــل العقــد ويتضــح أيضــا أن املدعــى‬\n      ‫عليهــا قــد أوفــت بكامــل التزامهــا مــع املدعــي وبالتالــي فليــس للمدعــي‬\n      ‫وجــه حــق فيمــا يطالــب بــه مــن ســداد أجــرة عــن ســنة إيجاريــة جديــدة‬\n      ‫أو ســداد األجــرة لســنوات العقــد املتبقيــة ألن العقــد شــريعة املتعاقديــن‬\n      ‫واملســلمون علــى شــروطهم ‪ .‬ثانيــا فيمــا يتعلــق بطلــب املدعــي إصــاح‬\n      ‫العــن املؤجــرة بــادي ذي بــدء أشــير إلــى أن العقــار موضــوع الدعــوى وهــو‬\n      ‫مــا اســماه املدعــي فيــا هــو يف احلقيقــة منزل مكون مــن طابقني وغرف‬\n      ‫ملحقــة للحــارس وتاريــخ بنــاؤه يعــود إلــى أكثــر مــن خمــس وعشــرون‬\n      ‫ســنة ومــا يتحــدث عنــه املدعــي ويطالــب بــه هــو إعــادة طــاء اجلــدران‬\n      ‫وتغييــر ليــات الشــطافات والقاعــدة البالســتيكية لكراســي احلمامــات‬\n\n\n‫‪153‬‬\n\f‫وتغييــر الكوالــن واألقفــال وهــي طلبــات يف احلقيقــة جــرى العــرف علــى‬\n‫انهــا تقــادم طبيعــي ألي مــكان مؤجــر ومــن الطبيعــي أنــه عنــد انتهــاء‬\n‫العقــد يقــوم املالــك بعمــل الصيانــة للعقــار إلعــادة تأجيــره ومــا يطالــب بــه‬\n‫املدعــي هــو أمــر غيــر مألــوف ولــم يجــري عليــه العــرف فالبنــاء كمــا هــو‬\n‫ولــم نقــوم بهــدم املــكان أو إزالــة أعمــدة أو االنتقــاص مــن املبنــى شــيء‬\n‫اللهــم إن اســتخدامنا للمــكان يأتــي يف طــور االســتخدام الطبيعــي‬\n‫ألي مــكان مؤجــر عــودا علــى بــدء فإننــا نشــير أخيــر العقــد اإليجــار‬\n‫يف أننــا أوضحنــا بالبنــد الثالــث مــن عقــد اإليجــار عبــارة ( مــع مراعــاة‬\n‫اإلهــاك الطبيعــي للعقــار ) أخيــرا فإننــا نتقــدم لفضيلتكــم بردنــا حــول‬\n‫مــا أثــاره املدعــي يف دعــواه ونطلــب رد الدعــوى لعــدم قيامهــا علــى ســند‬\n‫مــن الشــرع أو النظــام أو العــرف أو الواقــع فهــي ال تعــدو كونهــا محاولــة‬\n‫للتربــح واإلثــراء بــا ســبب علــى حســاب املدعــى عليهــا فالعقــار حتــت‬\n‫يــده ولــه أن يتصــرف فيــه كيفمــا يشــاء ووقتمــا يشــاء واهلل ولــي التوفيــق‬\n‫أه ـ وبعــرض ذلــك علــى املدعــي وكالــة وأبــرز رده بورقــة هــذا نصهــا‬\n‫أفيــد فضيلتكــم بالتالــي ‪ -1‬املــادة الثالثــة مــن عقــد االيجــار املبــرم مــع‬\n‫الســادة مجموعــة ‪ ...........‬نصــت علــى ( ال يحــق للطــرف الثانــي إضافــة أو‬\n‫تغييــر يف معالــم العــن املؤجــرة مــن دهانــات أو أعمــال ديكــور أو‪..‬الــخ)‬\n‫إال بعــد الرجــوع وموافقــة الطــرف األول وحيــث أنــه قــام بهــدم جــدار‬\n‫وعمــل بــاب دون الرجــوع إلينــا ‪ -2‬املوافقــة املبدئيــة علــى عمــل جبــس‬\n‫بــورد فواصــل بــن الغــرف ولكــن عملــت بطريقــة عشــوائية وليســت‬\n‫حضاريــة ‪ -3‬أرفــق لفضيلتكــم بعــض الصــور اخلاصــة باملبنــى املتهالــك‬\n‫والــذي ميثــل ‪ %10‬مــن الدمــار املوجــود األمــر الــذي دفعنــي بعــدم اســتالم‬\n‫املبنــى ‪ -4‬شــرط مــن شــروط مكاتــب العقــار املوضوعة مــن قبل اجلهات‬\n\n\n                                                                                         ‫‪154‬‬\n\f      ‫املختصــة بــأن علــى املســتأجر إعــام املؤجــر خطيــا إذا رغــب يف جتديــد‬\n      ‫العقــار قبــل حلــول مــدة انتهــاء االيجــار املنصــوص عليــه يف هــذا العقــد‬\n      ‫بأســبوعني علــى األقــل وإذا لــم يقــم بتنفيــذ هــذا الشــرط يعتبر املســتأجر‬\n      ‫مســتاجرا نفــس العقــار لســنة أخــرى ومطالــب بدفــع االيجــار كامــا‬\n      ‫كمــا أن زيــادة جــزء مــن الســنة يعتبــر إيجــار عــام كامــل بــدون مناقشــة‬\n      ‫ألي ســبب كان وحيــث أن القضيــة املاثلــة امــام فضيلتكــم واضحــة‬\n      ‫وموثقــة بأدلــة مصــورة وال تخفــى علــى املدعــى عليــه فإننــي أطلــب مــا‬\n      ‫يلــي ‪ -1‬عــدم املماطلــة وعمــل جميــع االصالحــات وتســليمنا العــن كمــا‬\n      ‫اســتلمها وبإشــراف مهنــدس مــن قبلنــا مرفــق صــورة مــن االســتالم‬\n      ‫‪-2‬دفــع إيجــار الســنة ‪1434-1433‬ه ـ كامــا وعمــل االصالحــات‬\n      ‫خــال ‪ 8‬أشــهر ‪ -3‬تســليمنا جميــع مفاتيــح األبــواب الداخليــة واخلارجيــة‬\n      ‫عنــد انتهــاء فتــرة االيجــار وهــو نهايــة شــهر شــعبان ‪1434/8/30‬ه ـ‬\n      ‫‪-4‬عمــل محضــر اســتالم وتســليم بــن الطرفــن أه ـ وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه وكالــة أبــرز رده بورقــة هــذا نصهــا املوضــوع ‪ :‬الــرد علــى‬\n      ‫خطــاب املدعــي‪ ...........‬املقــدم بجلســة يــوم الثالثــاء ‪ 1434-1-6‬ه ـ‬\n      ‫بالقضيــة رقــم ( ‪ . ) 332150769‬ربط ـ ًا بالــرد الــذي تقدمنــا بــه بجلســة‬\n      ‫يف‪1433/12/29‬ه ـ ‪ -‬والتــي يحــاول فيهــا املدعــي قلــب احلقائــق الثابتــة‬\n      ‫واملعضــدة بإثباتــات كتابيــة ومــا يحــاول إثارتــه بدفــوع واهيــة مــا انــزل‬\n      ‫اهلل بهــا مــن ســلطان للســعي نحــو حتقيــق مكاســب واالثــراء بــا ســبب‬\n      ‫علــي حســاب املدعــي عليهــا و اســمحوا لــي فضيلتكــم بالــرد ونوجــزه يف‬\n      ‫التالــي‪ :‬االول ‪ :‬مــا يتعلــق بدفــع األجــرة واســتالم الفيــا ‪ :‬ال نعلــم مــن أيــن‬\n      ‫أتــي املدعــي مبــا وصفــه مخالفتنــا (( شــرط مــن شــروط مكاتــب العقــار‬\n      ‫املوضوعــة مــن قبــل اجلهــات املختصــة )) فمــا هــي مكاتــب العقــار؟؟ ومــا‬\n\n\n‫‪155‬‬\n\f‫هــي شــروطها ؟؟ ومــا هــي اجلهــات املختصــة ؟؟ ومــا هــي عالقــة مكاتــب‬\n‫العقــار بالعالقــة التعاقديــة وبالدعــوي احلاليــة ‪،‬فاملدعــي يحــاول إغفــال‬\n‫العقــد ويخالــف القواعــد الشــرعية املتأصلــة وهــي أن املســلمون علــى‬\n‫شــروطهم وأن العقــد شــريعة املتعاقديــن ‪ .‬فالثابــت مــن خــال خطــاب‬\n‫االشــعار باإلخــاء املوجــه مــن املدعــي عليــه إلــى املدعــي والــذي قــام‬\n‫باســتالمه املدعــي بتاريــخ ‪ 1433-7-28‬ه ـ ‪ ،‬وفيــه نشــعره برغبتنــا‬\n‫يف إنهــاء العقــد بإنتهــاء الســنة االيجاريــة املدفوعــة لــه والتــي تنتهــي يف‬\n‫‪1433/9/1‬ه ـ وذلــك بحســب البنــد خامســا مــن العقــد ونصــه (( يف حال‬\n‫رغبــة الطــرف الثانــي بإخــاء املــكان املؤجــر عليــه ابــاغ الطــرف االول‬\n‫قبــل انتهــاء مــدة العقــد بشــهر علــي االقــل ويف حــال رغــب يف اخــاء‬\n‫العقــار قبــل نهايــة املــدة يلتــزم بســداد كامــل االيجــار للســنة التــي يرغــب‬\n‫االخــاء خاللهــا )) ‪ .‬وهومــا اقــر بــه املدعــي يف الئحــة دعــواه يف انه تســلم‬\n‫االخطــار ولكــن أغفــل ذكــر التاريــخ اخلــاص باســتالم اخلطــاب اال انــه‬\n‫أقــر يف الئحــة دعــواه بإســتالمه االجــرة حتــي نهايــة الســنة االيجاريــة‬\n                                               ‫التــي انتهــت يف ‪1433/9/1‬هــ‪.‬‬\n‫ومــن هنــا يتضــح عــدم أحقيــة املدعــي فيمــا يطالــب بــه مــن ســداد أجــرة‬\n‫جديــدة ألن العقــار أصبــح يف ملكــه وحتــت تصرفــه ‪ .‬ثاني ـاً‪ :‬يف الــرد‬\n‫علــي طلــب تســليم العقــار يف ‪1433/8/30‬ه ــواستالم املفاتيــح‪ :‬احلقيقــة‬\n‫اننــا نســتغرب مــن هــذا الطلــب وكيــف نســلمه العقــار وندفــع أجرتــه‬\n‫والعقــار حتــت يديــه وتصرفــه وإال كيــف صــور املــكان و مــن أيــن أتــي‬\n‫بالصــور التــي ســاقها وقدمهــا ومــن أيــن قــام بعمــل حصــر كمــا يدعــي‬\n‫بآثــار الدمــار وكأن قنبلــة ســقطت علــى العقــار كمــا جــاء بوصفــه‬\n‫مــن تهويــل وخيــال يف الوصــف‪ .‬فالعقــار حتــت يــد املدعــي وحتــت‬\n\n\n                                                                                        ‫‪156‬‬\n\f      ‫تصرفــه ولديــه مفاتيحــه ويحــاول تأجيــره علــي الغيــر ومعــروض لــدي‬\n      ‫اكثــر مــن مكتــب عقــاري منــذ فتــرة وحتــي تاريخــه لــم يقــوم بتأجيــره‬\n      ‫حيــث ان املــكان هــو يف االصــل وكمــا ذكرنــا ســكن عمــال وليــس‬\n      ‫مقســما كشــقق ســكنية ‪ .‬ثالثــا‪ :‬فيمــا يتعلــق بطلــب املدعــي اصــاح‬\n      ‫العــن املؤجــرة‪ :‬اســمحوا لنــا فضيلتكــم أن نكــرر بعــض مــا ذكرنــاه‬\n      ‫مبذكرتنــا الســابقة يف أن العقــار موضــوع الدعــوى وهــو مــا اســماه‬\n      ‫املدعــي فيــا هــو يف احلقيقــة منــزل مكــون مــن طابقــن وغــرف ملحقــة‬\n      ‫للحــارس وتاريــخ بنــاؤه يعــود الــي أكثــر مــن خمــس وعشــرون ســنة وقــد‬\n      ‫كان مجهــزا مــن قبــل كســكن للعمــال مــن خــال التجهيــزات التــي‬\n                                   ‫كانــت بــه وهــو مــا دعانــا يف احلقيقــة لتأجيــره‪.‬‬\n      ‫ومــا يتحــدث عنــه املدعــي مــن عمــل فواصــل وقواطــع جبــس فقــد كانــت‬\n      ‫بعلمــه وموافقتــه الصريحــة وباتفاق مكتوب بالعقــد بالبند ثالثا ((وافق‬\n      ‫الطــرف األول علــي الســماح للطــرف الثانــي بعمــل فواصــل جبســون بــورد‬\n      ‫أو خشــبية لتقســيم املســاحات الكبيرة ليتم اســتخدامها وعلي حســاب‬\n      ‫الطــرف الثانــي )) أمــا مــا يتحــدث عنــه مــن أن منظرهــا غيــر حضــاري‬\n      ‫وعشــوائية فهــذا شــأنه والعقــار بحوزتــه إن شــاء ابقاهــا وإن شــاء نزعهــا‬\n      ‫فهــي جتهيــزات وافــق عليهــا مســبقا وعلــي علــم بهــا وليــس علــي املدعــي‬\n      ‫عليهــا ادنــي التــزام أو اتفــاق بالعقــد علــي نزعهــا عــن إخــاء العقــار ‪.‬‬\n      ‫ومــا يتحــدث عنــه املدعــي ويطالــب بــه هــو إعــادة طــاء اجلــدران وتغييــر‬\n      ‫ليــات الشــطافات والقاعــدة البالســتيكية لكراســي احلمامــات وتغييــر‬\n      ‫الكوالــن واألقفــال وهــي طلبــات يف احلقيقــة جــرى العــرف علــي أنهــا‬\n      ‫تقــادم طبيعــي ألي مــكان مؤجــر ومــن الطبيعــي انــه عنــد انتهــاء العقــد‬\n      ‫يقــوم املالــك بعمــل الصيانــة للعقــار إلعــادة تأجيــره ‪ ،‬ومــا يطالــب بــه‬\n\n\n‫‪157‬‬\n\f‫املدعــي هــو أمــر غيــر مألــوف ولــم يجــري عليــه العــرف ‪ .‬فالبنــاء كمــا‬\n‫هــو ولــم نقــوم بهــدم املــكان أو إزالــة أعمــدة أو االنتقــاص مــن املبنــى‬\n‫شــيء اللهــم إن اســتخدامنا للمــكان يأتــي يف طــور االســتخدام الطبيعي‬\n‫ألي مــكان مؤجــر‪ .‬عــودا علــي بــدء فإننــا نشــير أخيــرا لعقــد اإليجــار‬\n‫يف أننــا أوضحنــا بالبنــد الثالــث عبــارة (مــع مراعــاة اإلهــاك الطبيعــي‬\n‫للعقــار) ‪ .‬أخيــرا فإننــا نتقــدم لفضيلتكــم بردنــا حــول مــا أثــاره املدعــي‬\n‫يف دعــواه ونطلــب ‪ :‬رد الدعــوي لعــدم قيامهــا علــي ســند مــن الشــرع‬\n‫او النظــام او العــرف أو الواقــع فهــي ال تعــدو كونهــا محاولــة للتربــح‬\n‫واإلثــراء بــا ســبب علــي حســاب املدعــي عليهــا فالعقــار حتــت يــده‬\n‫وبحوزتــه ولــه ان يتصــرف فيــه كيفمــا يشــاء ‪ .‬أه ـ فطلبــت مــن الطرفــن‬\n‫العقــد فأبــرز املدعــي وكالــة عقــدا وهــذا نصــه عقــد إيجــار بحمــد اهلل‬\n‫ال‬\n‫وتوفيقــه مت يف يــوم الســبت بتاريــخ ‪ 1430-9-1‬ه ـ اإلتفــاق بــن ك ً‬\n‫مــن ‪ :‬الســيد ‪ ........... :‬ســعودي اجلنســية هويــه رقــم (‪ )...........‬تاريــخ ‪-24‬‬\n‫‪1386-3‬ه ـ صــادره مــن مكــة املكرمــة وهــو املؤجــر ويشــار إليــه فيمــا‬\n‫بعــد بالطــرف األول ‪.‬الســادة ‪ :‬شــركة ‪ ......................‬و ميثلهــم يف هــذا‬\n‫العقــد الوكيــل الشــرعي مبوجــب صــك وكالــه رقــم ( ‪ ) 47013‬وتاريــخ‬\n‫‪1429-9-6‬ه ـ الصــادرة مــن كتابــة عــدل الثانيــة مبكــة املكرمــة‬\n‫الســيد‪ .......................‬ســعودي اجلنســية رقــم الهويــة (‪) .........................‬‬\n‫تاريــخ ‪ 1410-1-22‬ه ـ صــادره مــن مكــة املكرمــة وهــو املســتأجر و‬\n‫يشــار إليــه فيمــا بعــد بالطــرف الثانــي ‪ .‬علــى اآلتــي‪ :‬أو ًال ‪ :‬اطلــع الطــرف‬\n‫الثانــي علــى العــن املؤجــرة والكائنــة بحــي الهجــرة الطريــق الدائــري‬\n‫الثالــث فيــا دوريــن باملكيفــات و عددهــا (‪ )24‬مكيــف و بحالــه جيــده‬\n‫جــد ًا خلــف متوينــات ‪ ......‬الســتغالله كســن ملوظفــن شــركة ‪. ...........‬‬\n\n\n                                                                                               ‫‪158‬‬\n\f      ‫ثاني ـ ًا ‪ :‬حتمــل الطــرف الثانــي املســؤولية القانونيــة عــن اســتعمال العــن‬\n                          ‫املؤجــرة مبجــرد اســتالمه للعــن و بدايــة عقــد اإليجــار‪.‬‬\n      ‫ثالث ـ ًا ‪ :‬ال يحــق للطــرف الثانــي إضافــة أو تغييــر معالــم العــن املؤجــرة‬\n      ‫مــن دهانــات أو أعمــال ديكــور إال بعــد موافقــة الطــرف األول ‪ ،‬كمــا‬\n      ‫يتحمــل الطــرف الثانــي جميــع أعمــال الصيانــة مــع مراعــاة احتســاب‬\n      ‫اإلهــاك الطبيعــي للمبنــى و محتوياتــه عنــد نهايــة العقــد ‪،‬وقــد وافــق‬\n      ‫الطــرف األول علــى الســماح للطــرف الثانــي بعمــل فواصــل جيبســن بــورد‬\n      ‫أو خشــبيه لتقســيم املســاحات الكبيرة بالفيال حتى ميكن استخدامها‬\n      ‫و علــى حســاب الطــرف الثانــي‪ .‬رابع ـ ًا ‪ :‬يلتــزم الطــرف الثانــي بتســديد‬\n      ‫فاتــورة الكهربــاء وامليــاه و الصــرف الصحــي اخلاصــة بالعــن املؤجــرة‬\n      ‫ـداء مــن تاريــخ االســتالم ‪ .‬خامس ـ ًا ‪ :‬يف حالــة رغبــة الطــرف الثانــي‬ ‫ابتـ ً‬\n      ‫بإخــاء املــكان املؤجــر عليــه إبــاغ الطــرف األول قبــل انتهــاء مــدة‬\n      ‫العقــد بشــهر علــى األقــل ‪ ،‬و يف حــال رغــب يف إخــاء العقــار قبــل نهايــة‬\n      ‫املــدة يلتــزم الطــرف الثانــي بســداد كامــل اإليجــار للســنه اإليجاريــة‬\n      ‫التــي يرغــب اإلخــاء خاللهــا ‪ .‬سادس ـ ًا ‪ :‬مــدة العقــد املبــرم (‪ )5‬خمــس‬\n      ‫ـداء مــن تاريــخ ‪1430-9-1‬ه ـ وحتــى ‪1435-8-30‬ه ـ قابلــه‬          ‫ســنوات ابتـ ً‬\n      ‫للتجديــد ملــده مماثلــه ‪ ،‬و يف حــال رغبــة الطــرف األول بعــدم جتديــد‬\n      ‫مــدة العقــد فــإن عليــه إبــاغ الطــرف الثانــي قبــل انتهــاء مــدة العقــد‬\n      ‫بشــهر علــى األقــل ‪ .‬ســابع ًا ‪ :‬يلتــزم الطــرف الثانــي بدفــع قيمــة اإليجــار‬\n      ‫كدفعــه واحــده كاملــه أول كل عــام مــن تاريــخ العقــد ‪.‬ثامنـ ًا ‪ :‬يدفــع‬\n      ‫الطــرف الثانــي للطــرف األول مبلــغ و قــدره (‪ ) 80.000‬ثمانــون ألــف‬\n      ‫ريــال ال غيــر للســنه األولــى مــن العقــد مــع زيــادة ســنوية بنســبة (‪)% 10‬‬\n      ‫مــن قيمــة اإليجــار املذكــور أعــاه اعتبــار ًا مــن الســنه الثانيــة ويعتبــر‬\n\n\n‫‪159‬‬\n\f‫قيمــة إيجــار ملــدة ســنه كاملــه تبــد ًا يف تاريــخ ‪1430/9/1‬ه ـ وتنتهــي‬\n‫يف تاريــخ ‪ 1431-8-30‬ه ـ حســب التوضيــح التالــي ‪ :‬م تاريــخ اســتحقاق‬\n                           ‫اإليجــار مبلــغ اإليجــار املســتحق بالريــال ســعودي‬\n                                                 ‫‪ 1431-9-1 1‬هـ ‪ 88.000‬ريال‬\n                                                 ‫‪ 1432-9-1 2‬هـ ‪ 96.800‬ريال‬\n                                               ‫‪ 1433-9-1 3‬هـ ‪ 106.480‬ريال‬\n                                               ‫‪ 1434-9-1 4‬هـ ‪ 117.164‬ريال‬\n‫و إلحقــاق حــق كل طــرف أبــرم هــذا العقــد بنســختني أصليتــن بثمانيــة‬\n‫بنــود ملزمــة قانون ـ ًا و شــرع ًا للعمــل بــه لــكل مــن الطرفــن و اهلل ولــي‬\n‫التوفيــق و خيــر الشــاهدين أه ــو بعرضــه علــى املدعــي وكالــة صــادق‬\n‫عليــه وبســؤال املدعــي وكالــة هــل وافــق موكلــه علــى مــا قام بــه املدعى‬\n‫عليــه مــن تعديــات وإضافــات للمبنــى فقــال إن املدعــى عليــه عمــل‬\n‫أعمــال كثيــرة يف املبنــى وموكلــي لــم يوافــق إال علــى أعمــال اجلبســون‬\n‫بــورد ( فواصــل بــن الغــرف ) وأمــا مــا عــدا ذلــك فلــم يوافــق عليــه ولــم‬\n‫يبلغــه بــه املدعــى عليــه ومــن هــذه األعمــال التــي قــام بهــا املدعــى عليــه‬\n‫ولــم يبلــغ بهــا موكلــي وضــع بــاب خشــب بطريقــة عشــوائية بالــدور‬\n‫العلــوي وهــدم جــدار بالصالــون األرضــي كمــا أن اجلبســون بــورد الــذي‬\n‫وضعــوه كان بطريقــة ســيئة عشــوائية كمــا أن هنــاك اتالفــات‬\n‫باحلمامــات واملكيفــات كمــا أن أحــد األبــواب احلديــد يف امللحــق‬\n‫اخلارجــي غيــر موجــود وكذلــك اتالفــات يف الكهربــاء والبويــة‬\n‫واملكيفــات ونقــص يف محتويــات احلمامــات فبعضهــا غيــر موجــود أو‬\n‫مكســور وكل ذلــك يــدل علــى أنــه ليــس إهــاك طبيعــي وإمنــا عمــل‬\n‫مقصــود هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال أمــا‬\n\n\n                                                                                        ‫‪160‬‬\n\f      ‫اجلبســون بــورد فقــد مت تركيبــه عــادي يف حــدود الطبيعــي وموافــق‬\n      ‫للمواصفــات وأمــا مــا فقــد ومالــم يفقــد فــا نعلــم عنــه شــيئا ألننــا ســلمنا‬\n      ‫العقــار للمدعــي أصالــة مــن تاريــخ ‪1433/9/1‬ه ـ وأمــا وضــع البــاب يف‬\n      ‫الــدور العلــوي وهــدم جــدار يف الصالــون األرضــي فهــذا نحــن ملزمــون‬\n      ‫بإصالحــه وأمــا الهــاك يف البويــة والكهربــاء فهــو إهــاك عــادي وليس‬\n      ‫فيــه تخريــب مقصــود هكــذا قــرر فســألت املدعــي وكالــة هــل اســتلم‬\n      ‫موكلــك العقــار يف ‪1433/9/1‬ه ـ فقــال ان موكلــي لــم يســتلم العقــار‬\n      ‫بتاريــخ ‪1433/9/1‬ه ـ ورفضنــا اســتالم العقــار لوجــود تلفيــات فيــه علمــا‬\n      ‫بأنــه لــم يبلغنــا برغبتــه يف اإلخــاء وفســخ العقد إال قبــل رمضان بحوالي‬\n      ‫عشــرين يومــا أو خمســة عشــر يومــا وملــا رفضنــا االســتالم بقــي العقــار‬\n      ‫يف حوزتهــم ثــم إنهــم بتاريــخ ‪1433/12/6‬ه ـ أرســلوا لنــا رســالة بواســطة‬\n      ‫شــركة ‪ .....‬مرفقــا بهــا مفاتيــح وتبــن أن هــذه املفاتيــح هــي ليســت‬\n      ‫لألبــواب اخلارجيــة وإمنــا ألبــواب داخليــة هكــذا قــرر وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه وكالــة فقــال إن موكلــي أبلــغ املدعــي أصالــة بتاريــخ‬\n      ‫‪1433/7/28‬ه ـ بخطــاب ســلم لــه شــخصيا ورفــض اســتالم العقــار طيلــة‬\n      ‫هــذه املــدة حتــى أواخــر شــعبان حضــر املدعــي وكالــة ودخــل البيــت‬\n      ‫وطلبنــا منــه اســتالم املفاتيــح فرفــض بســبب وجــود مالحظــات لديــه‬\n      ‫علــى العقــار ثــم أرســل لنــا فاكــس يرفــض فســخ العقــد وأن العقــار ال‬\n      ‫زال بيــد موكلــي فحاولنــا الوصــول إلــى حــل ودي مــع املدعــي أصالــة‬\n      ‫فذكــر أن ســبب رفضــه الســتالم البيــت فقــال إنــه يوجــد بالعقــار‬\n      ‫تخريــب واتالفــات وأن علينــا إصالحــه فقــال لــه إننــا مســؤولني عــن أي‬\n      ‫تخريــب وإتــاف وأمــا اإلهــاك الطبيعــي فهــذا ال نتحملــه فرفــض‬\n      ‫وطلــب منــا إصــاح العقــار بخمســة وســتني ألــف ريــال فرفضنــا ذلــك‬\n\n\n‫‪161‬‬\n\f‫وتقــدم بهــذه الدعــوى ثــم أرســلنا لــه مفاتيــح العقــار برســالة عبــر شــركة‬\n‫فيدكــس وهــي النســخة الوحيــدة التــي توجــد لدينــا وال أعلــم هــل مفتــاح‬\n‫خارجــي أم داخلــي علمــا بأننــا اســتلمنا نســخة واحــدة مــن جميــع األبــواب‬\n‫الداخليــة واخلارجيــة وليــس لدينــا ســوى هــذا املفتــاح الــذي بعثنــاه‬\n‫للمدعــي أصالــة وال نعلــم هــل هــو للبــاب اخلارجــي أم لألبــواب الداخليــة‬\n‫هكــذا قــرر وحيــث األمــر مــا ذكــر فقــد جــرى بعــث املعاملــة إلــى هيئــة‬\n‫النظــر باخلطــاب رقــم ‪ 332150769‬يف ‪1434/1/10‬ه ـ للوقــوف علــى‬\n‫العقــار ومعاينتــه واإلفــادة عــن التلفيــات املوجــودة فيــه هــل هــي طبيعيــة‬\n‫أم ســبب تفريــط وتعــدي مــن املســتأجر واإلفــادة عــن أدوات احلمــام‬\n‫املفقــودة وتقديرهــا وكذلــك تقديــر إصــاح اإلعمــال التــي قــام املدعــى‬\n‫عليــه ولــم يســتأذن املدعــي أصالــة مــن وضــع بــاب يف الــدور العلــوي وهدم‬\n‫جــدار يف الــدور األرضــي وكذلــك اإلفــادة عــن الفواصــل الصناعيــة‬\n‫املوجــودة يف الــدور األرضــي هــل وضعــت حســب أصــول الصنعــة أم ال‬\n‫إ‪.‬ه ـ فــوردت اإلجابــة مــن هيئــة النظــر باخلطــاب رقــم ‪332150769‬‬\n‫يف‪1434/5/12‬ه ـ وهــذا نصــه احلمــد هلل والصــاة والســام علــى نبينــا‬\n‫محمــد والــه وصحبــه بنــاء علــى املعاملــة الــواردة لنــا مــن فضيلــة الشــيخ‬\n‫‪ .........‬رقــم ‪ 332150769‬يف ‪1434/1/10‬ه ـ بشــأن دعــوى ‪ ...........‬ضــد‬\n‫‪ ...........‬بوكالتــه عــن ‪ ...........‬فطلــب فضيلتــه الوقــوف واإلفــادة ‪...‬الــخ‬\n‫عليــه فقــد جــرى الوقــوف وتبــن أن العقــار محــل الدعــوى كان محــل‬\n‫اهتمــام مالكــه والعنايــة بــه والــذي يــراه حيــال مــا طلــب فضيلتــه اآلتــي‪:‬‬\n‫أوال‪ /‬إزالــة الفواصــل الصناعيــة لعــدم توافقهــا ألصــول الصنعــة مــن‬\n‫جهــة عــدم مالئمتهــا ملــا هــي فيــه ‪ .‬ثانيــا‪ :‬إزالــة البــاب املوضــوع بالــدور‬\n‫العلــوي وبنــاء اجلــدار املهــدوم بالــدور األول وإعــادة تأهيلــه حســب أصــول‬\n\n\n                                                                                        ‫‪162‬‬\n\f      ‫الصنعــة وتقديــر ذلــك ألفــان وثالثمائــة ريــال ‪ .‬ثالثــا‪ /‬تركيــب درفــة‬\n      ‫أملنيــوم ويقــدر ذلــك بخمســمائة ريــال رابعــا‪ /‬تركيــب األدوات التالفــة‬\n      ‫وتقديــر ذلــك ثالثــة آالف وأربعمائــة ريــال خامســا‪ /‬تســليم مفاتيــح‬\n      ‫األبــواب أو تغيــر القلــوب وتقديــر ذلــك مائتــان وخمســن ريــال سادســا‪/‬‬\n      ‫عمــل نظافــة للموقــع مــع تــروي مبواضــع التنديــة يف دورات امليــاه ويقــدر‬\n      ‫ذلــك بخمســمائة ريــال ســابعا ‪ /‬تعــذر اختبار عمــل املكيفات ومضخات‬\n      ‫امليــاه لعــدم وجــود كهربــاء باملوقــع هــذا مــا جــرى تقديــره ‪.‬إ‪.‬ه ـ ثــم جــرى‬\n      ‫إعادة املعاملة لهيئة النظر بشرحي رقم ‪ 332150769‬يف‪1434/5/25‬هـ‬\n      ‫لإلفــادة عــن التلفيــات املوجــودة يف العقــار وهــل هــي طبيعيــة ام نتيجــة‬\n      ‫تعــدي او تفريــط مــن املســتأجر وحصرهــا مفصــا وكذلــك حصــر‬\n      ‫أدوات احلمــام املفقــودة مفصــا وتقديرهــا إ‪.‬ه ـ فعــادت املعاملــة مــن هيئــة‬\n      ‫النظــر باخلطــاب رقــم ‪ 332150769‬يف‪1434/6/21‬ه ـ وهــذا نصــه‬\n      ‫احلمــد هلل والصــاة والســام علــى نبينــا محمــد والــه وصحبــه بنــاء علــى‬\n      ‫املعاملــة الــواردة لنــا مــن فضيلــة الشــيخ ‪ ...................‬رقــم ‪332150769‬‬\n      ‫يف ‪1434/1/10‬ه ـ بشــأن دعــوى ‪ ....................‬ضــد ‪ ............‬وكالــة‬\n      ‫فطلــب فضيلتــه اإلفــادة عــن التلفيــات هــل هــي طبيعيــة ام نتيجــة تعــدي‬\n      ‫او تفريــط مــن املســتأجر وكذلــك حصــر أدوات احلمــام املفقــودة‬\n      ‫وتقديرهــا عليــه نفيــد بــأن التلفيــات تتمثــل يف ‪ /1‬تركيــب بــاب بالــدور‬\n      ‫العلــوي ‪ /2‬فتــح جــدار بالــدور األرضــي وتركيــب بــاب مكانــه ‪ /3‬عــدم‬\n      ‫وجــود درفــة بــاب املنيــوم ‪ /4‬عــدم وجــود مفاتيــح األبــواب ‪ /5‬تنديــة يف‬\n      ‫دورات امليــاه فــاألول والثانــي نتيجــة احلاجــة إليــه مــن قبــل املســتأجر‬\n      ‫والثالــث والرابــع تعــدي وتفريــط واخلامــس نتيجــة إهمــال الصيانــة‬\n      ‫والتقديــر كمــا جــاء بقرارنــا الســابق أمــا أدوات احلمام املفقــودة والتالفة‬\n\n\n‫‪163‬‬\n\f‫فهــي ‪ /1‬مغاســل عــدد ثالثــة ‪ /2‬خــاط مغســلة عــدد ثالثــة ‪ /3‬شــفاط‬\n‫ولــي عــدد ثالثــة ‪ /4‬كرســي عــدد اثنــان ‪ /5‬بانيــو مــع خــاط عــدد‬\n‫واحــد فــاألول عــدد (‪ )2‬تالــف وواحــد مفقــودة والثانــي والثالــث والرابــع‬\n‫تالــف واخلامــس مفقــود فــاألدوات التالفــة نتيجــة التفريــط واملفقــودات‬\n‫ســببها ظاهــر وتقديرهــا مفصــا ‪ /1‬ســعر الوحــدة ‪350‬ريــال ‪ /2‬ســعر‬\n‫الوحــدة ‪ 90‬ريــال ‪ /3‬ســعر الوحــدة ‪25‬ريــال ‪ /4‬ســعر الوحــدة ‪ 600‬ريــال‬\n‫‪ /5‬ســعر الوحــدة ‪ 800‬ريــال هــذا مــا جــرى تقديــره إ‪.‬ه ـ بعــرض قــراري‬\n‫هيئــة النظــر علــى الطرفــن قــاال نطلــب إمهالنــا ملراجعــة موكلينــا ‪ .‬ويف‬\n‫جلســة أخــرى حضــر الطرفــان وكالــة وقــرر املدعــى عليــه وكالــة قائــا‬\n‫ان لــدى موكلــي رد علــى مــا جــاء يف قــرار هيئــة النظــر وأبــرز ورقــة هــذا‬\n‫نصهــا (نتقــدم بالــرد علــي طلبــات املدعــي وكذلــك التعقيــب علــي‬\n‫التقريــر الــوارد مــن هيئــة النظــر ونلخــص الــرد فيمــا يلــي ‪:‬أوال ‪ :‬الــرد‬\n‫علــي ادعــاءات املدعــي للمطالبــة بأجــرة عــن الفتــرة املتبقيــة بعقــد‬\n‫االيجــار‪ :‬العقــد شــريعة املتعاقديــن واملســلمون علــى شــروطهم فعقــد‬\n‫االيجــار اعطــى للمدعــي عليهــا موكلتــي حــق فســخ العقــد قبــل انتهــاء‬\n‫مدتــه شــريطة ان يتــم ســداد االيجــار للســنة االيجاريــة التــي ينفســخ فيهــا‬\n‫ا راجــع العقــد مســتند رقــم ‪ ) 1‬بحســب البنــد خامســا مــن‬        ‫العقــد (فضـ ً‬\n‫العقــد ونصــه ‪ ((:‬يف حــال رغبــة الطــرف الثانــي بإخــاء املــكان املؤجــر‬\n‫عليــه ابــاغ الطــرف االول قبــل انتهــاء مــدة العقــد بشــهر علــى االقــل ويف‬\n‫حــال رغــب يف اخــاء العقــار قبــل نهايــة املــدة يلتــزم بســداد كامــل‬\n‫االيجــار للســنة التــي يرغــب االخــاء خاللهــا)) ‪ .‬وبالفعــل فقــد ســددت‬\n‫املدعــي عليهــا االجــرة كاملــة للســنة التــي مت الفســخ خاللهــا وهــو مــا‬\n‫أقــر بــه املدعــي يف الئحــة دعــواه (فضــا راجــع الئحــة الدعــوي ‪ -‬مســتند‬\n\n\n                                                                                       ‫‪164‬‬\n\f      ‫رقــم (‪ ))2‬حيــث اقــر بســدادنا االجــرة لــه واســتالمه اياهــا ‪ ،‬وكذلــك‬\n      ‫هنــاك اقــرار صريــح مــن املدعــي بأنــه تلقــي إخطــار مــن املدعــي عليهــا‬\n      ‫لــه بفســخ العقــد حيــث ان العقــد بالبنــد اخلامــس اعطــي للمدعــي عليهــا‬\n      ‫حــق الفســخ شــريطة االخطــار املســبق قبــل نهايــة الســنة االيجاريــة مبــدة‬\n      ‫شــهر وهــو مــا أقــر بــه املدعــي يف الئحــة دعــواه يف انــه تســلم االخطــار يف‬\n      ‫تاريــخ ‪ 1433-7-28‬هــ‪ .‬مــن هنــا يتضحــان املدعــي عليهــا مــن حقهــا‬\n      ‫فســخ العقــد وانهــاؤه قبــل حلــول أجــل العقــد ويتضــح ايض ـ ًا أن املدعــي‬\n      ‫عليهــا قــد أوفــت بكامــل التزامهــا مــع املدعــي وســددت لــه كامــل‬\n      ‫الســنة التعاقديــة وبالتالــي فليــس للمدعــي وجــه حــق فيمــا يطالــب بــه مــن‬\n      ‫ســداد اجــرة عــن ســنة ايجاريــة جديــدة أو ســداد االجــرة لســنوات العقــد‬\n      ‫املتبقيــة الن العقــد شــريعة املتعاقديــن واملســلمون علــى شــروطهم ‪ .‬فيمــا‬\n      ‫يتعلــق بطلــب املدعــي اصــاح العــن املؤجــرة ‪ :‬العقــار موضــوع الدعــوي‬\n      ‫هــو يف احلقيقــة منــزل مكــون مــن طابقــن وغــرف ملحقــة للحــارس‬\n      ‫وتاريــخ بنــاؤه يعــود الــي أكثــر مــن خمــس وعشــرون ســنة ومــا يتحــدث‬\n      ‫عنــه املدعــي ويطالــب بــه هــو اعــادة طــاء اجلــدران وتغييــر ليــات‬\n      ‫الشــطافات والقاعــدة البالســتيكية لكراســي احلمامــات وتغييــر‬\n      ‫الكوالــن واألقفــال أو ترويــب أرضيــة احلمامــات باإلســمنت األبيــض‬\n      ‫هيفــي احلقيقــة طلبــات جــري العــرف علــي انهــا اســتهالك وأمــور تقــادم‬\n      ‫طبيعــة ألي مــكان مؤجــر ومــن الطبيعــي أنــه عنــد انتهــاء العقــد يقــوم‬\n      ‫املالــك بعمــل الصيانــة للعقــار إلعــادة تأجيــره ومــا يطالــب بــه املدعــي هــو‬\n      ‫أمــر غيــر مألــوف ولــم يجــري عليــه العــرف ‪.‬فالبنــاء كمــا هــو ولــم نقــوم‬\n      ‫بتغييــر معالــم العقــار أو هــدم املــكان أو إزالــة اعمــدة او االنتقــاص مــن‬\n      ‫املبنــى شــيء اللهــم ان اســتخدامنا للمــكان يأتــي يف طــور االســتخدام‬\n\n\n‫‪165‬‬\n\f‫الطبيعــي ألي مــكان مؤجــر عــود ًا علــي بــدء فإننــا نشــير اخيــر ًا لعقــد‬\n‫االيجــار يف أننــا أوضحنــا بالبنــد الثالــث عبــارة (مــع مراعــاة االهــاك‬\n‫الطبيعــي للـ ــعقار) ‪ .‬ثانيــا ‪ :‬التعقيــب علــى تقريــر هيئــة النظــر ‪ :‬جــاء‬\n‫تقريــر هيئــة النظــر مجحفــا بحــق املدعــي عليهــا فاملبنــى جتــاوز عمــره‬\n‫‪ 30‬أو‪ 40‬ســنة وكانــت املدعــى عليهــا تســدد أجــرة ‪ 100000‬ريــال ثــم‬\n‫تقــرر الهيئــة حتميلنــا‪ 6950‬ريــال قيمــة صيانــة هــو امــر ًا نــراه مجحف ـ ًا‬\n‫رغــم ضآلــة املبلــغ ونخــص اعتراضنــا عليمــا ورد بالتقريــر يف النقــاط‬\n                                                                          ‫التالية‪:‬‬\n‫‪ .1‬عــدم وجــود ‪ 2‬كرســي حمــام وقيمتــه ‪600‬ريــال ‪ :‬يف احلقيقــة لــم‬\n‫تكــن تلــك الكراســي موجــودة مــن االســاس عنــد اســتالم الفيــا فمــا‬\n‫تتحــدث عنــه هيئــة النظــر هــي كرســي احلمــام الشــطاف وهــو مــا يطلــق‬\n‫عليــه (بيديــه) وهــو غيــر موجــود مبكانــه مــن االصــل ورمبــا نزعــه‬\n‫مــن مكانــه املســتأجر الســابق أو مالــك العقــار املدعــي كــون هــذا‬\n‫الكرســي غيــر مســتخدم وليــس لــه اســتخدام خاصــة عندنــا كشــعوب‬\n‫عربيــة واحلقيقــة ان الــزام املدعــي عليهــا بقيمتــه هــو نــوع مــن االجحــاف‪.‬‬\n‫‪ .2‬الــزام الهيئــة للمدعــي عليهــا بتركيــب ‪ 3‬ليــات شــطاف وقيمتهــا‪90‬‬\n‫ريــال ‪ :‬فهــو أمــر خــارج عــن العــرف والعــادة حيــث ان تلــك االدوات‬\n‫مســتهلكة بطبيعتهــا مــع االســتخدام وجــرى العــرف علــي تغييرهــا مــن‬\n‫آن آلخــر خاصــة ان اللــي مــن البالســتيك ومســألة اســتخدامه مــع مــرور‬\n                                     ‫الزمــان تــؤدي لتهالكــه هــو امــر طبيعــي‪.‬‬\n‫‪ .3‬مــا يتعلــق باملغاســل وعددهــا ‪ 3‬وعــدد ‪ 3‬خالطــات وقيمتهــا ‪1320‬‬\n‫ريــال ‪ :‬فنوضــح أن أماكــن تلــك املغاســل موجــودة ولكنهــا لــم تكــن‬\n‫مركبــة عــن االســتالم كــون اماكــن تواجدهــا بالصالــة أمــام املطبــخ‬\n\n\n                                                                                     ‫‪166‬‬\n\f      ‫وقــت كان املالــك (املدعــي) يؤجــر العقــار إلســكان احلجــاج ونوضــح‬\n      ‫أن املغاســل اخلالطــات لــم تكــن موجــودة مــن االســاس فكيــف لنــا ان‬\n      ‫نتحمــل قيمــة غيــر موجــود ‪ -1‬مــا يتعلــق بتنديــة احلمــام وترويــب ارضيــة‬\n      ‫احلمــام الصغيــر باجلبــس االبيــض وعمــل نظافــة للموقــع والــذي قدرتــه‬\n      ‫الهيئــة بــ‪ ...........‬ريــال ‪:‬هــو يف احلقيقــة أمــر خــارج العــرف فترويب البالط‬\n      ‫للحمامــات امــرا ال دخــل للمســتأجر فيــه أو بخــروج االســمنت األبيــض‬\n      ‫مــن مكانــه بالبــاط موضــوع حتميــل هيئــة النظــر املســؤولية للمدعــي‬\n      ‫عليهــا بقيمــة اصالحــات ال تتجــاوز ‪ 3400‬ريــال ‪ :‬هــو أمــر فيــه اجحــاف‬\n      ‫للمدعــي عليهــا كــون تلــك األدوات لــم تكــن موجــودة يف األســاس أو‬\n      ‫خلروجهــا عــن العــرف واملألــوف فضــا عــن ذلــك فــإن هيئــة النظــر لــم‬\n      ‫تقــم باإلشــارة الــى تاريــخ البنــاء او عمــر املبنــي والــذي جتــاوز‪ 30‬الــي ‪40‬‬\n      ‫ســنة منــذ تاريــخ بنــاؤه أخيــر ًا فإننــا نتقــدم لفضيلتكــم بردنــا حــول مــا‬\n      ‫أثــاره املدعــي يف دعــواه ونعقــب علــي تقريــر هيئــة النظــر ونطلــب ‪/1 :‬‬\n      ‫رد الدعــوي لعــدم قيامهــا علــي ســند مــن الشــرع أو النظــام او العــرف أو‬\n      ‫الواقــع فهــي ال تعــد وكونهــا محاولــة للتربــح واالثــراء بــا ســبب علــى‬\n      ‫حســاب املدعــي عليهــا فالعقــار حتــت يــده وبحوزتــه ولــه ان يتصــرف فيــه‬\n      ‫كيفمــا يشــاء شــركة محــات عبدالصمــد القرشــي عنهــا وكالــة‬\n      ‫محمــد ابراهيــم شــاولي) إ‪.‬ه وبعــرض ذلــك علــى املدعــى وكالــة قــال إن‬\n      ‫موكلــي يطالــب مبــا قدرتــه هيئــة النظــر علمــا بــأن هيئــة النظــر قــدرت‬\n      ‫أن التالــف هــو ســبب تفريــط املدعــى عليــه ولــذا فيلزمــه دفــع مــا قدرتــه‬\n      ‫هيئــة النظــر كمــا أن موكلــي يطالبــه بإلــزام املدعــى عليــه بدفــع‬\n      ‫االجــرة التــي بــدأت يف ‪1433/9/1‬ه ـ وســداد فواتيــر الكهربــاء واملــاء‬\n      ‫حتــى نهايــة هــذا الشــهر هكــذا قــرر ‪ ،‬فجــرى ســؤال املدعــى عليــه‬\n\n\n‫‪167‬‬\n\f‫وكالــة هــل اســتأذن موكلــه فيعمــل التعديــات فيمــا عــدا الفواصــل‬\n‫فقــال إن موكلــي لــم يســتأذن فيمــا عمــل يف العقــار ماعــدا الفواصــل‬\n‫وبعــرض ذلــك علــى املدعــي وكالــة قــال صحيــح انــه لــم يســتأذن إال يف‬\n‫عمــل الفواصــل ومــع ذلــك فإنــه لــم يعملهــا وفــق أصــول الصنعــة هكــذا‬\n‫قــرر فبنــاء علــى مــا تقــدم مــن املدعــى واإلجابــة وبعــد االطــاع علــى‬\n‫العقــد بــن الطرفــن والن الفقــرة الثالثــة مــن العقــد نصــت علــى ال يحــق‬\n‫للطــرف الثانــي إضافــة أو تغييــر معالــم العــن املؤجــرة مــن دهانــات أو‬\n‫أعمــال ديكــور إال بعــد موافقــة الطــرف األول ‪ ،‬كمــا يتحمــل الطــرف‬\n‫الثانــي جميــع أعمــال الصيانــة مــع مراعــاة احتســاب اإلهــاك الطبيعــي‬\n‫للمبنــى و محتوياتــه عنــد نهايــة العقــد ‪ ،‬وقــد وافــق الطــرف األول علــى‬\n‫الســماح للطرف الثاني بعمل فواصل جيبســون بورد أو خشــبيه لتقســيم‬\n‫املســاحات الكبيــرة بالفــا حتــى ميكــن اســتخدامها و علــى حســاب‬\n‫الطــرف الثانــي ‪ .‬كمــا أن الفقــرة اخلامســة مــن العقــد نصــت علــى يف‬\n‫حالــة رغبــة الطــرف الثانــي بإخــاء املــكان املؤجــر عليــه إبــاغ الطــرف‬\n‫األول قبــل انتهــاء مــدة العقــد بشــهر علــى األقــل ‪ ،‬و يف حــال رغــب يف‬\n‫إخــاء العقــار قبــل نهايــة املــدة يلتــزم الطــرف الثانــي بســداد كامــل‬\n‫اإليجــار للســنه اإليجاريــة التــي يرغــب اإلخــاء خاللهــا ‪ .‬وألن املدعــى‬\n‫عليــه قــام بأعمــال يف العــن املســتأجرة بــدون إذن املدعــي أصالــة كمــا‬\n‫أن األعمــال التــي اســتأذن فيهــا لــم يقــم بعملهــا وفــق أصــول الصنعــة‬\n‫كمــا أنــه حينمــا رغــب إنهــاء العقــد لــم يقــم بإصــاح مــا تلفــه او قــام‬\n‫بتغيــره او مــا فقــد منــه قبــل الوقــت احملــدد وهــو ‪1433/9/1‬ه ـ وألن‬\n‫املدعــي أصالــة حينمــا امتنــع مــن اســتالم العــن حتــى يتــم اصالحــه أو‬\n‫دفــع تكلفــة اإلصــاح فــإن تصرفــه صحيحــا ألن ذلــك يحتــاج الــى وقــت‬\n\n\n                                                                                    ‫‪168‬‬\n\f      ‫وثمــن وهــو نتيجــة تعــدي او تفريــط مــن املســتأجر واملســتأجر اذا فــرط‬\n      ‫أو تعــدى يف العــن املســتأجرة ضمــن ينظــر كشــاف القنــاع ‪139/9‬‬\n      ‫وألن ممــا قررتــه هيئــة النظــر هــو عمــل نظافــة للموقــع وترويــب مواضــع‬\n      ‫التنديــة يف دورات امليــاه مببلــغ خمســمائة ريــال وألن هــذا مــن عمــارة‬\n      ‫العــن املؤجــرة وليــس الزمــا للمســتأجر ينظــر كشــاف القنــاع ‪. 109/9‬‬\n      ‫لذلــك كلــه فقــد حكمــت علــى املدعــى عليــه أصالــة بأن يدفــع للمدعي‬\n      ‫أوال‪ /‬تكلفــة اإلصالحــات و املفقــودات يف املبنــى التــي قدرتهــا هيئــة‬\n      ‫النظــر فيمــا عــدا تنظيــف املوقــع وترويــب مواقــع التنديــة يف دورات امليــاه‬\n      ‫مبلــغ وقــدره ســتة آالف وأربعمائــة وخمســة وأربعــون ريــال ‪ .‬ثانيــا ‪ /‬أجــرة‬\n      ‫املــدة التــي بــدأت يف ‪1433/9/1‬ه ـ مبلــغ وقــدره مائــة وســتة آالف ريــال‬\n      ‫وأربعمائــة وثمانــن ريــاال ‪ .‬ثالثــا ‪ /‬دفــع اســتهالك املــاء والكهربــاء حتــى‬\n      ‫‪1434/8/30‬ه ـ وأن علــى املدعــى عليــه أصالــة اخــاء املبنــى يف مــدة‬\n      ‫اقصاهــا ‪1434/9/1‬ه ـ وتســليمه للمدعــي أصالــة خاليــا مــن الشــواغل‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــي وكالــة القناعــة وقــرر‬\n      ‫املدعــى عليــه وكالــة عــدم القناعــة وطلــب رفعــه حملكمــة االســتئناف‬\n      ‫بعــد تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه مبراجعــة احملكمــة خــال‬\n      ‫عشــرة أيــام الســتالم صــورة الصــك وتقــدمي الالئحــة االعتراضيــة‬\n      ‫خــال ثالثــن يومــا مــدة االعتــراض فــإذا تأخــر ســقط حقــه يف طلــب‬\n      ‫االســتئناف واكتســب احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد مت عــادت املعاملــة من محكمة االســتئناف بشــرح‬\n      ‫فضيلــة الرئيــس برقــم ‪ 33/2150769‬يف ‪1434/11/18‬ه ـ علــى خطاب‬\n      ‫فضيلــة رئيــس محكمــة االســتئناف مبنطقــة مكــة املكرمــة املكلــف‬\n\n\n‫‪169‬‬\n\f‫برقــم ‪ 3321450769‬يف ‪1434/11/11‬ه ـ برفقهــا قــرار التصديــق‬\n‫مبوجــب القــرار رقــم ‪34349104‬يف ‪1434/11/4‬ه ـ وهــذا نصــه ‪-:‬‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ‪ ...........‬القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل‬\n‫بعــدد ‪ 34302116‬وتاريــخ ‪1434/8/22‬ه ـ املتضمــن دعــوى ‪...........‬‬\n‫ضــد شــركة‪ ...........‬واحملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكم ‪ .‬وصلى اهلل على نبينا محمد وعلى آله وصحبه وســلم‪ ،‬قاضي‬\n‫اســتئناف‪ ...........‬ختــم وتوقيــع قاضــي اســتئناف‪ ...........‬ختــم وتوقيــع‪،‬‬\n‫قاضــي اســتئناف‪ ...........‬ختــم وتوقيع‪،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/20‬ه ـ‬\n‫احلمــد هلل‪،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ‪ ...........‬القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل‬\n‫بعدد ‪ 34302116‬وتاريخ ‪1434/8/22‬ه ـ املتضمن دعوى ‪.....................‬‬\n‫ضــد شــركة ‪ .....................‬واحملكــوم فيــه مبــا دون باطنــه وبدراســة‬\n‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقة‬\n‫علــى احلكــم‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪170‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":147,"source_page_end":170,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2cade3311345afea8a0392708678903d5d5b1a1a1bcfa0a05df31037f4833d41","normalized_text_hash":"f5f5209bae2ab1ba19a20327002d840f91ff726b5bf1c5fa5345587ce518a06e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p147-34302116"},{"id":"7c239a48-5704-56cf-bfa4-f4be4409fbef","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -طلب إخاء عقار وقف -إجارة وقف مدة طويلة - ضرر متيقن الوقوع على عقار الوقف -إجازة فسخ ناظر الوقف لعقد األجرة -حكم بإخاء عقار.","document_number":"3435968","case_number":"33689238","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/22","year":"1434","subject":"عقد -إجارة -طلب إخاء عقار وقف -إجارة وقف مدة طويلة - ضرر متيقن الوقوع على عقار الوقف -إجازة فسخ ناظر الوقف لعقد األجرة -حكم بإخاء عقار.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/22 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3435968 :‬‬\n                         ‫َر ْق ُم الدعوى‪33689238 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34176955‬تاريخه‪1434/4/2 :‬هـ‬\n\n\n      ‫عقــد ‪ -‬إجــارة ‪ -‬طلــب إخــاء عقــار وقــف ‪ -‬إجــارة وقــف مــدة طويلــة ‪-‬‬\n      ‫ضــرر متيقــن الوقــوع علــى عقــار الوقــف ‪ -‬إجــازة فســخ ناظــر الوقــف‬\n                                          ‫لعقــد األجــرة ‪ -‬حكــم بإخــاء عقــار‪.‬‬\n\n\n\n\n                   ‫‪ .1‬قوله صلى اهلل عليه وسلم (( املسلمون على شروطهم ))‬\n                                             ‫‪ .2‬الضرر مرفوع يف الشريعة‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ناظــر وقــف ضــد املدعــى عليــه ومضمــون الدعــوى أن‬\n      ‫والــد املدعــي كان ناظــر وقفــه وقــد أجــره علــى املدعــى عليــه مــدة‬\n      ‫ثالثــن ســنة مــن ‪1422/1/1‬ه ـ بأجــرة ســنوية قدرهــا ألفــان وســتمائة‬\n      ‫ريــال وقــد ســلم املدعــى عليــه أجــرة الســنة األولــى والثانيــة وانقطــع عــن‬\n      ‫تســليم األجــرة لباقــي الســنوات وقــد تــويف والــده وان املدعــي هــو الناظــر‬\n      ‫وقــرر املدعــي أن العقــد املبــرم بــن والــده واملدعــى عليــه ينــص علــى أن‬\n      ‫العقــد ينفســخ عنــد عــدم ســداد األجــرة وطلــب املدعــي إلــزام املدعــى‬\n      ‫عليــه بإخــاء العقــار‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى‬\n      ‫ا ســوى تخلفــه عــن ســداد أجــرة الســنة الثالثــة فقــد ذكــر‬ ‫جملــة وتفصيـ ً‬\n      ‫انــه ســدد أجــرة الســنة الثالثــة ثــم تخلــف عــن الســداد الن والــد املدعــي‬\n\n‫‪171‬‬\n\f‫قــد تــويف وبســبب انشــغال ورثتــه وقــرر انــه غيــر مســتعد بإخــاء العقــار‬\n‫وانــه مســتعد بدفــع أجــرة الســنوات املاضيــة والقادمــة كمــا قــرر انــه‬\n‫تخلــف عــن ســداد األجــرة منــذ عــام ‪1427‬ه ـ وان املدعــي احلاضــر طالبــه‬\n‫يف عــام ‪1430‬ه ـ باألجــرة وانــه لــم يســتطع الســداد لظــروف مــرت بــه‪،‬‬\n‫عــرض ناظــر القضيــة الصلــح بــن الطرفــن وقــد تعــذر ذلــك‪ ،‬مت اطــاع‬\n‫ناظــر القضيــة علــى صــك امللكيــة وعقــد اإلجــارة‪ ،‬قــرر املدعــي نظــارة‬\n‫أن املدعــى عليــه تأخــر يف دفــع اإليجــار وانــه فســخ العقــد‪ ،‬قــرر ناظــر‬\n‫ـاء علــى مــا ســبق وملصادقــة املدعــى عليــه علــى تأخــره‬ ‫القضيــة انــه بنـ ً‬\n‫عــن دفــع األجــرة بســبب ظروفــه ولكــون املــدة ليســت بالقصيــرة فهــي‬\n‫تقــارب ســبع ســنوات ولكــون شــرط فســخ العقــد عنــد منــع األجــرة‬\n‫ثابــت بإقــرار املدعــى عليــه والن املســلمني علــى شــروطهم والضــرر‬\n‫مرفــوع يف الشــريعة وبقــاء املدعــى عليــه يف العقــار دون دفــع األجــرة‬\n‫ضــرر متيقــن الوقــوع علــى عقــار الوقــف لذلــك كلــه فقــد أجــاز ناظــر‬\n‫القضيــة فســخ املدعــي لعقــد األجــرة وإلــزام املدعــى عليــه بإخــاء العقــار‬\n‫محــل الدعــوى‪ ،‬صــدر قــرار محكمــة االســتئناف بالقصيــم باملوافقــة‬\n                                                                   ‫علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 33689238‬وتاريــخ ‪ 1433/12/19‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332182629‬وتاريــخ ‪ 1433/12/19‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/01/10‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 30‬‬\n\n                                                                                     ‫‪172‬‬\n\f      ‫وفيهــا حضــر ‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫بصفتــه ناظــر ًا علــى وقــف والــده ‪........‬مبوجــب الصــك الصــادر مــن‬\n      ‫هــذه احملكمــة برقــم ‪ 4/59‬يف ‪1428/5/27‬ه ـ وادعــى علــى احلاضــر‬\n      ‫معه‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬قائــا يف‬\n      ‫دعــواه عليــه إن والــدي ‪........‬كان قــد أوقــف األرض الواقعــة يف حــي‬\n      ‫‪ ........‬اململوكــة لــه مبوجــب الصــك الصــادر مــن محكمــة عنيــزة برقــم‬\n      ‫‪ 1/102‬وتاريــخ ‪1489/4/1‬ه ـ علــى أن تكــون النظــارة لــه مدة حياته ثم‬\n      ‫الصالــح مــن ذريتــه مــن بعــده وقــد أقمــت ناظــر ًا عليــه بعــد وفاتــه وذلــك‬\n      ‫مبوجــب صــك النظــارة الصــادرة مــن محكمــة عنيــزة برقــم ‪ 4/59‬يف‬\n      ‫‪1428/5/27‬ه ـ وقــد أجــر والــدي األرض حــال حياتــه للمدعــى عليــه‬\n      ‫ملــدة ثالثــن ســنة تبــدأ مــن تاريــخ ‪1422/1/1‬ه ـ بأجــرة ســنوية قدرهــا‬\n      ‫ألفــان وســتمائة ريــال دفــع املدعــى عليــه أجــرة الســنة األولــى والثانيــة‬\n      ‫ولــم يدفــع أجــرة الســنوات التاليــة وقــد نــص العقــد املبــرم بينهمــا علــى‬\n      ‫أن العقــد ينفســخ عنــد عــدم ســداد األجــرة أطلــب إلزامــه بإخــاء العقــار‬\n      ‫هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجاب قائــا ما ذكره‬\n      ‫املدعــي يف دعــواه مــن أننــي اســتأجرت مــن والــده العقــار املذكــور‬\n      ‫باملبلــغ واملــدة املذكــورة فصحيــح وأمــا قولــه إننــي لــم أدفــع ســوى أجــرة‬\n      ‫الســنة األولــى والثانيــة فغيــر صحيــح فقــد التزمــت بســداد األجــرة‬\n      ‫ثــاث ســنوات بعــد الســنتني األولــى والثانيــة ولــم أدفــع باقــي الســنوات‬\n      ‫لوفــاة والــد املدعــي والنشــغال ورثتــه وأمــا طلبــه إخــاء العقــار فأنــا‬\n      ‫غيــر مســتعد لذلــك ومســتعد بدفــع أجــرة الســنوات املاضيــة وااللتــزام‬\n      ‫بدفــع الســنوات القادمــة يف وقتهــا هكــذا أجــاب وبطلــب عقــد اإليجــار‬\n      ‫مــن املدعــي قــدم صــورة ورقــة هــذا نصهــا بســم اهلل الرحمــن الرحيــم‬\n\n\n‫‪173‬‬\n\f‫واحلمــد هلل وحــده حضــر عنــدي ‪........‬حامــل حفيظــة رقــم ‪........681‬‬\n‫مصــدر عنيــزة وتاريــخ ‪1385/5/23‬ه ـ وحضــر معــه ‪........‬حامــل حفيظــة‬\n‫رقــم ‪........‬مصــدر عنيــزة وتاريــخ ‪1396/11/10‬ه ـ وبعــد حضورهمــا‬\n‫أجــر ‪........‬بيتــه الواقــع ب‪ ........‬والــذي يحمــل صــك مــن احملكمــة‬\n‫برقــم ‪ 102‬وتاريــخ ‪1389/4/1‬ه ـ وذلــك علــى ‪........‬الســنة مببلــغ ألفــن‬\n‫وســتمائة ريــال ســعودي وملــدة ثالثــن ســنة ابتــداء مــن محــرم ‪1422‬ه ـ‬\n‫وقــد دفــع املســتأجر للمؤجــر حــق ســنتان مقــدم ويدفــع كل ســنة مقــدم‬\n‫مــن تاريخــه واالجــارة املذكــورة الصبــرة قادمــة بالبيــت ومــا يوضــع عليه‬\n‫مــن تعميــر ومنعهــا فســخ لهــا واشــترط ‪........‬أال يبيــع رغبــة اال مبوافقتــه‬\n‫هكــذا مت بينهمــا شــهد بذلــك ‪........‬حامــل حفيظــة رقــم ‪........‬مصــدر‬\n‫عنيــزة وتاريــخ ‪1402/2/9‬ه ـ وشــهد بــه كاتبــه ‪1424/1/23........‬ه ـ‬\n‫بصمــة املؤجــر ‪........‬بصمــه املســتأجر توقيعــه شــاهد وكاتــب ‪........‬‬\n‫توقيعــه وختمــه شــاهد توقيعــه انتهــى ويف جلســة أخــرى حضــر املدعــي‬\n‫الناظــر واملدعــى عليــه وقــد جــرى عــرض صــورة العقــد علــى املدعــى‬\n‫عليــه فقــال إن هــذا هــو العقــد الــذي تعاقــدت مبوجبــه مــع املوقــف والــد‬\n‫املدعــي وهــي صــورة طبــق األصــل هكــذا قــرر املدعى عليــه وقد اطلعت‬\n‫علــى صــك ملكيــة العقــار محــل الدعــوى فوجــدت أنــه صــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 1/102‬يف ‪1389/4/1‬ه ـ وهــذا هــو صحــة تاريخــه وقد‬\n‫حــرر التهميــش عليــه بالوقفيــة يف تاريــخ ‪1427/8/25‬ه ـ كمــا اطلعــت‬\n‫علــى صــك النظــارة فوجدتــه كمــا ذكــر املدعــي‪ ،‬وقــد ســألت املدعــى‬\n‫عليــه عــن الســنوات التــي تأخــر فيهــا عــن دفــع األجــرة فقــال كان‬\n‫والــد املدعــي مريضــا عــام ‪1427‬ه ـ ثــم تــويف يف عــام ‪1428‬ه ـ ولــم أســلم‬\n‫أجــرة العقــار منــذ كان مريضــا حتــى اآلن وقــد حضــر إلــي املدعــي‬\n\n\n                                                                                      ‫‪174‬‬\n\f      ‫عــام ‪1430‬ه ـ وطلــب منــي األجــرة وقــد كنــت أمــر بظــروف صعبــة ولــم‬\n      ‫أســتطع دفــع األجــرة لــه ولــم أدفــع شــيئا مــن األجــرة منــذ مــرض والــد‬\n      ‫املدعــي حتــى اآلن هكــذا قــرر املدعــى عليــه وقــد جــرت محاولــة الصلــح‬\n      ‫بــن الطرفــن فقــرر املدعــي بقولــه إن املدعــى عليــه تأخــر كثيــرا يف‬\n      ‫دفــع األجــرة وقــد فســخت العقــد وأطلــب إلــزام املدعــى عليــه بإخــاء‬\n      ‫العقــار هكــذا قــرر املدعــي فبنــاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n      ‫املتضمنــة طلبــه إخــاء املدعــى عليــه مــن العقــار الــذي اســتأجره مــن‬\n      ‫والــده والــذي أوقفــه والــده وأن ســبب الفســخ هــو تأخــر املدعــى عليــه عــن‬\n      ‫دفــع األجــرة وملصادقــة املدعــى عليــه علــى عقــد اإلجــارة والــذي ورد فيــه‬\n      ‫أن منــع األجــرة فســخ لهــا وملصادقــة املدعــى عليــه علــى تأخــره عــن دفــع‬\n      ‫األجــرة بســبب ظروفــه ولكــون املــدة التــي تأخــر فيهــا املدعــى عليــه عــن‬\n      ‫دفــع األجــرة ليســت بالقصيــرة فهــي تقــارب ســبع ســنوات حســب إقــرار‬\n      ‫املدعــى عليــه وقــد حصــل االمتنــاع عــن دفــع األجــرة بعــد مطالبــة املدعــي‬\n      ‫عــام ‪1430‬ه ـ بإقــرار املدعــى عليــه ولكــون شــرط فســخ العقــد عنــد‬\n      ‫منــع األجــرة ثابــت بإقــرار املدعــى عليــه وألن املســلمني علــى شــروطهم‬\n      ‫وألن الضــرر مرفــوع يف الشــريعة وبقــاء املدعــى عليــه يف العقــار دون‬\n      ‫دفــع األجــرة ضــرر متيقــن الوقــوع علــى عقــار الوقــف وملــا تقــدم كلــه‬\n      ‫فقــد أجــزت فســخ املدعــي لعقــد األجــرة املذكــور مــع املدعــى عليــه‬\n      ‫وألزمــت املدعــى عليــه بإخــاء العقــار محــل الدعــوى وبذلــك حكمــت‬\n      ‫وبعــرض احلكــم علــى الطرفــن قنــع املدعــي وقــرر املدعــى عليــه عــدم‬\n      ‫القناعــة وطلــب االســتئناف بالئحــة اعتراضيــة فجــرى تســليمه صــورة‬\n      ‫مــن الصــك هــذا اليــوم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا مــن‬\n      ‫تاريــخ اليــوم فــإن لــم يقــدم الالئحــة خاللهــا ســقط حقــه يف االســتئناف‬\n\n\n‫‪175‬‬\n\f‫واكتســب احلكــم القطعيــة وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                          ‫آلــه وصحبــه أجمعــن ‪ .‬حــرر يف ‪1434/2/12‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعنيــزة برقــم ‪ 33689238‬وتاريــخ ‪ 1433/12/19‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 332182629‬وتاريــخ ‪ 1433/12/19‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/04/20‬ه ـ افتتحــت اجللســة وقــد عــادت إلينــا‬\n‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪34176955‬‬\n‫يف ‪1434/4/2‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة «وبدراســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة قررنــا التصديــق علــى احلكــم» وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                 ‫حــرر يف ‪ 1434/04/20‬ه ـ‬\n‫احلمــدهلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n‫الثانيــة مبحكمــة االســتئناف مبنطقــة القصيــم علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة عنيــزة برقــم‬\n‫(‪ )332182629‬وتاريــخ ‪1434/3/22‬هــ؛ اخلاصــة بدعــوى ‪........‬ضــد‬\n‫‪........‬؛ بشــأن املطالبــة بخــاء عقــار؛ املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪........‬؛ املســجل برقــم (‪)3435968‬‬\n‫وتاريــخ ‪1434/2/12‬هــ؛ املتضمــن أن فضيلتــه أجــاز فســخ املدعــي لعقــد‬\n‫األجــرة املذكــور مــع املدعــى عليــه وألــزم املدعــى عليــه بإخــاء العقــار‬\n‫محــل الدعــوى وبذلــك حكــم؛ كمــا هــو مــدون ومفصــل فيــه وبدراســة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة؛ قررنــا التصديــق علــى احلكــم؛‬\n‫واهلل املوفــق؛ وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n                                                                                   ‫‪176‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":171,"source_page_end":176,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"94ef3cb5d4b1a6b094b91c400cb728dc3d3cb96e717e165951f4a6c8fc39e380","normalized_text_hash":"c43bf379d64354ecb1d715814656a7d1d18a30c66b5757aef7dea4d15261f6d6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p171-3435968"},{"id":"6f8991ff-6ee9-5a1b-8469-de30978f5549","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -إخاء عقار -إثبات اإلخطار باإلخاء عن طريق البريد املمتاز -العادة محكمة -الدليل إذا تطرق إليه االحتمال بطل به االستدالل -حكم بإخاء عقار.","document_number":"344846","case_number":"33700939","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالباحة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/26","year":"1434","subject":"عقد -إجارة -إخاء عقار -إثبات اإلخطار باإلخاء عن طريق البريد املمتاز -العادة محكمة -الدليل إذا تطرق إليه االحتمال بطل به االستدالل -حكم بإخاء عقار.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/2/26 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪344846 :‬‬\n                         ‫َر ْق ُم الدعوى‪33700939 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34217825‬تاريخه‪1434/5/20 :‬هـ‬\n\n\n      ‫عقــد ‪ -‬إجــارة ‪ -‬إخــاء عقــار ‪ -‬إثبــات اإلخطــار باإلخــاء عــن طريــق‬\n      ‫البريــد املمتــاز ‪ -‬العــادة محكمــة ‪ -‬الدليــل إذا تطــرق إليــه االحتمــال‬\n                                  ‫بطــل بــه االســتدالل ‪ -‬حكــم بإخــاء عقــار‪.‬‬\n\n\n\n\n                                       ‫‪ .1‬القاعدة الفقهية ( العادة محكمة )‬\n      ‫‪ .2‬القاعــدة الفقهيــة (الدليــل إذا تطــرق إليــه االحتمــال بطــل بــه‬\n                                                                 ‫اال ســتدالل)‬\n\n\n\n\n      ‫ا عبــارة عــن فتحتــن يف‬   ‫ادعــى املدعــي ضــد املدعــى عليــه انــه أجــره محـ ً‬\n      ‫عقــاره املوصــوف بالدعــوى ملــدة ســنة مــن تاريــخ ‪1425/7/17‬ه ـ مببلــغ‬\n      ‫ثمانيــة آالف ســنوي ًا ويتجــدد العقــد تلقائيـ ًا مــا لــم يخطــر احــد الطرفــن‬\n      ‫اآلخــر برغبتــه يف عــدم التجديــد قبــل نهايــة الســنة بخمســة عشــر يومـ ًا‬\n      ‫مبوجــب عقــد اإليجــار املرفــق صورتــه باملعاملــة وقــرر املدعــي انــه ابلــغ‬\n      ‫املدعــى عليــه باإلخــاء قبــل نهايــة العقــد بخمســة عشــر يومـ ًا عــن طريــق‬\n      ‫إرســال رســالة بالبريــد املمتــاز إال أن املدعــى عليــه لــم يقــم باإلخــاء‬\n      ‫وطلــب املدعــي إلــزام املدعــى عليــه بإخــاء العقــار‪ ،‬أجــاب املدعــى عليــه‬\n      ‫ا وصــادق علــى اســتالمه للبريــد‬    ‫باملصادقــة علــى الدعــوى جملــة وتفصيـ ً‬\n\n‫‪177‬‬\n\f‫املمتــاز وقــرر أن اإلرســالية تتضمــن زيــادة اإليجــار أو اإلخــاء وقــرر‬\n‫رفضــه للزيــادة كمــا قــرر انــه ســلم البــن املدعــي أجــرة الســتة أشــهر مــن‬\n‫الســنة اجلديــدة‪ ،‬حضــر ابــن املدعــي وأنكــر اســتالمه لألجــرة للســتة‬\n‫أشــهر اجلديــدة وقــرر أن هــذا املبلــغ هــو أجــرة حالــة للســنة املنتهيــة‬\n‫بتاريــخ ‪1433/7/13‬ه ـ بدليــل تســليمه لهــذا املبلــغ يف ‪1433/1/11‬هــ‪،‬‬\n‫ـاء علــى إقــرار املدعــى عليــه باســتالمه إلخطــار‬‫قــرر ناظــر القضيــة انــه بنـ ً‬\n‫طلــب اإلخــاء ومــا قدمــه املدعــى عليــه بشــأن تســليمه اإليجــار عــام‬\n‫‪1433‬ه ـ وانــه يعــد ذلــك جتديــد ًا للعقد محتمل أن يكون للســتة األشــهر‬\n‫األولــى لعــام ‪1433‬ه ـ كمــا أجــاب بــه ابــن املدعــي ويؤيــد ذلــك أن عــادة‬\n‫النــاس ومــا تعارفــوا عليــه بتســليم األجــرة بدايــة كل ســتة أشــهر وليــس‬\n‫مــن عادتهــم تســليم األجــرة للســنة املقبلــة قبــل ابتدائهــا والعــادة محكمة‬\n‫وإذا تطــرق االحتمــال بطــل االســتدالل كمــا أن اإلقــرار غيــر موقــع مــن‬\n‫املدعــي إمنــا مــن ابنــه ولذلــك فقــد صــدر احلكــم علــى املدعــى عليــه‬\n‫بإخــاء العقــار حــاال وافهــم املدعــي بــان لــه مطالبــة املدعــى عليــه فيمــا‬\n‫يخــص أجــرة الفتــرة مــن تاريــخ انتهــاء العقــد وحتــى تاريــخ اإلخــاء‪ ،‬مت‬\n ‫تصديــق احلكــم مــن محكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــد وبعــد فلــدي أنــا‬\n‫القاضــي يف احملكمــة العامــة بالباحــة وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بالباحــة برقــم ‪ 33700939‬وتاريــخ‬\n‫‪1433/12/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332228478‬وتاريــخ‬\n‫‪1433/12/25‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪ 1434/01/06‬ه ـ افتتحت‬\n\n                                                                                         ‫‪178‬‬\n\f      ‫اجللســة الســاعة التاســعة والنصــف وفيهــا حضــر ‪ ...........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...........‬وادعــى علــى احلاضــر‬\n      ‫معــه ‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪...........‬‬\n      ‫قائــا يف دعــواه عليــه أن مــن اجلــاري يف ملكــي وحتــت تصــريف األرض‬\n      ‫الواقعــة يف ‪........‬بالباحــة والواقعــة علــى شــارع ‪ ...‬والبالــغ قــدر مســاحتها‬\n      ‫اإلجماليــة أربعمائــة وثالثــون متــرا وخمســة وخمســون ســنتيمترا مربعــا‬\n      ‫واململوكــة لــي بالصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 286‬وتاريــخ‬\n      ‫‪1393/5/5‬ه ـ واملرفــق صورتــه باملعاملــة‪ ،‬وقــد أقمــت علــى األرض‬\n      ‫محــات جتاريــة دور واحــد وقــد قمــت بتأجيــر املدعــى عليــه احلاضــر‬\n      ‫محــل فتحتــن ملــدة ســنة اعتبــارا مــن بتاريــخ ‪1425/7/13‬ه ـ ومببلــغ‬\n      ‫ثمانيــة آالف ريــال لــكل ســنة‪ ،‬ويتجــدد العقــد تلقائيـ ًا مــا لــم يخطــر أي‬\n      ‫مــن الطرفــن اآلخــر برغبتــه يف عــدم جتديــده قبــل نهايــة الســنة بخمســة‬\n      ‫عشــر يومــا وذلــك مبوجــب عقــد اإليجــار املرفــق صورتــه باملعاملــة‪ ،‬وقــد‬\n      ‫اســتمر املســتأجر احلاضــر حتــى نهايــة العــام املنصــرم املنتهــي بتاريــخ‬\n      ‫‪1433/7/13‬ه ـ وقــد أخطرتــه برغبتــي بعــدم جتديــد العقــد للســنة التــي‬\n      ‫تبــدأ مــن تاريــخ ‪1433/7/13‬ه ـ وذلــك بإرســال رســالة إليــه بالبريــد‬\n      ‫املمتــاز يف شــهر ربيــع األول لعــام ‪1433‬ه ـ وطلبــت منــه إخــاء العقــار‬\n      ‫فــور انتهــاء الســنة املاضيــة إال أنــه لــم يخــل احملــل وال يــزال حتــى اآلن‬\n      ‫فيــه لــذا أطلــب احلكــم بإلــزام املدعــى عليــه بإخــاء احملــل حــاال هــذه‬\n      ‫دعــواي وبعــرض مــا جــاء يف دعــوى املدعــي علــى املدعــى عليــه أجــاب‬\n      ‫قائــا مــا ذكــره املدعــي مــن أننــي اســتأجرت احملــل املذكــور منــه ملــدة‬\n      ‫ســنة اعتبــارا مــن تاريــخ ‪1425/7/13‬ه ـ باملبلــغ املذكــور وأن العقــد‬\n      ‫يتجــدد تلقائيــا وأننــي مكثــت فيــه حتــى اآلن صحيــح ‪ ،‬ومــا ذكــره مــن‬\n\n\n‫‪179‬‬\n\f‫أنــه أخطرنــي بعــدم رغبتــه يف جتديــد العقــد لهــذه الســنة التــي تبــدأ مــن‬\n‫تاريــخ ‪1433/7/13‬ه ـ فغيــر صحيــح فلــم يصلنــي شــيء ‪ ،‬ولقــد ســلمت‬\n‫مبلــغ الســتة األشــهر األولــى لهــذه الســنة البنــه ‪ ...‬ومعــي إيصــال منــه‬\n‫بذلــك ولــذا فلســت مســتعدا بإخــاء العقــار قبــل انتهــاء العقــد بتاريــخ‬\n‫‪1434/7/13‬ه ـ هــذه إجابتــي وبســؤال املدعــي هــل لديــه بينــة علــى‬\n‫إخطــاره للمدعــى عليــه بعــدم رغبتــه يف جتديــد العقــد لهــذه الســنة أبــرز‬\n‫لنــا فاتــورة إرســال رســالة بالبريــد املمتــاز وباالطــاع عليهــا وجدتهــا‬\n‫تضمنــت اســم املرســل واســم املرســل إليــه ‪ ،‬ولــم يوضــح تاريــخ إرســالها‬\n‫وال صورة من األوراق املرســلة ‪ ،‬وبســؤال املدعي عنها أجاب بقوله إنني‬\n‫كبيــر يف الســن وال أعــرف القــراءة وقــد أمــرت ابنــي بإبــاغ املســتأجر‬\n‫بعــدم رغبتــي يف التجديــد فأخبرنــي أنــه بلغــه وأعطانــي هــذه الفاتــورة ‪،‬‬\n‫ومرفــق لكــم باملعاملــة صــورة مــن اإلخطــار هكــذا أجــاب وبالرجــوع‬\n‫إلــى أوراق املعاملــة وجــدت صــورة خلطــاب موقــع مــن موجــه مــؤرخ يف‬\n‫‪1433/3/29‬ه ـ متضمنــا إنــذاره باإلخــاء فــور انتهــاء مــدة العقــد‬\n‫املوافــق لتاريــخ ‪1433/7/1‬ه ـ انتهــى مضمونــه وبعرضــه علــى املدعــى‬\n‫عليــه أجــاب قائــا هــذه الورقــة املشــار إليهــا لــم أطلــع عليهــا إال اآلن ولــم‬\n‫يردنــي أي شــيء عــن طريــق البريــد هكــذا أجــاب فســألت املدعــي هــل‬\n‫لديــك مزيــد مــن البينــة فأجــاب قائــا أطلــب إمهالــي للجلســة القادمــة‬\n‫فأجيــب لطلبــه ورفعــت اجللســة إلــى يــوم الثالثــاء املوافــق ‪1434/1/27‬ه ـ‬\n‫الســاعة التاســعة والنصــف ويف املوعــد احملــدد افتتحــت اجللســة ‪ ،‬ويف‬\n‫هــذه اجللســة حضــر املدعــي واملدعــى عليــه وحضــر مــع املدعــي ابنــه‬\n‫حامــل الســجل املدنــي رقــم ‪ ،‬وبســؤال املدعــي ألديــك مزيــد بينــة أجــاب‬\n‫ا لــدي صــورة مــن إيصــال االســتالم للبريــد املمتــاز املرســل مــن قبلــي‬  ‫قائـ ً‬\n\n\n                                                                                          ‫‪180‬‬\n\f      ‫للمدعــى عليــه وموقــع علــى االســتالم مــن قبــل املدعــى عليــه بتاريــخ‬\n      ‫‪30‬ربيــع األول‪1433‬ه ـ ومبــن فيــه رقــم اإلرســالية املســتلمة واملطابقــة‬\n      ‫للرقــم املــدون يف الفاتــورة التــي قدمتهــا اجللســة الســابقة هكــذا قــرر‬\n      ‫وبالطــاع عليهــا وجدتهــا كمــا ذكــر وبعرضهــا علــى املدعــى عليــه‬\n      ‫صــادق علــى صحــة توقيعــه وأنــه اســتلم البريــد املرســل مــن املدعــي‬\n      ‫ا أن هــذا االخطــار الــذي اســتلمته كان مذكــور ًا فيــه‬              ‫وأضــاف قائ ـ ً‬\n      ‫طلــب زيــادة اإليجــار للســنة اجلديــدة التــي تبــدأ بتاريــخ ‪1433/7/13‬ه ـ‬\n      ‫وقــد اســتلمت هــذه اإلخطــار يف شــهر ربيــع الثانــي لعــام ‪1433‬ه ـ هكــذا‬\n      ‫ا اإلخطــار طلــب منــك زيــادة اإليجــار أو اإلخــاء عنــد‬        ‫قــرر فســألته قائـ ً‬\n      ‫ا نعــم ولكــن ملــاذا أزيــده ‪ ،‬علمــا بأنــه قــد‬‫انتهــاء مــدة العقــد أجــاب قائـ ً‬\n      ‫اســتلم املدعــي منــي إيجــار كامــل ســنة ‪1433‬ه ـ ولــدي إقــرار موقــع مــن‬\n          ‫إبــن املدعــي بذلــك هكــذا أجــاب ثــم أبــرز لنــا ورقــة مــن مطبوعــات‬\n      ‫مؤسســة ‪........‬للمقــاوالت العامــة وتضمنــت مــا نصــه « أقــر أنــا أننــي‬\n      ‫اســتلمت مبلــغ وقــدره ثمانيــة آالف ريــال مــن وهــو إيجــار البوفيــة الواقعــة‬\n      ‫يف ‪........‬ســنة ‪1433‬ه ـ واهلل ولــي التوفيــق «انتهــى نصهــا وبعرضهــا علــى‬\n      ‫ا هــذا املبلــغ إيجار الســنة املنتهيــة بتاريخ‬ ‫احلاضــر وســؤاله عنهــا قــرر قائـ ً‬\n      ‫‪1433/7/13‬هـ بدليل تاريخ تسليمه لهذا املبلغ يف ‪1433/1/11‬هـ وهو‬\n      ‫بدايــة الســتة األشــهر األخيــرة للســنة املنتهيــة يف ‪1433/7/13‬ه ـ وأمــا‬\n      ‫الســنة احلالية فلم نســتلم منه شــيء حتى اآلن ‪ ،‬وكيف أســتلم منه مبلغ‬\n      ‫الســتة األشــهر للســنة اجلديــدة دون زيــادة مــع إخبارنــا لــه ســابق ًا باإلخــاء‬\n      ‫هكــذا أجــاب وبعــرض جوابــه علــى املدعــي صــادق علــى صحتــه ‪ ،‬ثــم‬\n      ‫رفعــت اجللســة النتهــاء وقتهــا ودخــول وقــت اجللســة التــي تليهــا إلــى يــوم‬\n      ‫الثالثــاء املوافــق ‪1434/2/26‬ه ـ الســاعة التاســعة والنصــف ويف املوعــد‬\n\n\n‫‪181‬‬\n\f‫احملــدد افتتحــت اجللســة وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه‬\n‫مــع تبلغــه مبوعــد هــذه اجللســة يف ضبــط اجللســة الســابقة‪ ،‬وبعــد التأمــل‬\n‫يف مــا ســبق ضبطــه وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا‬\n‫قدمــه الطرفــان مــن أوراق ومبــا أن املدعــى عليــه أقــر باجللســة الثانيــة‬\n‫باســتالمه لإلخطــار املرســل مــن قبــل املدعــي املتضمــن عــدم رغبتــه يف‬\n‫جتديــد اإليجــار لســنة أخــرى بعــد إنــكاره الســتالمه يف اجللســة األولى‪،‬‬\n‫ومبــا أن العقــد نــص فيــه علــى أنــه يتجــدد مــا لــم يخطــر أي مــن الطرفــن‬\n‫اآلخــر بشــأن عــدم رغبتــه يف التجديــد‪ ،‬وقــد قــدم املدعــي ذلــك اإلخطار‬\n‫وأقــر املدعــى عليــه باســتالمه‪ ،‬ونظــرا إلــى أن مــا قدمــه املدعــى عليــه‬\n‫بشــأن تســليمه إليجــار احملــل لعــام ‪1433‬ه ـ كامــا املــدون نصهــا أعــاه‬\n‫وأنــه يعــد جتديــدا للعقــد محتمــل أن يكــون للســتة األشــهر األولــى لعــام‬\n‫‪1433‬ه ـ كمــا أجــاب بــه ابــن املدعــي احلاضــر باجللســة الســابقة ‪ ،‬ويؤيــد‬\n‫ذلــك االحتمــال أن عــادة النــاس ومــا تعارفــوا عليــه تســليم األجــرة بدايــة‬\n‫كل ســتة أشــهر‪ ،‬وليــس مــن عادتهــم تســليم األجــرة للســنة املقبلــة قبــل‬\n‫ابتدائهــا‪ ،‬والعــادة محكمــة‪ ،‬وإذا تطــرق االحتمــال بطــل االســتدالل‬\n‫كمــا قــرر ذلــك أهــل العلــم‪ ،‬إضافــة علــى أنهــا غيــر موقعــة مــن املدعــي‬\n‫وإمنــا مــن ابنــه‪ ،‬ولــكل مــا تقــدم فقــد حكمــت بإلــزام املدعــى عليــه‬\n‫بإخــاء عقــار املدعــي حــاال ويعتبــر هــذا احلكــم يف حقــه حضوريــا‪،‬‬\n‫وأفهمــت املدعــي بــأن لــه مطالبــة املدعــى عليــه فيمــا يخــص أجــرة‬\n‫الفتــرة مــن تاريــخ انتهــاء العقــد وحتــى تاريــخ اإلخــاء‪ ،‬وبعــرض احلكــم‬\n‫علــى املدعــي قــرر قناعتــه بــه وأمــرت ببعــث نســخة مــن صــك احلكــم‬\n‫للمدعــى عليــه لتمكينــه مــن االعتــراض عليــه خــال ثالثــن يومــا مــن‬\n‫اســتالمه لنســخة احلكــم وإذا لــم يتقــدم باعتراضــه خاللهــا ســقط حقــه‬\n\n\n                                                                                     ‫‪182‬‬\n\f      ‫يف االعتــراض واكتســب احلكــم القطعيــة‪ ،‬وختمــت اجللســة الســاعة‬\n      ‫العاشــرة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/26‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف يــوم‬\n      ‫األحــد املوافــق ‪1434/06/04‬ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــرة‬\n      ‫إال ربــع وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫برقــم ‪ 332228478‬يف ‪1434/05/28‬ه ـ وبرفقهــا قــرار التصديــق‬\n      ‫الصــادر مــن الدائــرة احلقوقيــة السادســة مبحكمــة االســتئناف برقــم‬\n      ‫‪ 34217825‬يف ‪1434/05/20‬ه ـ واملتضمــن بعــد املقدمــة مــا نصــه «‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر املوافقــة‬\n      ‫علــى احلكــم‪ ،‬وبــاهلل التوفيــق وصلى اهلل على نبينا محمد وآله وصحبه‬\n      ‫وســلم‪ ،‬قاضــي اســتئناف‪ ...........‬ختــم وتوقيــع‪ ،‬قاضــي اســتئناف‪...........‬‬\n      ‫ختــم وتوقيــع‪ ،‬رئيــس الدائــرة‪ ...........‬ختــم وتوقيــع انتهــى نصــه ‪ ،‬وللعلــم‬\n      ‫جــرى حتريــره‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                           ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/06/04‬ه ـ‬\n      ‫احلمــد هلل‪ ،‬والصــاة والســام علــى رســول اهلل‪ ،‬وبعــد ‪ :‬فق ــد ج ــرى م ّنــا‬\n      ‫نحـن رئيس وأعضاء الدائـرة احلقوقيـة السادسة يف محكمة االستئناف‬\n      ‫مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هذا احلكم الصادر من فضيلة‬\n      ‫الشــيخ‪ ...........‬القاضــي باحملكمــة العامــة بالباحة‪،‬واملســجل بع ــدد‬\n      ‫‪ 3448464‬وتاريــخ ‪1434/2/26‬هـ‪،‬املتضمــن دعــوى ضــد‪ ،‬احملكــوم‬\n      ‫في ــه مبــا دون باطــن الصك‪،‬وبدراس ــة احلكــم وص ــورة ضبط ــه والئحتــه‬\n      ‫االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‪،‬واهلل املوفــق‪ .‬وصل ــى اهلل‬\n                                        ‫عل ــى نبينا محمد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n‫‪183‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":177,"source_page_end":183,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4e4f47655152915710ed17ee5c1a767881592b32039b28903d384fbcf6c98b8a","normalized_text_hash":"1527654b1aa7a83538c21df8bc02820ca8821cb03c64df685d7a8469b88e564a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p177-344846"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
